/* 平成19年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h19.committeeSessions.push(...[{"id":"h19-20070731-14","meetingId":"h19-cm07","date":"2007年7月31日","dateIso":"2007-07-31","committee":"行財政改革特別委員会","time":"午後１時０３分～午後２時５０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"契約のあり方に関すること","agenda":"契約のあり方に関すること","exchanges":[{"speaker":"武内委員","kind":"質問","question":"ご説明いただいたモニタリング・評価ガイドラインはこれから始まるということでよろしいか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"実際、平成１９年度はモニタリング・評価という形ですが、平成２０年度以降は事業計画書等もこの様式を活用して運用していくという形になります。ですから、モニタリングの部分については、もう既に平成１９年度に入ってから各所管でそれぞれ作業を行っているです。","id":"exchange-001"},{"speaker":"武内委員","kind":"質問・要望","question":"それとも報告を予算・決算特別委員会に指定管理者の評価について報告を議会にもお願いしたいというお話があったのですが、それとも別の方法でお知らせいただくのか、その辺のところを教えてほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"それぞれの所管委員会もありますし、予算特別委員会、決算特別委員会もあります。やり方を整理しながら、何らかの形でと考えておりますが、もう少し検討させていただきお答えをさせていただければと思います。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区のどういう位置づけのものなのか、それに準ずるものなのか、その辺をご説明ほしいと求めました。それから、４１ページの品川区指定管理者制度活用に係る基本方針とどういう関係なのか。","respondent":"堀越行財政改革担当課長","answer":"策定にあたっては冊子の一番後ろに指定管理者の管理に対するモニタリング・評価システムの構築検討会委員名簿をつけてあります。基本方針との関係ですが、基本方針は品川区における指定管理者制度を活用していくかという部分の基本的な考え方を示したものです。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"いつ変わったかよくわからないで、いつの間にか変わっているという意見があるものですから、もう少し教えていただきたいと思ったのが一つです。具体的に説明があったところで、２ページ目ですけれども、具体的には何をどのように把握するのか教えてほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"評価についてですが、２９ページ以降に評価の実施方法という形で考えてあります。先ほども申し上げましたとおり、全庁的に検討会議を設けて策定いたしましたので、基本的なモニタリングの考え方として運用していくというものです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"サービス提供実態の把握につきましては、報告を受けながら履行されているかどうか確認する。本当に防ぐことができるのか、さらに工夫すべき点があると思っているのかどうか、その辺についての区の考えもあわせてご説明ほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"品川区においては、指定管理者と区のほうでコミュニケーションを図りながら、より良い施設の運営のために評価を行っていくという考え方です。こちらについては利用者からの意見ですとか、その中でしっかり履行されているかどうかについては…","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"事業計画書というのは区の公文書扱いになるのかどうか、区の係わるところのラインがよくわからないので、そこを教えていただきたい。５ページに評価結果についてるるご説明がありますけれども、議会への報告についてはどのように考えているのか教えてほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"先ほど別の委員のご質問にもお答えしたとおり、所管の常任委員会、また予算・決算特別委員会が基本であろうと考えております。モニタリング・評価を進めていく中で、初年度ということもございまして、これから検討していきたいと考えているところです。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"事業計画書の話がありましたけれども、同じように事業報告書とか総括シートの扱いについて教えてほしいと求めました。指定管理者として議決した議会側の責務もあるわけですから、１０月の中間評価の節目のところでは、これについてはいかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"基本的には指定管理者と協議を行いながら区が作成するものですので、同様の扱いになるかと思います。報告書に対して区としての考え方、全体的な一定の整理をどこでできるかという部分も含めて検討して、考え方を出していきたいと考えているところです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"例えば５月、６月に前年度事業報告書が提出されるわけですから、議会がチェックする機能があまりにも仕組みとして不十分だというのは感じます。４４ページの下のほうに、改めて指定管理者と品川区情報公開・個人情報保護条例の係わりについて、まずご説明いただけますか。","respondent":"堀越行財政改革担当課長","answer":"前回の委員会で千代田区のお話もありましたけれども、他の自治体において公募者に位置づけるのはどうかという議論もあります。区としてどのような対応を行っているかというところですけれども、情報公開の対応をしていくという形で、工夫しながら運用しているという考え方です。","id":"exchange-008"},{"speaker":"中塚委員","kind":"意見","question":"監査委員および議会と規定されていて、条文上、指定管理者がどこに入るのかよくわからないのです。今の条例と比べて、説明の中身とちぐはぐなので、そこをご説明いただけますかとの意見を述べました。","respondent":"堀越行財政改革担当課長","answer":"区のほうで保管する情報、基本的には品川区情報公開・個人情報保護条例に基づいて対応するという情報になるかと思います。併せて、指定管理者が保有している情報については、協議を行いながら対応していくという考え方です。","id":"exchange-009"},{"speaker":"中塚委員","kind":"意見","question":"実施機関の中に指定管理者が含まれてしまえば、品川区情報公開・個人情報保護条例に疑問はないのですけれども、含まれないわけですね。そこをもう少しわかりやすく説明いただけますかとの意見を述べました。","respondent":"堀越行財政改革担当課長","answer":"要するに公文書として位置づけているかどうかという部分ですので、千代田区においては実施機関と位置づけている形になろうかと思います。指定管理者だけが持っている情報の部分については、協議しながら対応していく部分ですので…","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"結局、指定管理者が持っている情報は、品川区情報公開・個人情報保護条例上は位置づけられていないということですか、そこが疑問点です。","respondent":"堀越行財政改革担当課長","answer":"協議しながら対応していくということですので、そのような対応をしているということですので、要するに含んでいないということになります。協定などで対応していくという、実質的にはそういった形で運用していくという、法人の独立性も考慮しながら工夫しているです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"今の説明の中では相手のさじ加減で公開できる、できないが決まってしまう余地が含まれてしまうのではないか。情報をしっかり公開させる仕組みづくりが確保されるべきではないか、今後の課題としてあるのではないかと思いますけれども、最後にいかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"ただ点数をつけるということではなくて、業務改善をしてサービス向上を図っていくということが基本的な考え方です。もう１点、先ほどご説明させていただきましたけれども、両面を見ながらモニタリング・評価ガイドラインの運用を図っていきたいと考えています。","id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"品川区の指定管理者制度の場合、官民競争入札は視野に入っていますか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"公の施設の管理を指定管理者を区が指定するものに対して行わせるということで、指定というのは地方自治法上の区分では契約ではございません。後ほどご説明しますが、契約の範疇には属しませんので、官民競争入札という概念は入ってこないという整理の仕方になろうかと思います。","id":"exchange-013"},{"speaker":"阿部委員","kind":"意見","question":"１点ですけれども、評価の基準をどういうところに持ってくるかというと、サービスに係わる部分が当然主体になってくると思います。していないとか、有給休暇の消化がどうなっているのか、評価の対象になっているかあるいは今後していくお考えがあるかどうか説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"労働関係の部分についてですが、そういった団体なりの雇用関係については、当然ながら法令順守をお願いするということは、当然の基本的な考え方です。ただ、会社が行うべきだと考えておりますので…","id":"exchange-014"},{"speaker":"阿部委員","kind":"確認","question":"確認ですが、労働環境については、区は特段チェックという形はしていかないということでよろしいですね。","respondent":"堀越行財政改革担当課長","answer":"細かい労働環境の部分について、今、例示を出された部分等につきましては、例えば労働関係の監督機関等が見ていくものだと。何か問題等があった場合は、事例に応じて対応していくことになろうかと思います。","id":"exchange-015"},{"speaker":"林委員","kind":"確認","question":"確認だけしたいのだけれども、全体的なことを区としてはもうこれででき上がったと考えているのか、その辺を聞かせてください。","respondent":"堀越行財政改革担当課長","answer":"指定管理者の管理に対するモニタリング・評価システムの構築検討会については一たん解散という形です。ただ、施設の所管する所管課と連絡会を持ちながら、必要に応じて見直しについては積極的に行っていくという考え方です。","id":"exchange-016"},{"speaker":"林委員","kind":"意見","question":"メンバーを見ると全庁的に、指定管理者を指定しているというか、所管の中に指定管理者と相対している部課長が入っているわけです。この冊子はだれに渡って、何の役に立つためにつくったのか、その辺を聞かせてくださいとの意見を述べました。","respondent":"堀越行財政改革担当課長","answer":"これをもとにしてそれぞれの手続に応じて変えていくものは変えていくという形でやっていくのが基本です。サービス向上に努めていただくという観点から、今後、品川区としての考え方を示していくということで配布していく予定でおります。","id":"exchange-017"},{"speaker":"林委員","kind":"質問","question":"役所の人たちがつくり上げたがんじがらめの牢屋の中に入れられているという感覚になりませんか。民間として生かしてほしいものを押さえつけてしまっているような気がしないでもないけれども、本当の目的を生かすという意味で、いかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"そういった点についてはなるべく簡素に、そういった視点から検討して、こういった形で策定したものです。指定管理者側の裁量の部分、今後、指定管理者側の意見も伺いながら見直し等に努めていきたいと考えているところです。","id":"exchange-018"},{"speaker":"林委員","kind":"質問","question":"皆さん方にとっては、自分たちが持っていないものを出してくれるんだという期待感を持って指定管理をやっているわけです。障子の桟のほこりを探していくようでは、非常に力が出し切れないと思うんだけれども、そういう話は所管課から上がってきていないか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"ただ、指定管理者側でみずからの判断でいろいろな取り組みをしていくことができるようになったことが、指定管理者制度の効果に挙げられると思います。新しい取り組み等について、評価して…","id":"exchange-019"},{"speaker":"林委員","kind":"質問","question":"指定管理の片方の大きい目標が何も遂げられていないことになるので、その辺はぜひ細かくというか、注意深くチェックしてほしい。そういうことについては、やってもらっている仕事は全部区のためなので、全部そういうとらえ方はしないと考えていいか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"事業計画の中で指定管理者からの提案を受けながら、サービス向上のためにやっていきたいというのが基本姿勢です。指定管理者側からの要望等もあるでしょうし、そういった部分を協議しながら区としても個別に柔軟に、適切に対応していきたいと考えております。","id":"exchange-020"},{"speaker":"林委員","kind":"提案","question":"５社が入ってきて、その提案は表に出せない会社の知的財産という関係があるから、それ以外のアイデアは表に出せないことになっている。せっかくその会社を指定管理者として指名したわけですから、そういうところもこの先きちんと区としての考え、いかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"この制度の趣旨を生かしていけるような形で、必要に応じて見直しといいますか、そういった部分についても検討していきたいと思います。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"この辺で三段階の主体とそれ以外のところの関係がどのようになっていくのかお伺いいたします。それから、９ページのインセンティブの考え方という言葉がよくわからないので用語の説明と、先ほど中身を飛ばされたので内容を説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"協議を行いながら実施していくとしていますので、意見・要望を受けて、これについては基本的に実施していきたいと考えているところです。サービス向上に向かっての努力を促すような一つの手法です。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"雇用形態の改善の方向もこの中で行っていけるのかどうか、労働条件に係わるところも聞かせてほしいと求めました。標準額に対してどうなのかということにおいて、経営努力で余剰報酬が与えられるのかどうか、この辺の考えも説明を求めました。","respondent":"堀越行財政改革担当課長、福田企画部長","answer":"合理的な説明がつくような形でなければならないと思います。経営努力に係わらないような利益を与えてもいけませんし、標準額というのは適切かつ慎重に判断していく必要があると考えております。 しかしながら、モニタリング・評価ガイドラインの３３ページが一番わかりやすいでしょうか、区はどうでもいいという考えは持っておりません。さらに「安全確保への取り組み」がございまして、利用者…","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"原則、やむを得ない場合には所定の手続きを経てこれを認めることとしています」ということですけれども、この辺が３３ページにも係わってくるのです。前にもお伺いしたのですけれども、賃金の問題とか、再委託先についての管理ができるのかどうかお伺いしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"区のほうに書面によって報告をいただいて、それによって承認するような形の手続きを経て再委託という形になってくると思います。再委託の業務にもよると考えなければならないと思いますが、人員の部分で言えば、実態について把握していくような形になろうと思います。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に委託先までに及んだところの情報が文書できちんと得られるのかどうかということが、今、そこのところは文書で求めたら出てくるのか。事前に情報公開で求めたら、そこの文書が出てくるのかどうか、その辺を再度お伺いしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"３３ページにありますとおり、安全管理、サービス向上という部分で再委託先の管理についても適切に行うという形で考えているところです。文書の扱いですけれども、区が保有している形については、品川区情報公開・個人情報保護条例に基づいて対応するという形になろうかと思いま…","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"そのとおりにいくと法人の独立性に及んでくるので、協議をするというご答弁だったので、そこと同じになるわけですか。ここにおいてもストレートに出ないという解釈でいいか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"一定、区が保有するその部分の文書については、品川区情報公開・個人情報保護条例に基づいて対応していく形になろうかと思います。それ以外の文書の部分については、個別に応じてといいますか、協議の中で対応していくような部分になろうかと思います。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それ以外は協議ということで、まだはっきりしない部分が現状では残っているという認識でよろしいですか。行政で一生懸命やられるのは当然であって、基本方針ではなくて議会にかける条例という形にしてほしいと求めましたが、いかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"その際、基本方針についてもご報告をさせていただいたと思いますので、適切な時期にご報告をさせていただいているものと考えております。基本方針の条例化のお話がありますが、設置条例に定めておりますので… 公共サービス改革法を受けた公共サービス改革基本方針、官民競争入札実施要項の審議等を行うものです。民間事業者の適正かつ確実な実施を確保ということで、確保すべき公共サービスの質については、実施要項で明確化するです。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"今の説明は、それとも品川区は国と足をそろえて考えが同じですということなのか、説明の趣旨がよくわからない。品川区が何かやりたいことでもあるのか説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"今、そういった部分についてどのような形で効果的にできるのかというのは、一定の検討が必要ではないかと考えています。本日は、公共サービス改革法についてご説明させていただいた次第です。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のお話の中で、いつぐらいからどのような中身の検討が行われていたのか教えてほしいと求めました。品川区が担っている役割の中で、具体的に何を考えているのか、もう少し教えていただけますか。","respondent":"堀越行財政改革担当課長","answer":"品川区としての基本的な考え方を申し述べさせていただいた次第でして、戸籍関係について検討していると申し上げたものではございません。民間企業側の市場が成熟してきておりますし、社会経済状況の変化や周囲の環境も見極めながら…","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"質問しても具体的な話が出てこなくて、何か考え方と考え方みたいな空中論にしか聞いていて思えないのです。先ほどからの説明ですと、具体性に欠けるので、２点ご説明ください。","respondent":"堀越行財政改革担当課長、福田企画部長","answer":"法律の概要についてご説明させていただいたとおり、ただ簡素化という形ではなくて、区としても先ほど来説明させていただいているとおりです。全体的には、そのような形で認識しているものです。 効率性、もう一つ一番大事なサービスの向上を目的といたしまして、さまざまな民間委託事業を実施してまいりました。それからもう一つ、事故ですか命ですか、それと行政の簡素性、効率性の二つを比較したことはございません。","id":"exchange-030"},{"speaker":"中塚委員","kind":"意見","question":"結局、何も出てこないのです。やはり、私は事態がうまくいっていない表れではないかと言わざるを得ませんとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"１点だけお聞きしたいのですが、官民競争入札は実際に品川区では既に行われていることなのか、これからのことなのか、もし行われているのであれば、件数を教えてほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"品川区においては官民競争入札の実施例はございません。国においても、民間競争入札は実施しておりますが、官民競争入札の実施例については、私のほうでは聞いてございません。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/471723?Template=document&Id=5822#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":27827,"voices":76}},{"id":"h19-20070801-16","meetingId":"h19-cm08","date":"2007年8月1日","dateIso":"2007-08-01","committee":"街づくり特別委員会","time":"午後１時０３分～午後５時１９分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"地区計画に関することのうち、八潮地区","agenda":"地区計画に関することのうち、八潮地区","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"その検討会でどういうところを目標にしているのかなというのと、どういうところまで詰めていこうと考えているかということ、どのようなリンクというか関係になっていくのかなというのをちょっとお伺いしたいなと思います。","respondent":"日下部企画財政課長","answer":"実はそのときに、具体的に検討の部会ですね、どういうような今申し上げたような共通認識を持ってまちづくりの検討を進めていったらいいのか。このような形で検討会が組織されておりますし、これは逐次またこの委員会の中でご報告をする、このように考えているところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"２点なんですが、どういうふうなものと考えているのかということと、それをどのように確保する地区計画というものを考えていくのかなと。そういうのをちょっとお伺いしたいのと、あと、あと今後要望が出てきた場合というのはどのように対応されるのかなというのをお伺いしたいと思います。","respondent":"青木都市開発課長、日下部企画財政課長","answer":"今の団地が、団地特有の問題として高低差があってタクシーが寄りつけないとか、いろいろな課題があることは事実です。これから皆さんと話し合っていきたいというふうに考えております。 非公式ではありますけれども、いろいろ例えば学校関係で跡地の活用ができないかというような、そういう照会が何件か非公式には来てあります。そういう観点からも非常に有意義な取り組みをしている…","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"今後そういった有意義な活動をされている団体ですとかが要望が続々と寄せられる可能性もありまして、ほかの団体とかの要望があるのかなと思うんですけれども、そこら辺だけもう一度お願いしたいのですが。","respondent":"日下部企画財政課長","answer":"それに対する対応ということで今いろいろご説明していますが、それについては、またケース・バイ・ケースで対応するということになろうかと思います。龍の子と品川総合福祉センターということでありますが、その辺については十分にまた検討を進めていきたい…","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"ではとりあえずそういった地域からの要望があれば、入れる余地もあるということですか。スペース的には龍の子さんと福祉センターだけで手いっぱいというわけではないようなんか尋ねました。","respondent":"日下部企画財政課長","answer":"その辺はしっかりと受けとめて、具体的にどうするかはまたもう少し整理が必要ですが、最大限活用できるようなことも考えていきたい。このように考えてあります。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"５０代前後ということなんですが、再生というんでしょうか、こういう意見の聴取というものは何か場を設けているのか。たぶんいくんでしょうけれども、それはどういうふうに議論を進めていくのか、それも教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"検討会ですけれども、その辺、私どもとしましてもその辺は検討会とは連携協力してということで進めていこうということを確認しておりますので。で中長期の視点で検討すべき課題、これから地域の方々と一緒になって検討を進めていきたい、このように考えております。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう検討会であってほしいなと思っていますので、アドバイザー的な形で、このかかわりを模索されると思います。やはりそれを広げていく、もうちょっと夢のあるような、そういう雰囲気づくりをぜひ目指していただきたいなと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"なるほどなというふうに思って伺いましたけれども、ちょっとその辺の状況を含めて教えていただきたいなというふうに思っているんです。この２点です。","respondent":"青木都市開発課長","answer":"起債の償還が終わっていないとか、いろいろな他の条件があって、学校を廃止した事例もまだ一団地の中では厳密にはないというふうに聞いています。それぞれ似たような事例はあるけれども…","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、個別の問題にどうしても入っていきがちなところがありますので、助言をする必要があるのかなということを改めて強く思いました。その辺については、品川区もこれからどういうふうな形でこれと同じような状況が出ないとは限らない中で、改めてちょっと伺いたいと思いました。","respondent":"青木都市開発課長","answer":"民間の事業者を入れて、いわゆる分譲マンションであるとか賃貸住宅であるとか、多様な供給主体に任せるということを進めております。長期的な課題になると思うんですけれども、八潮団地についてもそのような事例を参考に…","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"皆さん、そこら辺のところは十分にやっていってほしいと思いますので、もう一度そこら辺の考え方というのも地域の住民の方と話していただきたい。そこら辺をちょっとまず先に教えていただきたい。","respondent":"青木都市開発課長、日下部企画財政課長","answer":"では、先ほどのご説明の中で平成２１年度には八潮南小中で仮開校した小中一貫校が真ん中の八潮小中に戻っていくということで想定していますので。平成２０年の夏ごろには… 委員がさっきおっしゃいましたように制度的な面での取り組みというのを抜きにはできませんので、これからあそこは住宅の関係事業者が５社あります。より実現性の高い方策も含めてどうあるべきかということで…","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう先は、日にち的にはもう迫っているんだから、そこら辺の考え方がどうなのかなというのが１点。買いやすい店にしてほしいというのは思いがあるんだろうと思うけれども、現実、そこら辺のことの考えをもう一回教えていただきたい。","respondent":"岩田まちづくり事業部長","answer":"先ほど課長がご説明しましたように、幸いなことに八潮団地はまだ築２３年から２５年ですから、建て替えの問題はまだまだ一世代先の話になります。それの５社、ありますので…","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうすると今言ったパトリアにしても何にしても、そういう部分も、おのずと決まってくる部分があるじゃないですか。ぜひ行政側もそういう意味合いがあるならば、そこら辺のところも含めて話していただければなと、これは要望にしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"食事も一緒にしちゃいましょうよというような、やはりそういう購買行動ですか、その辺も仕組みとして考えていくべきじゃないかなと思うんです。ファミリー層の方しか入れないという年齢枠というんですか、そこに住んでいなければ、その辺についてのお考えはどう思われますか。","respondent":"日下部企画財政課長","answer":"そう簡単なことではありませんし、いろいろ検討も進めていければなと、そのように考えているところです。そういった意味では、そういうような形を一つ考えていくのも、お互いにこれからいろいろ意見交換も含めて進めていきたいというふうに思っております。","id":"exchange-012"},{"speaker":"渡辺委員","kind":"提案","question":"先ほど質問が出ていましたが、どうしても、現実は難しいと思うんですね。先ほどメールの２件のご提案も非常に建設的な提案があって、こういうことが今後もケースとして可能かどうか、ご質問と要望として伺いたいと思いますとの意見を述べました。","respondent":"日下部企画財政課長","answer":"ほっとしているところですけれども、いずれにしましても毎月１日には「やしおだより」を全戸配布で、すべての世帯にこれを投函しているわけです。そしてまた一方で、地域のご意見も、このような形でお寄せいただくということをさらにきめ細かく進めていきたい…","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"住んでいる人が１万３,０００人以上ですから０.２％ぐらいということで、実際に足を運んでやろうという人はまだまだ少ないのかなという気がします。ビルについてはまだあと２５年ぐらいはそのままの状況だ、その中でやることを考えているのかということを、１回お聞かせ願いたいと思います。","respondent":"日下部企画財政課長","answer":"活性化に向けた取り組みを進めていったらいいのかということが、その点についての共通認識というのは、これからやはり議論の中でもう少し詰めていく。検討会は２６名、熱心な方が参加をされていますけれども、非常に大勢の方が…","id":"exchange-014"},{"speaker":"浅野委員","kind":"意見","question":"今満足しているけれども、例えば５年たったら全然意見が変わる場合もあると思うんですね。この２５年なんとかもつような、活性化のある八潮のまちづくりにしていかなければいけないのかなと思いますので、これは意見としてお話ししますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"スケジュールの件が出たものですから関連して質問させていただきたいんですが、理想を目指して地区計画というのが、失礼いたしました。住民の意見を踏まえた上で地区計画の縛りを変更というか、そういう手続に入るということでよろしいんか尋ねました。","respondent":"青木都市開発課長","answer":"それともう１点、それに間に合わせるようなスケジュールは私どもとして設定をしておきたいということでご説明申し上げております。ですので、ほかに使いたいことが決まった段階で間に合わないということがないように手続を進めていきたいということでご説明しておりますので。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"ということは、先行的にまず地区計画のほうを変更するということはないということなんか尋ねました。","respondent":"青木都市開発課長","answer":"ある意味で、想定される範囲でフリーハンドは持ちたいわけですよね。将来を考える中でいろいろなことに対応できるような、先に地区計画、それは皆様のご議論の中で決まっていくことだと考えています。","id":"exchange-017"},{"speaker":"安藤委員","kind":"意見","question":"私もちょっと勉強不足で本当に申しわけないんだけれども、規制問題というのは変わらないけれども、用途を変える。明確に差があるというか、規制としてはだいぶ変わってしまうような気がするんですけれども、ちょっと懸念があるんですよねとの意見を述べました。","respondent":"岩田まちづくり事業部長","answer":"地区計画の変更という形でそのときには考えていただければいい。それから、先ほど言いましたように、用途、容積を基本的には変更するつもりはございませんので、建築紛争が当面起きるということも考えられない。","id":"exchange-018"}]},{"id":"topic-02","title":"旧東海道南品川三丁目地区地区計画","agenda":"旧東海道南品川三丁目地区地区計画","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"どうしてこういうことを聞くかというと、駆け込み、例えば今、駆け込みでというのは、逆に言うと、いつまで建築確認をおろすかというのを聞きたい。この条例改正が行われる日までは確認行為はおりるのかどうなのか。","respondent":"阿部都市計画課長、片田建築課長","answer":"１０月に都市計画決定をしたあと、そのあと条例の改正になりますので、その辺の日程を考えております。今建築中のものを含めて５棟です。 ご理解をいただいて、この制限条例が当然予定されているわけですから、そのようなご説明はさせていただきたいと思います。ここについては、それに基づいて単に小さくするということは残念ながら…","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは要望も含めて理解なんですが、これ以上あまり言うと、答弁もいいです。ぜひこの今５棟あるという話がありましたけれども、私も言いますけれども、ぜひ言っていただければなと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"これは理解できる話だと受けとめて伺っていましたけれども、４階以上のものが建っているところで、この規制が当然かかるわけですよね。その辺についてはどういうふうに考えておられるのか、ちょっとそこを伺いたい。","respondent":"阿部都市計画課長","answer":"私どもも説明会の中では、地区計画は街区で囲まれた範囲で考えるものですという説明をしておりまして、皆さん参加者の方に対しても。ただ、その中では、そういう話はなくて、現在、地区の中で進められてきたこの沿道沿い２０ｍの中でいくという確認をその説明会の中でしたです。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"当然その説明を伺って、それだったらいいだろうということで合意された、こういう意味で受け取っていいんですか。今の質問とちょっと裏腹なんですけれども、この２０ｍの範囲に限らずに、その辺をもう一度最後に質問したいと思います。","respondent":"阿部都市計画課長、岩田まちづくり事業部長","answer":"区が、そういうことも含めて地域の方々が検討して、区に地区計画の策定の要請書を出していただいたということです。まずはこの現在の地区計画のルールがこの地域の権利者の方々が中心となってご自分たちで考えたという前提がありますの… 区内では中原街道沿道についての、あれは公害防止型の地区計画なんですけれども、その制度でやっております。地区計画はいろいろなものがありますので、また機会をつかまえましてご説明をします。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"それはそれとして了解というか、同意の点では３分の２同意だとかいうことがあるというふうに聞きますけれども、その点についてはどうなんでしょうか。先ほどの説明では１月の時点で、ちょっとその辺の同意との関係で、どういうふうになっているのかというのを伺いたいと思います。","respondent":"阿部都市計画課長","answer":"その賛同書に署名なされた数ですけれども、割合ですけれども、この２０ｍの地区に居住する権利者の方については約７割の賛同です。ただ権利者の方はこの地区外にも当然いらっしゃいますので、そういう方を含めますと約５５％の割合で賛同承認を得ているです。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"今はいいんだけれども、そういう意味での不利益が生じては禍根を残すルールになっちゃうのかなと、ちょっとその辺が心配だったので伺ったんです。じゃ、差し支えなければぜひちょっとその辺のご意見も伺いたいと思うので、教えていただける部分があったら教えてほしいと求めました。","respondent":"岩田まちづくり事業部長","answer":"その土地の形状とか位置によって決まってくるものですので、だいたいプラスマイナスゼロぐらいの延べ床面積が確保されるという説明です。制限を受けることはないだろうということを判断をいたしまして、区の案として地域にお示しする、こういうものです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"署名の実数というのを教えていただきたいのと、その権利者というのは具体的にどういった方を指しているのかお伺いしたいと思います。お願いします。","respondent":"阿部都市計画課長","answer":"その思いを具体化するために今回の地区計画を考えて検討してきたですので、そういう内容の熱い思いの趣旨をいただいております。今回の提案説明会の権利者です土地の所有者、そのほか、抵当権者等の土地に関する権利を有している方です。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"１点だけすみません。７割の方と、あとほかを含めると５５％ということで合意が得られているということだったんですが、抵当権者の方を指しているんか尋ねました。","respondent":"阿部都市計画課長","answer":"今回の原案の説明会の対象には抵当権者も含まれますけれども、借地権者の方が権利者として該当しますので、その方々からの賛同を得た。賛同書が出たです。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/823348?Template=document&Id=6348#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":45957,"voices":70}},{"id":"h19-20070803-8","meetingId":"h19-cm08","date":"2007年8月3日","dateIso":"2007-08-03","committee":"建設委員会","time":"午前１０時０１分～午後４時５０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"の区営自転車等駐車場利用料の一部改定","agenda":"の区営自転車等駐車場利用料の一部改定","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"指定管理者との関係ですけれども、指定管理者の委託料はこれを受けて変わるというか、その辺の変化について教えていただけますか。","respondent":"松嶋交通安全担当課長","answer":"５％の増加を見込んでおりますので、収入は確保する予定でおりますけれども、来年度は下げる予定です。ただ、見合った委託料を検討していかなければならないということでございまして、完全に下げるということを言っているわけではございません。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"意見","question":"逆に言ったら、そこで努力してもらうということも出てくるわけで、その辺の考え方だけは明確にしておかないと、その辺の考え方をしっかりやらないと。連動するのかしないのかとの意見を述べました。","respondent":"岩田まちづくり事業部長","answer":"駐輪場の場合は利用料金制度を取っておりませんので、利用料はストレートに全部区に入ります。受託事業者は逆にこれで利用者が増えれば、仕事が大変になるわけですから、そういう面では基本的には委託料の変化はないものと考えております。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"根拠として、ただ利用率が低いからということで下げるということならば、周りに放置自転車が多いのか。例えば、その辺もあると思うんですが、このまま料金を下げなければ放置自転車が一向に減らないということが前提としてあるのか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"利用率の引き下げにつきましては、ご指摘のとおり、例えば旗の台駅第１駐輪場につきましては、使い勝手が若干悪いということがあります。天王洲アイル駅第１駐輪場と品川シーサイド駅駐輪場につきましては、放置自転車が多いから引き下げるということではございません。","id":"exchange-003"},{"speaker":"井上委員","kind":"提案","question":"平均利用率が３０％ということで、線引きをしたのかどうかを確認したいということと、ほかのところでそういう利用率がまだあるのかということが一つ。大崎駅の例を示して料金制度を改定すべきだということを提案していたので…","respondent":"松嶋交通安全担当課長","answer":"立会川駅駐輪場とか青物横丁駅駐輪場等がありますので、新馬場駅駐輪場を下げることは、時期尚早ということで考えてあります。定期利用の検討ですけれども、自転車の自粛を考えておりまして、定期利用の検討はしていないところです。","id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"要望です。健康だとか自粛ということは別の問題として考えていくべきだと思いますので、そこも視野に入れて検討してほしいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"阿部委員","kind":"質問・要望","question":"要望に近いですけれども、置いてはいけませんというのは見かけるのですが、ここに駐輪場がありますというのはあまり多く見かけないのです。今回値下げするわけですから、新たに使ってもらえないわけですから、何か考えていただきたい。","respondent":"松嶋交通安全担当課長","answer":"ご指摘のとおりでございまして、使っている人に安くしても利用率は上がりませんので、特に駅に料金を引き下げるという掲示をしたいと考えているところです。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"その中で結構故障したものが２年前には多くあり、直してくださいという要望があるけれども、現状はきちんと直されているのか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"故障の部分につきましては耳に入っておりませんので、早急に確認いたします。","id":"exchange-007"}]},{"id":"topic-02","title":"の平成１９年度「道の日」クリーンキャンペーンの実施","agenda":"の平成１９年度「道の日」クリーンキャンペーンの実施","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"この前、別件の報告事項であったが、８月１０日がもし土曜日、日曜日だったら、月曜日にやると考えていいのかということを説明を求めました。","respondent":"松嶋交通安全担当課長","answer":"８月１０日は全国的に「道の日」ということで、１０日に決められておりますので、土日であっても１０日にやらざるを得ないと考えております。","id":"exchange-008"}]},{"id":"topic-03","title":"の首都高速道路中央環状品川線五反田出入口工事説明会の開催","agenda":"の首都高速道路中央環状品川線五反田出入口工事説明会の開催","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"同時に、対応策はどういうことを考えているのかということ。もう１点、何年ぐらいの工期になるのか説明を求めました。","respondent":"阿部都市計画課長","answer":"ただ、実際真正面が工事になる場合もありますので、その場合には商店に対しても十分配慮して、出入口に差し支えないようにやると聞いてあります。工期は先ほど申し上げましたけれども、平成２５年２月までです。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の話ですと、自分の店の前が長い期間工事をされるわけですから、影響がないということはないと思うんです。ぜひ、近隣の方々への状況を伺いながら、進めてほしいと求めました。","respondent":"阿部都市計画課長","answer":"今、申し上げましたとおり、まずは拡幅用地として空地になってあります。その後、出入口確保については十分配慮していくと首都高速道路(株)が申していますので、ご指摘があったということは事業者に伝えていきます。","id":"exchange-010"},{"speaker":"井上委員","kind":"質問・要望","question":"今回始められるのは入口と書いてあるところの工事があって、また次に何年か経った入口トンネルとか、区間ごとに工事を始めるということでしょうか。それから、平成２５年まで６年間というのは、工事完了が平成２５年なのか、その辺のところをお願いします。","respondent":"阿部都市計画課長","answer":"全体の工期ですけれども、今回の工期は平成２５年２月までですけれども、全体の中央環状品川線の工期は平成２６年３月竣工予定です。今回の工事については、平成２５年２月までです。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問・要望","question":"この日のほかに週末に１回ぐらい説明会があってもいいのではないかということは、区から要望などを出していらっしゃいますでしょうか。一切、そういう話はなくて、１回限りで十分であるということか尋ねました。","respondent":"阿部都市計画課長","answer":"説明会は１回ですけれども、私どもから要望があれば出向いて説明してほしいという申し入れはしています。","id":"exchange-012"}]},{"id":"topic-04","title":"の大崎駅周辺地区まち運営組織の設立","agenda":"の大崎駅周辺地区まち運営組織の設立","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"こうした形でのまち運営組織というのは、品川区で初めてのケースになるのかどうか教えてください。先ほどの話ですと、駐輪場の話が出ていましたけれども、どの部分に委託料を払うのか説明を求めました。","respondent":"青木都市開発課長","answer":"２番目としまして、年度末までの５カ月間で３カ所を含めまして約２,０００万円ぐらいになるだろうと試算しております。すべて管理運営について、通常の施設の維持管理すべてを含むということでご理解いただきたいと思います。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"どの部分に委託料を払うのかというのがよくわからない。それともこの部分に委託するからその金額が設定しているのか、幾らでどの部分に設定するのか教えていただけますか。","respondent":"青木都市開発課長、岩田まちづくり事業部長","answer":"地下駐輪場ですから明かりが必要ですし、エレベーターも動きますし、当然料金徴収業務も生じています。そういったものすべてを含めて、この会社を通じて管理運営をお願いするものです。 駐輪場の維持管理の業務を委託する。駅前広場であれば清掃とか樹木の植栽の業務を委託する、そのようにご理解をいただきたいと思います。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"この駐輪場は区営駐輪場という位置づけですね。その先には区営駐輪場で指定管理者で他のところは改定しましたけれども、その後はどういうふうにされていくのか尋ねました。","respondent":"青木都市開発課長","answer":"当面は中間法人を通じて管理をお願いしまして、区の施設を委託管理してもらうという形になっていきます。利用状況等を踏まえて、管理運営あるいは利用実態などを踏まえて、将来的な課題として時期を見計らって移行していきたいと考えております。","id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"今のご説明の中には、メンテナンスの話が多かったと思うんですけれども、まちづくりとか地域活性化とかもありまして、具体的にどういうことをやっていこうかというのは、設置後に始めていくのですか、それともある程度青写真があるのか尋ねました。","respondent":"青木都市開発課長","answer":"例えば地元で町会がやっているまちおこしなどに対しても、何らかの支援あるいは協働という形での取り組みがあると思いますし、独自の事業としては。現在は公共施設の管理からスタートしますけれども…","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"要望だけしておきます。行政側がしっかり線引きをしていかないと、周りの残っている部分もあるわけですから、その辺の兼ね合いも必ずあるわけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"}]},{"id":"topic-05","title":"の避難通路（滝王子通り）機能強化に関する説明会","agenda":"の避難通路（滝王子通り）機能強化に関する説明会","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"なぜ、道路拡張ありきなのか、震災対策というのだったら、ほかにやるべきことがあるのではないかという意見が強かったと思うんです。説明の中で道路を広げなければいけない根拠が乏しいという質問に対して、区はどのように考えているのか教えてほしいと求めました。","respondent":"伊勢住環境整備担当課長","answer":"当日のご質問に対する回答は、この説明資料あるいはパンフレット等で説明しましたけれども、なかなかわかりにくいというようなところを感じておりましたので、今後、説明会を実施するときは、その辺も含めて、もっとわかりやすいような形で説明をしていきたいと考えております。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"大火が起きないような住宅の不燃化や耐震化を進めることこそ一番大事ではないかという意見が強かったと思うんです。参加者といろいろ話を聞きましたけれども、実際に２時間かけて避難しろというけれども、それについてはどのように考えているのか説明を求めました。","respondent":"岩田まちづくり事業部長","answer":"時間がございませんので、骨子だけご説明いたします。これは道路を広げるだけではなくて、周辺の建物の不燃化、そういったものとすべて総合的な対策として地域の方にご提案をしているものです。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/325823?Template=document&Id=3884#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":14011,"voices":69}},{"id":"h19-20070803-5","meetingId":"h19-cm08","date":"2007年8月3日","dateIso":"2007-08-03","committee":"総務委員会","time":"午後１時０２分～午後５時１５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件整理しています。","topics":[{"id":"topic-01","title":"の１、報告事項について聴取をしてまいります。 初めに、(1)基本構想等の策定状況","agenda":"の１、報告事項について聴取をしてまいります。 初めに、(1)基本構想等の策定状況","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"その回、その回の策定委員会での投げかけをどういうふうに考えておられるのかというのをお聞きしたいのと、それとさっきのアンケートですか。回収数が２,８５９件とありまして、これはどういう意味合いを持つのか、そこを教えていただければ。","respondent":"福島長期計画担当課長","answer":"信頼度９５％の誤差を求める回答比率、回答比率５０％の質問で、プラス１.２５％になります。回答比率５０％、±１.２５％で、９５％以内に入り込んでいるというものです。","id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"３４万区民のうち回答されたのが２,８５９人という、これで分析に、要するに分析に耐え得る標本数という規定がどうしてできるのか。これがどうして要するに区民の意識の問題として分析に耐え得る標本数だと確保ができているというふうに規定できるのかというのがわからないところな…との意見を述べ…","respondent":"福島長期計画担当課長","answer":"当初の回収率は４０％ぐらいだろうというふうに見込んで、逆に６,０００件というのを見込んだのが、２,０００件回答が来れば分析が可能だろうです。計算を出すことはあるんですけれども、そこまで私も説明しきれませんけども、数として十分耐え得る数字だと考えています。","id":"exchange-002"},{"speaker":"浅野委員","kind":"質問","question":"今在留の外国人向け放送局と伺ったんですけれども、聴取率というんでしょうか、どのぐらいの方が聞かれているのかなというのを一つお伺いしたい点と。８カ月間、来年の３月まであるんですけれども、そこら辺の基準をお伺いしたい。","respondent":"中川原広報広聴課長","answer":"ちょっと次の試行のご質問にも答えることになるかと思いますが、この時間帯がどうなのかということも含めて、試行の中で検討したいと考えています。３分間にどのような内容が流せるのか、また、ひいては災害時の情報提供手段としての有効性を検討したいと思ってあります。","id":"exchange-003"},{"speaker":"浅野委員","kind":"確認","question":"これはちょっとこれに関連するかどうかわからないところがあるんですけども、そこは今日本語以外というのはやっているんでしょうか。あれはちゃんと機能しているかどうかを確認するために流しているんですけれども、この四つの言葉ですね、教えてほしいと求めました。","respondent":"中川原広報広聴課長","answer":"日本人向けだけでございまして、外国人については、この間対応はやっておりません。災害放送につきましては、東京都のほうで放送局と協定を結びまして、東京都として災害情報を外国人向けに発信することになっております。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"今の災害情報の話なんですけども、こういう放送で呼びかけるのと避難所で対応できるかどうかという、連動するんでしょうか。そこだけ教えていただけますか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"菊地委員","kind":"意見","question":"避難所でこういう言葉しかわからない皆さんが、もしこういう災害対策の情報を聞かれて避難をされたときに、区として対応ができるのかどうかというのはとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"}]},{"id":"topic-02","title":"に移ります。区政６０周年記念事業「ちょっと素敵なしながわのまち」写真コンクール","agenda":"に移ります。区政６０周年記念事業「ちょっと素敵なしながわのまち」写真コンクール","exchanges":[{"speaker":"浅野委員","kind":"質問・要望","question":"前回もあったというふうに伺っているんですけども、今回どのぐらいを想定されているのかということを教えていただきたいんですが。インターネットで公開するということですが、ふだんのアクセス数というんでしょうか、わかる範囲で教えてほしいと求めました。","respondent":"中川原広報広聴課長","answer":"「Ｗｅｂ写真館」のアクセス数が、３月にオープンしましたので、今いろんな感想とか情報をお寄せいただいている状況です。品川区のホームページ自体は毎月１０万件を超えるアクセスなんですが、そろそろとりたいと考えています。","id":"exchange-007"}]},{"id":"topic-03","title":"続きまして、(4)品川南ふ頭公園電気設備工事請負契約","agenda":"続きまして、(4)品川南ふ頭公園電気設備工事請負契約","exchanges":[{"speaker":"武内副委員長","kind":"質問","question":"ほかのＪＶなんかでもやっぱり落札予定価格に近い形で１億２,０００万円台で応札してきている企業が多いんですけれども、今回落札できた東陽・日建ですか、なぜこんなに安くできたのかというところを。","respondent":"中島経理課長","answer":"具体的に「おたく、東陽電気工事の企業体につきましては、この種の工事を得意としている事業者というのが大きな要素だと思っています。それから、この間、この企業は、品川区の受注が少なかったということがございまして、気合を入れた入札というふうに私ども考えてあります。","id":"exchange-008"},{"speaker":"武内副委員長","kind":"質問","question":"こちら、品川区側がお願いしている内容は着実に、金額だけじゃなくてクリアされているということなんでしょうから、しっかりお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問・要望","question":"どこに設置されるのかということと、あと、(1)の高圧受変電設備は、このキュービクルの中に含まれるのか。たぶんアンプはそこじゃなくて、例えば管理棟とか、ちょっと教えていただきたい。","respondent":"中島経理課長","answer":"２点目から先にご説明いたしますけれども、高圧受電盤と照明関係ですけど、それはこちらの今委員ご指摘のとおりキュービクルの中に設置されるです。申しわけございません。","id":"exchange-010"}]},{"id":"topic-04","title":"参議院議員選挙の投開票結果","agenda":"参議院議員選挙の投開票結果","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"内容的には問題は別にどうこうはないんですけど、ただ一番最初に出ている、ちょっとよくわからないんですけど、事務用品のカード決済というのは、コピーやなんかを使うときに、個人の職員がすることを書いてあるんですかね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/495406?Template=document&Id=1756#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":31137,"voices":67}},{"id":"h19-20070827-6","meetingId":"h19-cm08","date":"2007年8月27日","dateIso":"2007-08-27","committee":"区民委員会","time":"午後１時０３分～午後 ４時５４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"番の報告事項","agenda":"番の報告事項","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"素案ですから策定したと思うんですけど、こういう改訂案に至ったのかというのをお伺いしたいのと、説明会の開催とかの予定はないのかということもあわせてお伺いしたいと思います。","respondent":"久保田防災課長","answer":"１つは、図書館等でもごらんいただけるように、そういう形でのご案内をする予定にしています。いろいろなところでの説明会というお話ですけれども、このホームページなり、説明会の開催は考えてございません。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"より積極的にという意味では、やっぱり顔と顔を突き合わせたりとか、私は個人的にはそう思ったんですけれども。１回目の防災会議で素案を提示して話し合う、委員の構成は計５７名ということで、５７名中どれぐらいいらっしゃるのかなというのをお聞きしたい。","respondent":"久保田防災課長","answer":"薬剤師会、建設防災協議会、トラック協会ということで参加しています。持ち寄ってこの会議の中で検討をするというのが主になってありますので、それに対してまちの意見として先ほどの方々を含めて意見をいただいて。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"あるいはどういった声が出ているのか、どういうふうに聞いているのかというのがもし具体的にあれば、教えてほしいと求めました。","respondent":"久保田防災課長","answer":"区民の意見を聞くということで先ほどから説明しているパブリックコメントを行い、あるいは聞いていくということでやっているものだと考えております。防災に対しての考え方、あるいはそういうものについてお聞きしながら…","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"普段から町会単位を中心につくっている組織なので、町会とは普段からおつき合いがあって、こういう中で意見を取り入れるというお話ですけれども、このマニュアルといいますか、素案をつくる上で、そのテーマで話し合ったりとかというのはしたんか尋ねました。","respondent":"久保田防災課長","answer":"ごらんのとおり、地域防災計画というのはこれだけ膨大な、広範囲なものですので、ある１つの部分について物を聞くとか何とかというのはなかなか難しゅうありますので、全般的な意見、あるいはお話なり何なりの中で、私どもも吸い上げるものは吸い上げていくです。","id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"意見","question":"先ほどのご説明の中で、品川区の独自の地域性というのは、どのようにとらえていて盛り込まれているのか。以前に既に出ている部分でも、区の独自的な地域性というのをどういうふうにとらえて盛り込もうとしているのか、その点を１点説明を求めました。","respondent":"久保田防災課長","answer":"上位計画というふうに説明しましたけれども、都の計画あるいは国の計画と十分に調整をとってやっていく計画だということかなと考えております。それから、戸越公園一帯周辺の事業の考え方あるいは目標もここに掲げて…","id":"exchange-005"},{"speaker":"飯沼副委員長","kind":"提案","question":"１つには、たびたび提案をしているわけですけれども、耐震補強のところと家具転倒防止のあたりはいかがでしょうか。ぜひぜひ盛り込んでいっていただきたいんですけれどもとの意見を述べました。","respondent":"久保田防災課長","answer":"耐震改修促進計画については今、鋭意検討中ですので、ここの中ではその程度のお答えしか今のところはできないと考えています。今、いろいろな形で進めるべきだろうなと考えていまして、実は先週も土曜日に防災アドバイザー研修というのを実施したんですが。","id":"exchange-006"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"そういった意味で、さっきの地域説明会を開いてほしいというのは、私もその思いは大変強いです。その点はぜひやっていってほしいなと思うのと、見ればわかるという方向にぜひぜひしていっていただきたいなと思いますが、いかがか尋ねました。","respondent":"久保田防災課長","answer":"いろいろな防災情報をわかりやすく知ることができる、我が家の防災ハンドブックというのを今検討しております。この中には今出ていた防災地図とか何かも盛り込みまして、そういう情報を伝えていきたいと考えております。","id":"exchange-007"},{"speaker":"山路委員","kind":"質問","question":"３畳の部屋にベッドが置いてあって、１０月の地震の新しい速報というんですか、新しいのは。そういうところは検討されたことがあるかどうか、説明を求めました。","respondent":"久保田防災課長","answer":"今後これを普及をかけていくにあたって、実際それをどういうふうに使いこなせるかということが問題になってくるのかなとは思っているところなんです。２階のほうにも展示していますし、連携して、あるいは紹介みたいなものも検討していきたいなと考えております。","id":"exchange-008"},{"speaker":"山路委員","kind":"質問・要望","question":"ですから、求める人の自由、圧倒的に改修をやりたいけどできないという人が多いんですよ。その点はどう考えていらっしゃるんか尋ねました。","respondent":"久保田防災課長","answer":"今、確かにおっしゃったとおり、この防災ベッドにしてもシェルターについても、そういう点ではまだまだのものかなと考えています。東京都のほうもそういういろいろな考え方を出してきていますので、その辺は研究しながら、よりいい方法を今後とも見つけていきたいと考えています。","id":"exchange-009"},{"speaker":"山路委員","kind":"質問・要望","question":"困っている人がたくさんいるわけですから、不安な人が、高齢者でお１人で木造住宅に住んでいる方が。モデルにやって、多くの区民に知っていただくというのがこれから大事になってくるんじゃないかと思いますので、私はそれを要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"稲川委員","kind":"質問","question":"丸井も男の館と２つあるんですけれども、両方がヤマダ電機になってしまうんか尋ねました。","respondent":"金子産業振興課長","answer":"そのように聞いております。","id":"exchange-011"},{"speaker":"稲川委員","kind":"質問","question":"この情報に関してなんですけど、一般的にヤマダ電機さんが入るということは随分前から決まっていたんじゃないかなと、地域の人からもそういう話があったし、ヤマダ電機が求人広告も出していたという中で、ちょっと委員会報告がおくれているような気がするんですが、その辺はどうか尋ねました。","respondent":"金子産業振興課長","answer":"私どもが現段階で得た情報としては、契約が成立したのがあくまでも８月２３日、先週の木曜日のことですので、そういう意味ではそれが一番確実なところであるというところから出発しているものだと思います。","id":"exchange-012"},{"speaker":"山路委員","kind":"質問","question":"丸井からヤマダ電機にかわるということなんですけど、区のほうに相談というか、区はどこまで介入をしているんか尋ねました。","respondent":"金子産業振興課長","answer":"これはご案内のとおり、今までは丸井さんが所有していた部分と地権者から借りていた部分で丸井の店舗というのを構成していたわけですね。大井町のにぎわいを損なわない方向で、大型の量販店を今後の入居者として考えているということでしたので…","id":"exchange-013"},{"speaker":"山路委員","kind":"意見","question":"区民になじみの深い歴史のある場所であったので、丸井からヤマダ電機へ移ったからどうこうというわけじゃないんですよ。全体、区民の人に喜ばれるようにアドバイスしていただきたかったという意見があったんですけど、その辺はどういうふうに思われますかとの意見を述べました。","respondent":"金子産業振興課長","answer":"そういう意味ではまちの活力を低下させないで、よりにぎわいを高めていく場所だと考えていますので、今回は私どもとしては望ましい方向ではないかと考えています。","id":"exchange-014"},{"speaker":"山路委員","kind":"質問・要望","question":"現状ではそういう方向じゃないかと思うんですけど、区民の方が旧公会堂があった歴史的な場所ですので、きゅりあんの周辺は、品川区もこの辺は気を配って、区民に喜ばれる街づくりをお願いしたいということを言われましたので、この委員会でご要望だけ申し上げておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点だけ確認します。丸井がファンドに売却した、それはファンドに売ったのは、丸井の所有物と地権者から借りているその権利も一緒に売ったということか尋ねました。","respondent":"金子産業振興課長","answer":"詳細な情報につきましては、現段階では入手しておりませんので、その辺についても今後入手していきたいと考えております。","id":"exchange-016"},{"speaker":"飯沼副委員長","kind":"質問","question":"旧公会堂があって、ほんとうに大事な場所にあるので、大型店が入るということへの地元への影響も大変大きいと思うんです。区商連とか、その辺で影響が大きいんですけれども、そういう話し合いとかご相談とかというものはなかったんか尋ねました。","respondent":"金子産業振興課長","answer":"そういう意味では、今後仮に問題があるとしても、これからの問題であろうかと考えています。当然のことながら、大井町のまちのにぎわい、あるいはさまざまな支障が出ないような形で対応するように今のところ考えているところです。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"要望なんですけれども、大型量販店なものですから、車の流れが相当変わるんじゃないかと思うんですね。その辺をよく、もちろん向こうに対しても要望すると同時に、区のほうも考えておいていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"川西委員長","kind":"確認","question":"前回の委員会で確認をいただきました調査項目、いずれの視察先につきましても今のところ内諾をいただいております。〔「異議なし」と呼ぶ者あり〕。","respondent":"川西委員長","answer":"後日になりますが、日程等が確定いたしましたら、お手元に行程表等を配付します。なお、９月の委員会で調査項目についての勉強会を行いたいと考えております。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/598842?Template=document&Id=2494#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":22360,"voices":44}},{"id":"h19-20070827-7","meetingId":"h19-cm08","date":"2007年8月27日","dateIso":"2007-08-27","committee":"厚生委員会","time":"午後１時０３分～午後３時３２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"幼保一体施設について説明していただくのは初めてだと思うんですけれども、幼保一体ということでどのような施設になるのかお聞きしたいと思います。荏原西地区の幼保一体施設であれば、保育園は新たにできるのか、幼保一体施設の基本的なことについて教えていただけないか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"品川区が進めている幼稚園、平塚小学校がこちらに移転するということで、それに伴って平塚幼稚園も一緒に移転します。品川区は０歳から就学までの幼児教育を進めているところで、保育園と幼稚園との連携の施設にしたいと思っているところです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで言えば、そこに０歳から３歳までの保育園が新たにできるという資料も併せてつけていただいて説明にしていただきたい。それから、資料について、今後の要望に対してもお願いしたいと思います。","respondent":"高橋幼保一元担当課長","answer":"第５次と第６次の総合実施計画中に第一日野と平塚での幼保一体施設は入っているところですが、本委員会に報告をさせていただいているところです。同時にそちらに移るということで…","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"そうしますと、４・５歳児は荏原西地区であれば平塚幼稚園が移転する。それにプラスして０歳児から３歳児までの認可保育園が新たに２カ所できるということで確認させていただいてよろしいか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"今の段階では新たに０歳から３歳までの認可保育園を建設する予定です。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私たちも認可保育園をぜひつくってほしいということを、本当に評価をしたいし、うれしく思っています。資料の要望として、時期を入れた資料にしていただきたいということを、一つ要望させてほしいと求めました。","respondent":"高橋幼保一元担当課長","answer":"今年度の１２月には実施設計が完了し、来年度に議会等に説明しながら、平成２２年度に開校予定です。カリキュラムについて検討していますが、やはり品川区でどういった乳幼児教育を進めるかということは、ある一定の線が必要かと思っています。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ある程度、基本設計の段階で、議会にももっと早い時点で報告をしていただきたいということを要望させてほしいと求めました。それから、設計に対しては現場の声が入っているのか、このことについてもお聞かせほしいと求めました。","respondent":"高橋幼保一元担当課長、古川児童保健事業部長","answer":"今回の荏原西地区について、０歳から１４歳までの初めての取り組みであるということで、品川区総合実施計画に出しています。基本設計、実施設計に向けて現場の職員、平塚幼稚園の園長等を含めて検討しているところです。 先ほど担当課長が申し上げましたように、第６次総合実施計画でも打ち出していますけれども、今回の実施設計を平成１９年度に実施することについては。２１年度に工事を行う予定であるということで…","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もっと早い時期に説明していただきたいし、きちんと中身がわかるような資料で説明していただきたいということを要望させてほしいと求めました。今、残っている園に関してはすべて０歳から３歳児までの区立認可保育園をつくっていくという考え方でいいのでしょうか、このことだけ確認をします。","respondent":"古川児童保健事業部長","answer":"可能性があれば計画化に持っていきたいと考えていますけれども、個々の幼稚園を見ると難しい幼稚園もあるだろうと思います。若干そういった面は違ってくるだろうと思っていますので、必ずしも９園すべてということにはならない場合もあるだろうと考えております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、今回二つの認可保育園が０歳から３歳児までが増設となるわけですけれども、それ以外のところで保育園の増設計画ではっきりしている部分はあるのか、そこだけ説明を求めました。","respondent":"小林保育課長","answer":"その辺につきましては、また計画がある程度、目鼻がついた時点で適宜ご報告をさせていただきたいと考えています。","id":"exchange-007"},{"speaker":"堺委員","kind":"質問・要望","question":"３歳までの部屋も決まっているようですが、受入れ枠は数字として出ているのですか、あるいはこれから数字を出していくのか。１００％というか、２人を同じところに何とか入れていただけるように、もし数字が出ているようであれば教えてほしいと求めました。","respondent":"高橋幼保一元担当課長、小林保育課長","answer":"私からはこの２施設においての認可保育園の人数枠、規模についてご説明したいと思います。特に、幼児につきましては、４歳・５歳児につきましては１クラス５３m2で３５人という部分がありますので、それは確保しています。 タイミングがずれてしまって、バラ措置になってしまう場合もあります。やはり１人よりも２人、３人、バラ措置の解消に向けて努力してまいりたいと考えています。","id":"exchange-008"},{"speaker":"堺委員","kind":"質問","question":"４階に０歳、１歳、２歳とありますけれども、小さい子どもが高いところで保育される安全面というのは大丈夫なのかどうか。それから、小さい子どもはエレベーターか何かで行ったり来たりするようになっているのでしょうけれども、エレベーターはどこにあるんか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"説明が不十分で申し訳ありません。エレベーター等については保育園施設にはございませんが、ほかの施設ではエレベーター等での上下の行き来ができるようになっています。","id":"exchange-009"},{"speaker":"堺委員","kind":"質問","question":"３階の平面図で、保育園が３歳・４歳・５歳児が入るところがちょうど１階部分だということですね。０歳・１歳・２歳児が１階にストレートの部分で、３歳・４歳・５歳児が２階部分という方が安全なのかと思ったんですが、それはどうなんか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"例えば、砂が保育室に入らないということもございまして、品川区では一般的に２階施設でしたら０歳・１歳・２歳児を２階に持ってきているところです。多分、他区もそのようなところが多いかと思います。","id":"exchange-010"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"少し確認をさせてほしいと求めました。２歳児１０人となって、１１０人ぐらいの規模ということですが、幼稚園の部分は今の定員はそのまま移行するということでいいのか尋ねました。","respondent":"高橋幼保一元担当課長","answer":"学校教育法で３５人が１学級ということがありますので、その部分も考慮して、地域周辺の需要に合わせて変更する可能性も出てくるということですので。今後、実施設計をする中で、周辺の需要度もあわせながら、その辺の決め方は考えてまいりたいと思いますので…","id":"exchange-011"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"ちなみに、おそらく前の委員会で説明があったかと思うんですけれども、その辺のところの説明をほしいと求めました。先ほど、今後の計画はないという説明だったんですけれども、もう一度その考え方をお聞きしたいと思います。","respondent":"小林保育課長","answer":"その他中延保育園、荏原西保育園まで３００ｍ、こういった周辺の保育園施設とのバランスで地域需要を充足していくという考えに立っております。今後、実施計画の中で、周辺の保育園の状況も含めて精査して定員を具体的に定めてまいりたいと考えております。","id":"exchange-012"},{"speaker":"宮崎副委員長","kind":"質問","question":"そうしますと、定員はこれから周りの状況などもということですけれども、今の説明ですと、かなり余裕を持ったつくりになっているお話です。最大を取っているともう少しのびっこ園台場より大きくできると思うんですけれども、そういう意味での余裕を持ったつくりになっているのか尋ねました。","respondent":"高橋幼保一元担当課長、古川児童保健事業部長","answer":"今回の施設については、０歳が６人のスペースに４６m2を確保して、３.３m2で割りますと６人以上入れる受け入れ枠があるという考え方です。基本はのびっこ園台場ですけれども… ご案内のとおり平塚中学校の敷地１万m2少しありますが、かなり厳しい中で算段しながら約１,０００m2を生み出そうということです。できるだけ余裕をと申し上げましたのは…","id":"exchange-013"},{"speaker":"宮崎副委員長","kind":"質問","question":"質問は変わりますけれども、構造上で心配な点が２点あります。音の対策はどのように考えて対策を取っているのか、お聞かせほしいと求めました。","respondent":"高橋幼保一元担当課長、古川児童保健事業部長","answer":"どのようなものになっているのかここではお話できませんけれども、保育園部分につきましては、建物自体は鉄筋コンクリートで進めております。幼保の部分の３・４・５歳児の下は調理室になってございまして… かなりこれは工夫をいたしまして、荏原西地区小中一貫校・幼保一体施設については、正直なところ私どもの考え方が反映された図面と思ってあります。私どもも間違いなく実施していくところですが、なお教育委員会とその点につきましても…","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地域への説明会をぜひやっていただきたいと思うんですが、予定があったら説明を求めました。","respondent":"高橋幼保一元担当課長","answer":"今後、地域説明会をするかどうか、教育委員会と連携して進めてまいりたいと思います。今の時点ではいつ実施するということは決まってございません。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私も途中から出させていただきましたけれども、その中でも地域の声をぜひ聞いてほしいということで、たくさん意見が出されていました。そこに幼保一体施設が入ってくるということでは、ぜひ教育委員会を含めて地域の説明会を開く方向でご検討をほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"宮崎副委員長","kind":"意見","question":"今までお年寄りの関係だと８０２０運動とか確かあったような気がするんですけれども、そういうものはこういうときには全く関係ないのでしたか。私もしばらく厚生委員をやっていなかったので、わからなかったんですがとの意見を述べました。","respondent":"太田健康課長","answer":"ただ、区政６０周年記念のイベント事業との関係がありますので、表彰自体は１２月１５日の記念イベントの中で今年度は実施する予定です。なお、予定ですけれども９月中旬から１０月中旬ぐらい、１カ月にかけて応募期間ということで設けるという動きです。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この制度はこれから受ける方が対象ということで、今現在品川区でも不動産がありながら生活保護を受けている方がいらっしゃると思うんですけれども、そういう方は移行しなくていいということか尋ねました。","respondent":"志村生活福祉課長","answer":"単独の所有でないと、この制度が活用できませんので、自己所有ができるような手続を進めてくださいというような指導は行ってあります。国からしますと、今、受給されている世帯の中で、この要件に該当するものについては制度を活用するようにということになってあります。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"５００万円は超えていると思うんですけれども、強制的に生活保護が打ち切られて社会福祉協議会からお金を借りて生活するようなところに改めなさいということにならないといいなと思っているんですけれども、その辺のところはいかがか尋ねました。","respondent":"志村生活福祉課長","answer":"これは非常に判断の難しいところで、評価額５００万円以上の土地建物の自己所有です。５００万円以上にならないと、なかなかそこまでいかないのではないかと、現場の者としてはそのように考えてあります。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その方は借地権ですので、よかったです。それが１.５倍を超えてしまうことも場合によってはあるのではないかと思うんですけれども、その辺はどのように保障されていくのか説明を求めました。","respondent":"志村生活福祉課長","answer":"これの１.５倍ですから、大体１８万円ぐらいとお考えください。貸付限度額に早く到達してしまうということになりかねませんので、実際の貸し付けにあたっては、その辺を慎重に判断していきたいと思ってあります。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これからということなので、生活保護であればここまで受けられるのに、それが受けられないということがないように、ぜひお願いしたいと思います。さまざまな問題を抱えた要保護状態の方の相談にどこが対応されていくのか、その辺のところがどうなっていくのかお聞かせほしいと求めました。","respondent":"志村生活福祉課長","answer":"先ほどご説明したとおり、３カ月、初めて生活保護を廃止ということになります。ただし、今ご説明したとおり、月額１８万円お貸しするわけですので、年間２００万円ぐらいの貸付額になります。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これから始まっていく制度で、どのぐらいの方が対象になるかわからないという状況もありますけれども、生活保護が必要な状況になっている方が困ることのないような制度にしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"}]},{"id":"topic-02","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先日、多分２１日だったと思うんですけれども、原小学校跡地の説明会が開かれましたけれども、説明会の参加者の人数を教えてほしいと求めました。それから、最後に皆さんから説明会をぜひ引き続いて行ってほしいという要望が出されましたけれども、どういう方向になっているのか説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"私が答えていい立場かどうかわからないですけれども、一応主な説明者ということで私が参加させていただきました。開催の要望等については、説明会の結果を事業者と区のほうで整理していますので、今のところ開催する、しないということは申し上げられない状況です。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その場では引き続いて説明をしてほしいという声がたくさん上がっていましたので、説明を引き続いてやってほしいと求めました。やはり区としてしっかり地域の方にも説明をしてほしいと求めましたので、区民の要望にこたえて説明会を開く方向で検討をお願いしたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"日照の影響等々について説明をして、それについて質問、疑問等に答えるという趣旨の説明会であろうと思います。なお、これとは別に着工前の事前の工事説明会は開催することになります。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"例えばワンルームもファミリー世帯に変えてほしいとか、民間のマンションの紛争予防条例に基づく説明会でもそこまでされているわけです。まして区の施設ですので、地域の要望にこたえてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/928192?Template=document&Id=3180#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":25383,"voices":76}},{"id":"h19-20070827-8","meetingId":"h19-cm08","date":"2007年8月27日","dateIso":"2007-08-27","committee":"建設委員会","time":"午後１時０３分～午後３時０４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"の少年少女のためのサッカー教室（オリンピアンふれあい交流事業）の開催","agenda":"の少年少女のためのサッカー教室（オリンピアンふれあい交流事業）の開催","exchanges":[{"speaker":"井上委員","kind":"提案","question":"運動施設管理業務委託業者からの提案事業ということでしたけれども、どういうところからの提案で、それとも今回初めてこういうものなのかということをお願いしますとの意見を述べました。","respondent":"藤田道路公園課長","answer":"園芸教室を開いたりとか、あとは地域の方々をまぜたボランティアとしての活動だとか、さまざまな形で行ってきてあります。こうしたスポーツの交流事業をやってはどうだという提案を受けて、今回、実施するという形になったものです。","id":"exchange-001"},{"speaker":"井上委員","kind":"提案","question":"今、私はこの業者については芝の管理だとか、その部分でこういう提案制度をそういうところに持たせたということは別に問題ないと思うんです。たまたまこのプロポーザルで決定した業者がそういう提案でうまくいったからということなのか…","respondent":"藤田道路公園課長","answer":"いろいろなノウハウを出しながら、いろいろな提案をしてくださいというようなお願いを私どももしながらこれまでもやってきております。そういった業務の中で、お互いにいい結果につながるだろうというような事業については取り上げながら進めていきたいと考えているところです。","id":"exchange-002"},{"speaker":"井上委員","kind":"提案","question":"たまたま、この提案と無関係なのかどうなのかというところで、このＮＰＯ自体以前から活動されているのかなというのがちょっとわからないんですが。だけど、そことは関係ないものなのか、そういうことに関連して提案があって、ではということになったのか…","respondent":"藤田道路公園課長","answer":"ちょっと年数は定かではありませんけれども、今回の東京のオリンピック招致にあわせてできた組織だとか、そういうことではございません。それを区として現場を取り仕切りながら、１１月１０日にすばらしいイベントとして開催したいと思っているところです。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"そうすると、品川区の予算をここに使うとか、経費が出ているとか、その辺の予算的なものはあるんか尋ねました。","respondent":"藤田道路公園課長","answer":"例えばどこかからかテントを借りてきて設置するとか、考えているのは、その部分については若干なりの予算を使いながら事業を進めたいなと考えているところです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"参加費用的なものはどういう形になるのか、保険とかで５０円とか、参加費用はどういう形になるんか尋ねました。","respondent":"藤田道路公園課長","answer":"ということで、現場の取り仕切りについては品川区で行うということになります。それから参加費については、今回については無料です。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういう環境というものも私は大切だと思いますので、ぜひそういうことも取り組んで、今後考えてほしいと求めました。意見だけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"提案","question":"運動施設管理業務委託業者からの提案事業の一環だから建設委員会なのかということを教えていただきたいのと、今、主管という話があったけれども。だからこの質問になると、ここの提案事業の一環だからこれをやったのか、今の管理業者にはこういう提案をしてもらってとの意見を述べました。","respondent":"藤田道路公園課長","answer":"ただ、私ども例えばサッカーだけではなく、当然、野球も含めて体育館を使ったスポーツだとか、いろいろなスポーツがあることも認識しています。今後、うまくいけばまた所管課とも十分協議をしながら、何か新しい道はないのかというようなことを協議をしていきたいと考えておりま…","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"提案","question":"共催まで１つ上げるつもりなのか、生涯学習課だってそれなりの考えがあると、すべてお願いをしていくところがあるわけだね。答えられるなら答えていただきたいし、いろいろ提案していただいて、働きかけまでやっていこうと考えられているのかどうかというのを確認したいとの意見を述べました。","respondent":"藤田道路公園課長","answer":"ただ、これから展開していく中では、一番何が事業として進めやすいかというのは十分考えながら進めなければいけないと考えています。当然話としては出てまいりますので、ぜひ子どもが喜ぶための企画というのは私どもも考えていきたいと考えていますので、よろしくお願いいたしま…","id":"exchange-008"}]},{"id":"topic-02","title":"の「都市高速道路 中央環状品川線」換気所の景観に関するアンケート調査","agenda":"の「都市高速道路 中央環状品川線」換気所の景観に関するアンケート調査","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"近隣の方々のご意見を伺いたいというアンケートを、ぜひ率直な住民の不安や意見を聞く、そういうところも必要ではないかと思うんです。なぜ景観だけに絞ってなのかというのが非常に疑問なんですけれども、お考えはありますか。","respondent":"阿部都市計画課長","answer":"五反田でも、東京都第二建設事務所と周辺の町会の方は話し合いを持っておりまして、その中で工事に対する理解を求めているという状況です。それを重ねながら、換気所を含めた品川線に対する理解を得ていくというような方向で話を進めているという状況です。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"であれば、なおさらこのアンケートの中に、この計画に対する地域の方々のご意見を率直に聞くことがあってしかるべきだと私は思います。この「ご協力のお願い」に書かれている３行目、これでアンケートをとろうというのがよくわかりませんけれども、いかがか尋ねました。","respondent":"阿部都市計画課長","answer":"先ほど申し上げましたとおり、去年の６月の段階で全区域にわたりまして事業の説明会は既に行っております。既に説明を行いましたし、継続して各地域でこの工事についての、あるいは説明会を行っておるものですので。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"関連で伺いますと、どういう状況になっているのかな、どういう状況になっているのかを教えてください。だって実際、住環境がよくなるとは私はこの話からも思えないんですけれども、いかがか尋ねました。","respondent":"阿部都市計画課長","answer":"東京都におきましては供用開始前後、必要であればつけるということで答えておりますけれども、あくまでもつけないということではございません。そこについても一般街路の渋滞も解消されるだろうと、もう１つは…","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"現状、まだ東京都はそれについてつけないという方向で話が進んでいるのか、そこは現状でどこまで話が進められているのかを教えてほしい。つけられるような大きさでという話ですけれども、完成までにつくのかどうか、その辺の脱硝装置についてもう少し詳しく説明を求めました。","respondent":"阿部都市計画課長","answer":"ただ東京都からは、今のところ明確につけるという回答はいただいてはおりません。ただ、私どもとしては従来から要望しておりますけれども、今後も脱硝装置をつけてほしいと強く要望してまいりたいと思っています。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その形の中だけれども、新宿線のデータだとか、いろいろご要望があると思うんです。今の脱硝装置のこともそうだけれども、そこら辺の主張はしっかり都に伝えていくという見解でいらっしゃるのか、そこら辺だけ聞かせてください。","respondent":"阿部都市計画課長","answer":"ただ、換気所のあり方、その辺について話し合いの場を持っていると認識しております。供用後のデータですね、事前と事後という感じだと思いますけれども、それについては合同連絡会のほうに十分に提供をお願いしたいと思っています。","id":"exchange-013"},{"speaker":"井上委員","kind":"意見","question":"どういう形で、それでこの５０ｍも、その範囲というのはだれが決定したことなのかというところをまず説明を求めました。","respondent":"阿部都市計画課長","answer":"配布の時期ですけれども、今日以降、配布をすると聞いております。もう１つ、具体的には今回は５０ｍ範囲ですけれども、それが一番重要なことではないかなと考えています。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"だからその５０ｍ範囲と決めたところは東京都の第二建設事務所なのか、区なのか、そこはどうか尋ねました。","respondent":"阿部都市計画課長","answer":"この事業主体は東京都と首都高速道路株式会社ですので、決めたところは東京都第二建設事務所です。事前に私どもが２月に会ったときには、当然のことながら、前回の事業説明会の範囲と同じ範囲に少なくともしてほしいという要望は出しております。","id":"exchange-015"},{"speaker":"井上委員","kind":"提案","question":"そういう意味だったら、私なんかも南品川の換気所は、離れているけれども、すごく気になるところだし、日々目にしなければならないところです。当然区として３つのこういう換気所が建つわけですから、ここは１８日と言っているかもしれないけれども、そのことについてはいかがか尋ねました。","respondent":"阿部都市計画課長","answer":"区として３つの換気所を統一してデザインしてはという話ですけれども、そういう考えよりも、それが一番やっぱり重要なんだろうと考えています。それをお聞きして、具体的に今後の換気所のデザインに生かしていくということが大事なんだと思います。","id":"exchange-016"},{"speaker":"井上委員","kind":"提案","question":"今、まちのイメージをと言っているときに、もう少し広く考えるという視点だけは持っていていただきたいということを１つ要望しておきます。要望がたくさん出ている換気所ができる、事業主体にするように提案をするのか、その先で何かあるんか尋ねました。","respondent":"阿部都市計画課長","answer":"私も何回か事業説明会すべての会場で出ましたけれども、健康調査をしてほしいという具体的な要望はございませんでした。ただ、今申し上げたとおり、事前に健康調査をするという考えは現在ございません。","id":"exchange-017"},{"speaker":"井上委員","kind":"質問","question":"今、あの地域でのアレルギーを持ったお子さんとかがたくさんいるということは、当然区としても把握をされていることだと思うんです。そういうことというのも難しいですから、データをそろえることはできないわけですから、今後そういうことを検討される予定はないんか尋ねました。","respondent":"阿部都市計画課長","answer":"先ほど申し上げましたとおり、環境影響評価の中で基準をクリアしているものですので、現時点で健康の調査をするという考えは持っておりません。","id":"exchange-018"},{"speaker":"井上委員","kind":"質問","question":"住民の人たちのそういう声というものは、あれば、そういう対応というのはしていこうとされているんか尋ねました。","respondent":"阿部都市計画課長","answer":"今申し上げたとおり、もう既に予測できちっと出ているわけですから、それを改めて健康調査をするという考えはございません。","id":"exchange-019"},{"speaker":"阿部委員","kind":"質問","question":"すいません、聞き落としたかもしれませんが、このアンケートの配布対象人数を教えてください。要は何部配布という計画なのかということと、それはいつごろまとまって、結果の公表はどのような日程になっているかということを説明を求めました。","respondent":"阿部都市計画課長","answer":"先ほど申し上げましたとおり、道路端から５０ｍの範囲ですけれども、対象としては２万９,５００人です。今回については多分同じような形になるんだろうとは思いますけれども、申しわけございませんけれども、時期あるいは形については把握しておりません。","id":"exchange-020"},{"speaker":"阿部委員","kind":"提案","question":"何がどうなって、ご確認の上、ホームページだけではない結果公表の仕方もあわせて区を通して要望してほしいと求めました。地域に役立つ施設みたいなものを何げなく提案をしているような質問項目があるんですが、何か換気所そのもののイメージしかないんですとの意見を述べました。","respondent":"阿部都市計画課長","answer":"南品川につきましては、ここのところに面したものを活用できないのかなという意味で、Ｑ２のところにそういう具体的なものを入れていると思います。要するに、今申し上げた検討会の中で出された意見を踏まえて、その中でこういう細かな聞き方になっているのかなと思います。","id":"exchange-021"},{"speaker":"阿部委員","kind":"質問","question":"インフォメーションセンターの話が出たのでちょっと伺いますが、出入り口の説明会のときに、その後の進捗状況を教えてください。五反田以外のところは何か住民に対する、五反田はそういう予定は、そういうものがないのかなという思いも含めてちょっとお伺いしました。","respondent":"岩田まちづくり事業部長、阿部都市計画課長","answer":"先ほど都市計画課長がお答えしましたように、既に２年近く換気所に関するデザイン検討委員会、主に技術的な面で詰めてきました。そういう検討の中で、これから検討していきたいということでここに取り入れてもらったですので… 実際に検討していると聞いてございまして、どちらになるのかはまだ決定していないとは聞いていますけれども、どちらかを開く方向で検討していると聞いています。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"ここの場所に貼ってありますが、見ていただくような環境をつくってもらえるような、そういうことをお願いできないものでしょうか。その辺をちょっとお答えください。","respondent":"阿部都市計画課長","answer":"その辺は例えば先ほどから申し上げているような説明会とか、そういう中で示していくというようなことについて、可能なものについては東京都第二建設事務所に話を持っていくというふうに思います。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"全然想像していたものと現実が違っていたとか、そういう誤解のできるだけないように、できるだけ慎重に換気所の設計を考えてほしいと求めました。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"}]},{"id":"topic-03","title":"の再開発準備組合の設立","agenda":"の再開発準備組合の設立","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"０.５haといえば、どういうふうなコンセプトのまちづくりとして誘導していこうとしているのか、それを教えてください。それと、８７名が武蔵小山とありますけれども、そういったものの権利者はどういう状態になっているのかをあわせて教えていただけますか。","respondent":"青木都市開発課長、伊勢住環境整備担当課長","answer":"権利者関係、大崎三丁目地区について、私からご説明申し上げます。借地権の方に関しましては、２名の方が法人登録という形になって把握しています。 それから借家人の数ですけれども、現在のところ１７１件です。それから法人、個人の内訳等については詳しい資料はもらってございません。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"大崎全体のまちづくりをどう考えているのか、まちづくりというのは部分部分、それよりはそれぞれのつながりが１つのまちになるわけですよね。権利者の機運が高まってと、その機運というのは具体的にどういう話が出ているのか、そこを教えていただけますか尋ねました。","respondent":"青木都市開発課長、伊勢住環境整備担当課長","answer":"まちづくりは、大崎につきましては品川区の市街地整備基本方針において、都市活性化拠点という位置づけをしております。それに見合った、でも周辺との関係も考えながら… 武蔵小山の機運の関係ですけれども、地震のとき結構揺れるだとか、あるいはいざ火災が起こったとき危ないというような課題があります。なかなか建て替えが難しいというようなことで、それで共同化等について勉強会を重ねるうちに…","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えばこの商店街にとってこれはどういう影響があるのか、その部分というのはどういう状況なのかを教えていただきたいんです。部分部分続くものですから、その辺を教えていただけますか。","respondent":"伊勢住環境整備担当課長","answer":"市街地整備基本方針等で、あるいは都心整備を進めるまちだとか、いろいろ書かれてあります。もちろん商店街の方々だけじゃなくて、商店街の周辺に居住されている方の意向等も把握しながら検討を進めたいと考えております。","id":"exchange-027"}]},{"id":"topic-04","title":"の大崎駅西口地区におけるまちづくりの現況","agenda":"の大崎駅西口地区におけるまちづくりの現況","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"この大崎駅西口地区におけるヒートアイランドへの対応というのは、これはどういう対策がとられたか、そこを伺いたいんです。どうなるのかなと思っていたんですけれども、全体としてどういうコンセプトがあるのか、まずそこを説明を求めました。","respondent":"青木都市開発課長","answer":"当然、敷地内の緑化を空間の３０％以上とるということ、建物によっては壁面の緑化も進めるということで実際に取り組んでおります。現在のところ具体的にこれがあったから気温が何度下がるとか、そういったところまでは残念ながらまだデータは各所ごとに検証されていません。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"環境配慮ガイドラインの中身を教えていただきたいのが１つと、進めていくお考えがあるとすれば具体的にどういう方策を今、そこを教えていただけますか。","respondent":"青木都市開発課長","answer":"まず、当時、あるいは将来開発するつもりであるという事業者の方々にお集まりいただいたまちづくり連絡会という組織が検討を重ねたものとして。番人というと変ですけれども…","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"さっきの話だと門番ですか、区は東京都のＣＯ２削減の義務化をどのように今、考えているのかを教えてください。６月の建設委員会で聞いたときに、その時点では東京都からまだ、その後何か東京都の関係で動きがあればあわせて教えていただけますか。","respondent":"青木都市開発課長","answer":"大まかな方針がありますので、それにおいてどのぐらいのＣＯ２削減対策、これは品川区においても同様に準じたやり方で事業者を指導しております。今後、力を入れて進めていきたいと考えています。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"今のお話の中で、計画段階からＣＯ２削減をしっかりやりなさいよというお話を区のほうからも話しているというお話でよかったでしょうか。じゃあ、今、今日の報告でもありました大崎駅西口地区として、これはどんなＣＯ２削減計画があるんか尋ねました。","respondent":"青木都市開発課長","answer":"それをいかに削減していくか、従前よりもＣＯ２の削減、ＣＯ２の発生量が減るんだということはまず期待できないと考えています。今後、完成後もそういったことの取り組みを積極的にやっていくように指導していきたいと考えていることは先ほどもご報告したものです。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"国だってチーム・マイナス６％とか、ＣＯ２をとにかく抑えようという話の流れの中で、これは大分無責任な話だなと思っているんです。ＣＯ２を減らすのは極めて期待できないですと、こんな対応は改めるべき姿勢だと私は思いますけれども、いかがか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"当然、大規模な開発であれば、そういうことをきちっと総合的に計画的に考えていきましょうというのが計画段階でのＣＯ２の削減の指導方法なんです。都民全体でＣＯ２の発生量を抑えていきましょう、こういう計画だと認識しておりますので、誤解のないようにお願いします。","id":"exchange-032"},{"speaker":"中塚委員","kind":"意見","question":"そこから出ているＣＯ２量の削減にきちんと責任を負うことを、今、検討すべきじゃないのかなと思っているんです。区がみずからＣＯ２を増やすような計画、きちんとＣＯ２削減という視点に立つべきじゃないかと、このことを私は言いたいということですとの意見を述べました。","respondent":"岩田まちづくり事業部長","answer":"先ほどからも都市開発課長もお答えしていますように、極力ＣＯ２削減になるようなエネルギー効率のいいビルにする、これが大前提なわけです。そして同じようにできるのであれば、結果的にＣＯ２削減に協力ができると、こういうことを説明しておるものです。","id":"exchange-033"},{"speaker":"阿部委員","kind":"質問・要望","question":"以前もちょっとお伺いしたことがあるかと思いますが、大崎駅のホームがもう飽和状態で非常に危険な状態になっているという記事があったと思います。それで、区として大崎駅の安全性についてＪＲに対してどれだけの働きかけをしているのか、その辺をもう一度教えてほしいと求めました。","respondent":"青木都市開発課長","answer":"そうしますと現在２０万人のところに９万人ですから、相当な増加が見込まれます。駅に伝えておるのみで、具体的な検討は現在区とＪＲとで、あるいは区が独自にということでは検討はしておりません。","id":"exchange-034"},{"speaker":"阿部委員","kind":"質問・要望","question":"なければ、はい、そうですかというわけにはいかないと思います。せっかくといっていいんでしょうか、ちょっと強い姿勢でこの話題についてはやってほしいと求めましたが、いかがか尋ねました。","respondent":"青木都市開発課長、岩田まちづくり事業部長、齋藤住宅課長","answer":"あまり具体的には申し上げたくないんですけれども、鉄道事業者としての責任もあると考えています。まちづくりを進める行政側の責任もあると思いますので… 当然、自分のところの投資として考えるべきでしょうと、私からこれは早急に検討していただきたい課題ですと口頭ではお伝えはしております。… いいかげんにしなさい、どれだけ人が混んでいるか、もっと上席の人に相談をしてくださいという話をしております。…","id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここのところももしかしたら何か動きがあるのか、そういう情報があったら、わかっていたら答えられるところがあったら答えていただきたい。何の動きもないというなら、動きがなくて結構です。","respondent":"岩田まちづくり事業部長","answer":"ただ、近々、どういうことになるかについての社内決定をするという話は来ております。これは今月末か、区にもお話が来ると思いますし、ここ近々大きな動きがあるやに聞いておるというところまででご勘弁をお願いしたいと思います。","id":"exchange-036"}]},{"id":"topic-05","title":"の目黒川水門扉の塗り替え","agenda":"の目黒川水門扉の塗り替え","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ほかのいろいろご要望等もあると思うんだけれども、それらも一緒に、ぜひ東京都も動いてよと言っていただきたい。その点はどう思われているのかというのをもし知っていらっしゃったら答えていただきたいのが１つ、それから２つ目は、そこら辺を説明を求めました。","respondent":"松代管理工事課長","answer":"１点目の東京都港湾局による今回のケースですが、今後こういった形でいろいろな連携を図って、区民の皆さんと一緒にやっていきたいと考えています。いろいろとそういったものがないのかというところですので、今後…","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"この募集が始まるんでしょうけれども、応募資格というのはどういうふうに考えているのかなと。応募資格はどなたなのかを教えていただけますか。","respondent":"青木都市開発課長","answer":"在住地、勤務地も問いません。東京都が発注する工事になりますので、その東京都と協議ができる、お話し合いができる方であればだれでもいいということで募集しております。","id":"exchange-038"},{"speaker":"三上委員","kind":"質問","question":"そうなると、そういった皆さん方は、我々に一言軽く声をかけてもらえるといいのになというものがあるかもわからない。協力をお願いしたいというのがあってもいいんじゃないかなと、ですからそこらあたりのそういった方々の声も聞いていただきながら。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"井上委員","kind":"提案","question":"これからそういう提案制度とか、発信をしていただくということをお願いしたいなと思っていますので、ちょっと視点として置いておいていただきたいなと思いますとの意見を述べました。","respondent":"本多委員長","answer":"本件を終了いたします。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/325823?Template=document&Id=3886#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":38985,"voices":113}},{"id":"h19-20070827-9","meetingId":"h19-cm08","date":"2007年8月27日","dateIso":"2007-08-27","committee":"文教委員会","time":"午後１時０４分～午後２時２６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"平成１９年度「通学区域の弾力化」に関するアンケート調査結果","agenda":"平成１９年度「通学区域の弾力化」に関するアンケート調査結果","exchanges":[{"speaker":"山内委員","kind":"確認","question":"確認なんですけれども、これはアンケートされる側の方のやり方というのはアトランダムに行っているんでしょうか。生徒も含めて、父兄の方、生徒をアトランダムにこちらのほうから調査をするという形でやっているんか尋ねました。","respondent":"古里学務課長","answer":"これは全員対象でお願いをしております。学校を通して、全保護者に配付をして行っております。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"どういうふうになっているのかちょっとよくわからないので、その辺のチェックをどういうふうにされたのかを伺いたいと思います。たまたま近くにある場合もあるんでしょうけれども、その辺の関係を聞きたいなと思うんですけれども、どういうふうに見たらいいんか尋ねました。","respondent":"古里学務課長","answer":"残念ながらそのような個別集計はとってございません。単純集計だけしか今はとってございませんので、従来の指定校に入学をしたというこの１,２２４名の回答者が、今のところ統計はとれてございません。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"そうすると、Ｑ１の１の従来の指定校に入学した１,２２４名の方々が、指定校を通学のしやすさを考えて選んだというように単純に見ていいんですか。私はこの数字を見て不安というか、どういうふうに考えたらいいのかなというのは知りたいところなので、教育委員会の見解を伺いたいと思うんですけど。","respondent":"古里学務課長","answer":"推測ですけれども、この数字の状態から見て、Ｑ１の１に回答した方の大多数がＱ２の１に該当しているものと従来から推測をしているところです。来年以降、個別集計をとったほうがよろしいかなということも考えてありますので、今後の検討課題とさせていただきたいと考えておりま…","id":"exchange-003"},{"speaker":"西本委員","kind":"意見","question":"それから、ちょっと難しいとは思うんですが、その辺は見れるのかどうか。難しいとは思いますけれども、むしろ小学校も中学校のように４つじゃなくて全域に広げるかどうかわかりませんが、その考え方を説明を求めました。","respondent":"古里学務課長","answer":"これは変更の手続の段階で、小学生はやはり通学区域、ブロックというものについては今後も何らかの形で維持していくべきものだろうと考えております。こうしたことを踏まえながら、今後の検討課題、こちらも検討課題で申しわけないんですが、検討課題かなと考えています。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"私はどうかなと思いますので、今の学区域制度というのが始まって大分たっている状況ですから、うまくやってほしいと求めました。今どういう状況になっているのかということと、さらに区としての考え方として広げていくという考えがあるのか、その辺をお願いします。","respondent":"古里学務課長","answer":"学校公開についてはほとんどの学校が年間を通してさまざまな公開授業を実施しているところです。こちらが入学時案内パンフでご紹介をした学校説明会以外の学校公開の事例にも、行っておられる方もたくさんいらっしゃると認識しています。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"今のところで、小学６年生の保護者、公立中学校、６ページですね。この傾向はどうなのかなという部分がありまして、やはりきちっと自分たちの目で、いかがか尋ねました。","respondent":"古里学務課長","answer":"学校説明会に参加してというのも同じくらいの率でだんだん上がってきておりまして、平成１５年の数字はここに出してございませんけれども。自分のお子さんが今後３年間、慎重にご判断を、多方面から情報を集めてご判断をなさっておられるのかなと見ているところです。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"一貫教育というものを品川区で推進していっているわけですから、強いのは当たり前だと思いますけれども、そういう形で流れがいっているのか。地域性を考えた上での選択をしてほしいと求めましたが、その辺はどういう方向で受けとめられているのかをお聞きしたいと思います。","respondent":"古里学務課長","answer":"６ページのところのＱ２の５の回答のアになりますが、品川区が進めようとしている小中一貫教育への期待のあらわれだなと思っているところです。懸命に推し進めているですので…","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"それぞれの学校がどういう位置付けで、地域とのあり方、それでそれを乗り切っていくという形に持っていかないとなかなかわかりづらい。やっぱり期待感はどうしてもそういう一貫校のほうになりがち、その中での連携を心がけていただきたいということでお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"金野委員","kind":"確認","question":"確認と質問なんですが、平成１７年度からなんですが、この始まったときからアンケートをされているんですか。その他で考えられる、お母さんたちが基準として考えられることはどんなことなんか尋ねました。","respondent":"古里学務課長","answer":"ここには３カ年しか載ってございませんけれども、設問の項目は若干変わってきている部分はありますけれども、少しずつ工夫をしながらやってあります。その他の回答ですけれども、これは記入式の回答になってございまして、わりと意見というところが多いです。","id":"exchange-009"},{"speaker":"金野委員","kind":"質問・要望","question":"学校をよくしたい、自分たちの子どもをより健全に育てていただきたいというところで、どれだけ学校教育に反映されているのか。こういう見えない意見というのが、より学校教育に必要な部分でもあるのかなという気はするんですけれども、その辺はどうなんか尋ねました。","respondent":"古里学務課長","answer":"この記入式の内容については全部チェックをし、改善に役立てるべきこと、あるいはご意見という意味では改善のご意見もあります。それからご注文というご意見もありますので、その辺はきちんと見ながらやっていくです。","id":"exchange-010"},{"speaker":"金野委員","kind":"質問・要望","question":"その小さな声というんでしょうか、より子どもたちの健全育成のための教育のいい環境をつくる意味でも、今後も見てつなげてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"石田（慎）委員","kind":"質問","question":"公立を選択するときに、経済面というのが非常に各家庭で考えられることだと思うんですが、その項目が入っていないというのは何かあるんですか。その他のところに経済面で公立の学校を選んだとかという記入が、実際にそういうのが何件かあるのかないのかというのをお聞きします。","respondent":"古里学務課長","answer":"あるいは品川区が進めている教育改革の一環としての学校選択制ですので、したがって、公立を選んだのかということを問うアンケートではございません。したがって、特に選択肢として経済的な問題ということに触れていないというのは…","id":"exchange-012"},{"speaker":"市川委員","kind":"質問","question":"小学校６年生の保護者および児童へのアンケートなんですけれども、６年生であれば子どもだけでもこのアンケートに答えられるような内容かなと思うんですけれども、こういうアンケートの集計の仕方をした動機というのは何か理由があるんか尋ねました。","respondent":"古里学務課長","answer":"Ｑ２とＱ４はほぼ同じ内容になっておりますけれども、これは同じ内容にわざとしています。ほぼ同じ内容にしているということですので、そのようにご理解をいただければと思います。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"下位のほうにあるというそこのところは、どういうふうに教育委員会としては見ているのか、その辺をちょっと伺いたいと思うんですけれども。品川区の教育行政がどういうふうに、その辺の一定程度の議論をしている見解がもしあれば、伺いたいと思います。","respondent":"古里学務課長","answer":"それから２つ目の質問につきましては、私どもが進めております教育改革というのは、これが教育改革の基本的な目標です。そういった期待にこたえて、少しずつ小中一貫教育を含め、保護者のニーズに対してはそういう点でこたえているというふうに考えているところです。","id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"２番目の質問についてはちょっと抽象的過ぎちゃったので大変恐縮だったんですけれども、答えていただいてありがとうございました。１６番目という状況から見てのご判断ということで見解を述べていただいたわけですけれども、今、どの先生にも自分の存在がわかってもらえていると。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"６ページにありますＱ２の１３、指定校に入学したくないからというのがあるんですね。何かここから問題がある形でそういう形になっているのか、そういう分析をしていいのかどうかわかりませんが、そういう傾向があるんか尋ねました。","respondent":"古里学務課長","answer":"今後、指定校へ入学したくないからというところはどういう回答と連動しているのか、今の段階ではまだそういう分析はしておりません。分担をしながら、そういう段階を越えてきているというところから、改善の検討を今しているということでご理解いただければと思います。","id":"exchange-016"},{"speaker":"西本委員","kind":"意見","question":"個別集計はこれからだということなんですが、一番必要なのは個別集計だと。ちょっと予算をつくっていただいて、あとは教育委員会の中で、そこから何が得られるかというところを検討してほしいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"}]},{"id":"topic-02","title":"八潮地区・荏原西地区小中一貫校通学区域の取り扱い","agenda":"八潮地区・荏原西地区小中一貫校通学区域の取り扱い","exchanges":[{"speaker":"南委員","kind":"確認","question":"改めて確認をしておきたいと思っているんですけれども、どういうふうに整理されて今日まで来ているのか、その辺を改めて伺っておきたいと思います。","respondent":"古里学務課長","answer":"５校の教職員、保護者をまじえたさまざまな検討部会を設けて、準備を進めるために検討をしております。今、こちらのほうにおきましてもそれぞれいろいろな必要な検討部会を立ち上げ、どのようなものかという検討会を開催をしていると聞いております。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"それ以外に当然あると思うので、できるだけ細かく今の状況がどうなっているのか教えていただきたいと思って質問しているので、よろしくお願いします。それともう１つ、やるのであればどの時点でどんな内容で計画されておられるのか、それも伺いたいと思います。","respondent":"藤森小中一貫教育担当課長","answer":"今まで教育課程の来年度の内容について検討してきたものを、５校の合同研究会を開いて、夏休みに十分検討してきたものをそこで集約して。そういった中で学校の内部でさらに細かい検討をしていくという作業をしています。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、いろいろと地域の必要な力を出さなきゃいけないときも当然あるわけですから、その辺について検討してほしいと求めました。その辺のご努力をできるだけしていただきたいということを、改めてつけ加えさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"荏原西地区だと実はこの学校だったみたいな、意外とわかりにくい区域で、指定校の案内が来るまでは意外とわからない。大体ここら辺からなので、自分の指定校がここだというのはある程度わかるんですけれども、わからないんじゃないかと思うんですが、いかがか尋ねました。","respondent":"古里学務課長","answer":"今年度は学区域の変更が伴ってありますので、この辺もきちっと説明をしているようなことはやっていきたいと考えています。今後もそのようなきめの細かな地域への周知というのは、できるだけしてまいりたいと考えております。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"きょうの予定表にもないので、どういう状況になっているのかちょっと知りたいところなので、説明をしていただきたいと考えています。委員長にもそのことを先週お尋ねしたんですけれども、どうなんか尋ねました。","respondent":"市川庶務課長","answer":"このほど学事制度審議会の設置運営については、しかるべき時期に報告をしますということで説明してまいりました。最終的な準備を進めている段階ですので、このまま順調に事業が進めば、９月の文教委員会で報告をするという心づもりでおります。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"９月から開始となると、それは承知して質問しているつもりなんですけれども、どの程度の期間でやろうとしているのか。あるいは１０年ほど前に設置された適正規模審議会のときには、その辺の考え方について、どうなるかについては知りたいところなんですけれども。","respondent":"市川庶務課長","answer":"今、ご質問にございました新しく設ける検討組織の性格、目的、運営の指針と申しましょうか、そういうことも含めて、今現在、最終的な準備の段階にありますので、整理がついた段階でまとめて報告をします。","id":"exchange-023"},{"speaker":"南委員","kind":"質問","question":"ほかの審議会の設定は１年とか１年半とか２年とかいろいろありますけれども、当初目的としていた期間を超えないで設置されていくんですかね。その辺が非常に心配なので、どういうふうになっていくのかというのをちょっと聞きたいところなんですけれども、そこは教えていただけますか尋ねました。","respondent":"市川庶務課長","answer":"検討組織というのは当然のことながら、もちろん検討していただく課題を諮問する側の一定の考え方をお示ししますけれども、検討課題の内容。","id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"きちんとした議論がしていけるようにしていくというつもりで非常に関心を持って見ているわけで、９月のときにはぜひ何らかの形で話していただけるようにしていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"南委員","kind":"質問","question":"私も前回、山形県で少人数教育をやっているはずなので、どうでしょうかと意見を申し上げたんですけれども、そこはどうだったんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"それでまた北のほうに行って、今度太平洋のほうに行くわけですからね。ですから、そこのところで品川区の教育の目的の住民要望のところにあるそういう問題にもどうかと投げかけてさせていただいたわけですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"地理的によくわからないんですが、地震の影響は大丈夫か尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/120587?Template=document&Id=4610#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":22046,"voices":69}},{"id":"h19-20070827-5","meetingId":"h19-cm08","date":"2007年8月27日","dateIso":"2007-08-27","committee":"総務委員会","time":"午後１時０２分～午後３時０２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっと１つだけ基本的なところでよくわからないところを教えていただきたいんですが、特別交付金を３％増やすという形になっていますけれども、この辺をちょっと教えていただきたいのですが。","respondent":"日下部企画財政課長","answer":"その理由というのは、１つは、普通交付金では算定できないような、例えば災害とか、そういう特別な事情に対する算定を充実するということが１点。結局は普通交付金については配分割合を３％下げる、一方で特別交付金を３％上げるということで提案がありまして、一たんは受けとめ…","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問・要望","question":"今言った一長一短あるというところで、短所のほう、そこをもう少し教えていただきたい。","respondent":"日下部企画財政課長","answer":"平成１９年度はどうしても５％で行くということになりましたので、そのことによって客観性、透明性を担保する必要があるだろう。今ご質問の点から行きますと、そういうような課題がどうしてもやっぱり抜きにできない、そういうことです。","id":"exchange-002"},{"speaker":"土井委員","kind":"確認","question":"来年はまた話し合いをするのよということなのかどうか、ちょっと確認、それを忘れていたので。それで、来年はわからないけれども、我々はこう思っているのよというものがあるのだろうと思えるから、その辺もちょっと確認をしておきたい。","respondent":"日下部企画財政課長","answer":"１つは平成１９年度の算定のやり方をどうするかということを具体的にはっきり決める、これは都区間でちゃんとルールを確認するということです。それからもう１つは、これについて縮小の方向も含めてこれから平成２０年度財調協議を通して協議を進めていく、そのようなことです。","id":"exchange-003"},{"speaker":"土井委員","kind":"確認","question":"言葉を変えて確認します。５％の特別交付金の部分は、ほぼ、大体決めたとおりに行っているんだけれどもという意味のことなんですよね。","respondent":"日下部企画財政課長","answer":"先ほど１件算定と申し上げましたが、それはまさしく今ご指摘の点、そういう問題です。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問・要望","question":"多分、品川区のアンケートの場合、後者のほうだと思うんですね。それが大体予想どおりだったのか、それとも意外なところがあったのか、そういうものがございましたらば教えてほしいと求めました。","respondent":"福島長期計画担当課長","answer":"ただ、一般区民よりはより多くの方が当区に住み続けたいというふうに回答してくるだろうなとは予想しましたが。そのほか細かい点では、若干の違いはありますけれども、ほぼ予想どおりというふうに思っているかと思います。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"１つ１つのアンケートについても、そういう母数の特性ですか、もっと基本構想にも役立つのかなというような気がしてならないんですね。そのような流れ、今後このアンケートをどのような過程で使われるかというのを教えてほしいと求めました。","respondent":"福島長期計画担当課長","answer":"こちらは策定委員の皆様にお示しし、策定委員の皆様に考えていただくということで資料提供をしていくです。こういった年数とほかとの相関とか、そういう質問が出ましたら、また詳細に調べていきたいというふうに思っております。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問・要望","question":"こういう方々が今の行政に対してどういうリードを求めているかということについては、どういう評価をしているのでしょうかということが質問なんです。増加していると指摘がされているわけですから、調査していくのかということをお伺いしたいのですが、いかがか尋ねました。","respondent":"福島長期計画担当課長","answer":"回答にならないかもしれませんけれども、品川区と関係する団体につきまして、グループインタビューないし個別インタビューをしています。あるいは今後、第四次長期基本計画をつくっていく段階等も含めまして、今後検討していきたいというふうに考えてあります。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"実際の昼間人口は５０何万人いらっしゃるわけですから、そういう方々に対して行政がスポットを当てていく。それらのニーズがあることも事実ですから、もう少し団体のアンケートのところもいいんですが、そういうのを改めて説明を求めました。","respondent":"福島長期計画担当課長","answer":"委員長はじめ、あるいはどういう施策を打っていくのかというのは、策定委員会の中でも若干ではありますが出てあります。そういったこともありますので、今後何らかの方策を考えていきたいというふうに考えております。","id":"exchange-008"},{"speaker":"菊地委員","kind":"意見","question":"その内容についてどうのこうの言うつもりはないんですけれども、どういう形でこれから区のほうで示したこういう調査結果ですとかを審議していくのか、そこをもう少しとの意見を述べました。","respondent":"福島長期計画担当課長","answer":"ですから、今回のような資料につきまして事務局からの説明はなるべく省きまして、審議を中心に進めていきたいと思っています。進め方ですけれども、その分野ごとに区切りまして、委員の皆様からさまざまなご意見をいただきたいというふうに考えているものです。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問・要望","question":"例えば１０ページとか１１ページを開きますと、これを１つ高齢者の福祉、区民の皆さんはこれに非常に高い要望を持っていらっしゃると。それを具体化することが必要なんですけれども、策定委員会の中で、じゃあ、これを示して、区民の要望はわかりました。","respondent":"福島長期計画担当課長","answer":"策定委員としてどう考えるのか、この区民要望のまま進めていっていいのかどうか、そういったような議論をいただきたいというふうに思っております。事務局のほうで再度策定委員会の意見としてまとめ、また策定委員会のほうに返す…","id":"exchange-010"},{"speaker":"土井委員","kind":"質問","question":"子どもがたくさんいろいろ書いてくれているんだなということになるので、この人たちはどういう選択で選ばれたんですか。選ばれた人なんですか、それとも書いてくださいと言ったら書いてくれたんか尋ねました。","respondent":"福島長期計画担当課長","answer":"実施方法については学校に任せましたのでばらばらでございました。生徒会を使いまして、生徒会で１０年後の品川区はどうありたいということを検討して、そのまとめを生徒会長が書いてきたというものもございました。","id":"exchange-011"},{"speaker":"土井委員","kind":"質問","question":"４０何人ぐらいで、人数が数人ぐらいでこれだけ出てくるのは大変だなと思って見たものですから、今の状況を伺うと。そういう中で、ダブりも含めた内容があるわけですから、そして発表してくださいよということで出している資料ですよということでいいんですよね。","respondent":"福島長期計画担当課長","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"確認でお教えいただきたいのですけれども、４５％という形なんですけれども、区のバランス。まず１点お聞きしたいのは、ちょっと確認なんですけれども、教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"先ほど、これは５ページの上段のところでご説明させていただきました。これから後で出てまいりますけれども、都区のあり方検討委員会ということで、２年間でしっかり議論して取りまとめをしていく。","id":"exchange-013"},{"speaker":"原委員","kind":"意見","question":"委員の１人として思うんですけれども、どうしても先にいろいろ進めて決めていきたいものは決めていきたいというお考えがあるのかもわかりませんけれども、こちらの体制という意味合いを含めてお教えほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"菊地委員","kind":"意見","question":"４ページにある平成１８年度限りの２００億円、何かものすごい開き、小中学校の改築などでものすごい開きがありましたよね。２００億円は東京２３区で配分されて、どういうふうにとらえ、どういうふうに捻出される形になるのかちょっとの意見を述べました。","respondent":"日下部企画財政課長","answer":"先ほどちょっとご説明させていただきましたけれども、大体築５０年、それが２３区で大体９００校ある。各区を見るとまたいろいろなばらつきがありますけれども、基本的には財調ベースで考えますとそのようなことか言えようかと思います。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"引き続き、区長会に３つの専門部会というところで、大都市整備部会のところで、括弧で（将来的な制度のあり方含む）と出されていますよね。この何年か前に東京２３区をこういうふうにしてみたいなという広告がありましたけれども、ちょっとこの辺の中身を少し教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"第二次の検討が進んでおりまして、最終報告はたしか一昨年の１０月ですか、されております。その後、当然のことながら、その辺の内容もある程度参考にして検討を進めていくということではないかというふうに承知をしております。","id":"exchange-016"},{"speaker":"菊地委員","kind":"意見","question":"これは区長会でどうのこうのという話ではないのかもしれませんけれども、都区制度は都区制度として、東京都と区で検討はしている。一方で、国を中心にして道州制云々とあるんですけれども、この辺のとらえ方というのは、区としては、あるいは区長会としてはどんなふうにとの意見を述べました。","respondent":"日下部企画財政課長","answer":"３つぐらいたしか案が出ておりますし、これは都区のあり方については検討していく必要があるだろうというふうに考えておりますし、このように考えています。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問・要望","question":"大きなことですので、雑駁の答えしかできないと思いますけれども、この都区のあり方検討委員会に対して品川区はどういう考え方で臨んでいくのか。この検討会についてどういう思いで臨んでいらっしゃるのかということを大きな意味で確認といいましょうか、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"今、都区のあり方検討ということで２年間かけて、高橋区長がある意味で区長会の会長としてその都区のあり方検討の下地をつくったわけです。２３区全体の議論がしっかりとまとまって、その辺の基本的な考え方には変わりがない、このように考えているところです。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"確認","question":"ですから、確認したいのが、２３区でやるべき仕事であるという品川区の基準が多分あるんだと思います。そういうことについて、非常に雑駁な質問しかできないんだけれども、考え方はどうお持ちなのかということをお答えほしいと求めました。","respondent":"日下部企画財政課長","answer":"いずれにしろそれをもとに私どもを含めて具体的な検討を進めていくということになろうかと思いますが、事務の中身についてもいろいろ検討を進めていくということが重要ではないか、このように考えております。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私はそういうスタンスであっていいと考えていますので、ぜひ進めていってくださいということを要望だけはしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"土井委員","kind":"質問・要望","question":"財源で、最大の効果を上げればいいわけですから、同じ仕事が安い値段でできればいいわけです。まさしく要望しかないんだけれども、最少のもの、小さなもので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/495406?Template=document&Id=1758#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":40981,"voices":77}},{"id":"h19-20070828-14","meetingId":"h19-cm08","date":"2007年8月28日","dateIso":"2007-08-28","committee":"行財政改革特別委員会","time":"午後１時０３分～午後３時２６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"財政（歳入）に関すること","agenda":"財政（歳入）に関すること","exchanges":[{"speaker":"山内委員","kind":"意見","question":"徴収率というのは、基本的には１００％が普通だとは思うんですが、「目標徴収率達成に向け」という文言はどういう意味なのか。これは一体何％を考えているのかというのを、ちょっとお示しくださいとの意見を述べました。","respondent":"武内税務課長","answer":"９３.２８％、平成１８年度が９４％を立てまして、９４.５４％という数字をあげております。１００％が目標なんですけれども、こういう数字を掲げているところもありますので、ご理解いただきたいと思います。","id":"exchange-001"},{"speaker":"山内委員","kind":"質問","question":"平成１８年度まで、一応こういう形でお知らせいただいているんですけれども、そうすると、毎年１％ずつ伸びているということだと、今年度の平成１９年度は、やはり９５％という認識をしているんですが、平成１９年度はいかがなんか尋ねました。","respondent":"武内税務課長","answer":"今年度につきましては、昨年度２３区の状況をかんがみまして、９４.６５％という数字を挙げております。そういう意味で、今回は１％ではなくて、９４.６５％という数字を掲げさせていただきました。","id":"exchange-002"},{"speaker":"山内委員","kind":"意見","question":"やはり1)から6)のことが結構多く流れているんですけれども、取り組み方というものについてお考えがあるのかというところを、ちょっとお願いできればと思いますとの意見を述べました。","respondent":"武内税務課長","answer":"全国の自治体でさまざまな方策をとって徴収率アップを考えておりまして、設置できないかなということで検討してまして、そのようなコールセンター的なものを検討しているという状況です。","id":"exchange-003"},{"speaker":"山内委員","kind":"質問","question":"最後に、一つ教えてください。6)の差押の実施というのがあるんですけれども、具体的な金額がもしわかれば、平成１８年度で結構なので、教えていただけばと思うんです。","respondent":"武内税務課長","answer":"金額でいきますと、５億１,３００万円です。これは、滞納額ということではなくて、差し押さえた価格というんですか、そういうものを合計しますと５億円余ということです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"健全財政を求めて、もう少し区民の実態がどうなっているのかというのを、ぜひ伺いたいと思っているんです。３年間の推移が書いてあるんですけれども、滞納者がどう推移しているのかとか、その辺も含めて教えてほしいと求めました。","respondent":"武内税務課長、原国保年金課長、蓼沼高齢福祉課長","answer":"説明しますと、６億６,０００万円ほど、滞納繰越という金額になっております。普通徴収は年４回になりますので… それから、高いところでいきますと、限度額超えの人が８７％弱ということで、限度額超えの方は収納率が高い。それから、３５万円から５３万円… 平成１８年度が９８％の収納率ということで考えますと、当然、繰越額というのは増えてくるということは明らかになるのかなと考えています。… 滞納者の人数ですとか、割合について、今、手元にデータがございませんので…","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"階層のところを伺ったら、やはり所得の低い方ほど滞納があるけれども、区民税のところで、１,０００万円以上の方もいらっしゃると。その辺も、できたら詳しく教えてほしいと求めましたが、いかがか尋ねました。","respondent":"武内税務課長、原国保年金課長、蓼沼高齢福祉課長","answer":"所得割で課税する額が２００万円以下と、２００万円から７００万円という数字で、約５割がこの階層に入ります。今年度… 先ほどの１万円から５万円の均等割の世帯の保険料の範囲になりますけれども、そういったところでの収納率の低い原因かなと理解をしています。… ただいまのご質問については、手元にデータがございませんので、後ほど、ご答弁申し上げたいと思います。普通徴収のほうが約８８％なり…","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"きょう、論議の中身に加えていただきたいと思うんですが、いかがでしょうか。払えない状況にある方の相談の中身なんかも、ぜひちょっと、きょうここで明らかにしてほしいと求めました。","respondent":"武内税務課長、原国保年金課長、蓼沼高齢福祉課長","answer":"毎回２万円では大変だけれども、毎月５,０００円にしてくれれば払えるとか、そういう分納というようなシステムも多く相談に来られるんです。… 生活が困窮しているとか、そういったところが３,３００件ほどですので、４割強の方がそういうような事情であるです。… 支払いできない方はいろいろあるかと思います。具体的な件数、割合等について数字がありましたら、後ほどご答弁させていただきたいと思います。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特にきょうは高齢者のところがどうなっているのかというのを、数字的に詳しく伺いたいと思っていたので、ぜひ教えてほしいと求めました。実際にお話を伺って、その辺の制度について、許されたら具体的に教えてほしいと求めました。","respondent":"武内税務課長、原国保年金課長、蓼沼高齢福祉課長","answer":"では、９８％の方が皆さん、お金があるから払える方なのかというと、そういうわけでもないと、私は考えています。そこから支払っていただくということも… 国民健康保険料は住民税をもとに実施しておりますので、国民健康保険料のほうについても連動して軽減されるというような特別な事情の場合にあります。… この第３段階は、保険料の見直しが検討されておりますけれども、なかなか支払い能力が及ばないというような世帯が多いのではないかなということ。…","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺について、ちょっとそれぞれお答えをほしいと求めました。最後に、差押について、どういう状況になったときに差押に至るのか、そこのところも説明を求めました。","respondent":"武内税務課長、原国保年金課長、蓼沼高齢福祉課長","answer":"その辺の視点で考えますと、その２％の方はほんとうに払えないのか、私どもは日々仕事をさせていただいているわけです。定期預金を１００万円持っていると… １,０００万円であれば一定程度財産があるという判断をさせていただいて、まずは何回も通知をした後に、差押を実施しております。その都度、相談をしなが… 自分は払わないというような方については、先ほど申し上げましたように、差押も実施をしております。平成１７年度には…","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"４割強の方が失業とか、やはり払いたくても払えない層がいるんだというところを、しっかりとらえてほしいと求めました。最後になりますが、その点をご質問します。","respondent":"武内税務課長","answer":"減免制度を先ほどご説明させていただきましたけれども、そういう救済措置というのは現実的にありますので、その辺はよく私どもと相談していただければと考えています。","id":"exchange-010"},{"speaker":"阿部委員","kind":"質問・要望","question":"制度上のことを教えていただきたいんですけれども、先ほどから出ております減免の内容ですとか、条件といったものは、法律事項で決められているのか、それともそれぞれの区の条例などで決められているのか、さらには窓口の胸先三寸みたいな部分があるのか、ちょっとその辺も説明を求めました。","respondent":"武内税務課長、原国保年金課長、蓼沼高齢福祉課長","answer":"区民税の関係は、地方税法がありまして、第３２３条に、「市町村は、天災だとか、そういう特別な事情がある場合については減免する」。その１号… 昭和３６年から国民健康保険が始まっておりますけれども、一定程度共通基準を持って実施しようということで、来ております。２３区共通でやっておりますし… 基本的な考え方は介護保険法で示されておりますけれども、具体的には、先ほど申し上げました介護保険料の特例減額は条例に基づくものです。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"ということは、どの範囲まで、どの程度まで減免をするかということは、区の条例を変えれば、広がったり、狭めたりすることができるという解釈でいいんか尋ねました。","respondent":"武内税務課長","answer":"もちろん、そこの自治体の条例によるということですので、品川区単独で考えられないということはないと思いますけれども、２３区の中で、そういう特例的な減免制度というものをやっている区は聞いておりません。","id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"それからもう１点なんですけれども、人間心理として、なかなか難しいものがあるかと思います。減免制度を周知するということと、それから、より多くの人に相談をしてもらうための何か工夫というようなことはされていますか尋ねました。","respondent":"武内税務課長","answer":"毎年１回、年に１回は、そういう税の申告書をお送りしております。区の広報等、あるいは区のホームページ等を使いまして、そのような税の中身については詳しく説明しております。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"私も、滞納者の実態の把握について伺いたかったんですけれども、その前に、先ほど、山内委員の質問に対する答弁の中で、税金の滞納の徴収について、非常勤とか、外部に関しても検討しているというお話がありましたけれども、ちょっとどういうことなのか、教えてほしいと求めました。","respondent":"武内税務課長","answer":"あるいは２３区ですと世田谷区で実施しているんですけれども、「納期を過ぎているんですけれども、お忘れではないですか」という形でやっております。品川区も、徴税職員が抱えている件数も多い中で…","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"まさに生活丸ごとそのもののプライバシーの固まりですから、私は、外部に委託というのはあり得ないなと思っているんですけれども、私の意見です。コールセンターはどういうものなんでしょうか、もう少しお願いします。","respondent":"武内税務課長","answer":"ここに書かれている以外で何か検討されているのかという質問がありましたので、それを外部委託だとか、何とかという部分にまでは行っておりません。自治体でやっている部分を勉強しながら進めていきたいということで、今後、注意しながら検討していきたいというふうに考えていま…","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"その把握はどういう方法で行っているのか、国民健康保険料で結構ですから、少し詳しく教えてほしいと求めました。３,０００件とありましたけれども、滞納世帯の理由の多いもの五つで結構ですから、それもあわせてご説明いただけますか。","respondent":"原国保年金課長","answer":"今はこういう状況でお支払いができないという話であれば、じゃあ、どうしましょうかということでのご相談がそこから始まると認識しております。そういうところを入口にしながら対応しています。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう一度、確認させていただきたい。改めて伺いたいのは、なぜこういう調査をするのか、その目的をどこに置いているのか。","respondent":"原国保年金課長","answer":"それから、調査の目的ですけれども、やっぱり相手のあることですので、当然、保険料を支払ってくださいという一方通行の話ではございません。相手の状況を聞く中で、相手はどういうふうに訴えているのかというのを聞きながら、そういう中でのカウントということで意識しています。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"それについて、１点、お答えほしいと求めました。相談する機会があったりするわけですから、国民健康保険料の滞納の傾向みたいに追っているのかどうか、そこもあわせて教えていただけますか。","respondent":"武内税務課長","answer":"ちょっと説明がうまくできなくて申しわけないんですが、ちょっとその辺、訂正をします。主な徴収の取り組みの１番目に、説明の中で、その辺の対応をするという中身を含んでおります。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"しかし、なぜ特別区民税や介護保険料の滞納については、そういう傾向を把握しないのか、それは非常に疑問です。それ以上にきめ細かな滞納者の実態の把握を進める必要があると、私は思うんですけれども、いかがか尋ねました。","respondent":"武内税務課長、蓼沼高齢福祉課長","answer":"本人が死亡して、執行停止ということで、それぞれ不納欠損ということで落とさせていただいています。そういった意味では、そのような状況で、滞納者の状況を把握できるのかなと考えております。 平成１２年当時で言えば、ちょっと考え方が違うのかなという気がいたしますけれども、手をこまねいて見ているということではありません。いろいろ客観的な情勢分析については、もちろん、今後…","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"それがどういう割合で、どういう状況で区民の中に広がっているのか、カウントをしていかないとつかめないと思うわけですよ。改めて伺いますけれども、再度、いかがか尋ねました。","respondent":"武内税務課長、蓼沼高齢福祉課長","answer":"今後、プログラムの改修を見て、できるようにしていきたいなと考えています。 滞納の件については、適宜、ケース・バイ・ケースで対応してきているです。今後、実態把握については、検討課題とさせていただきたいと思います。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"滞納者の実態をきちんとつかむために相談が大事だと、払えないその原因が大事だと言っておきながら、そこのカウントをなぜ進めていかないのか。理由を把握することがなぜ必要でないのか、ぜひやるべきだと思うんですけれども、介護保険料のほうはいかがか尋ねました。","respondent":"蓼沼高齢福祉課長、日下部企画財政課長、福田企画部長","answer":"先ほど、申し上げました半分弱の方が７５歳以上の後期高齢者ですから、国保と税とは考え方が少し違うのではないかなと考えております。ただ… お答え申し上げましたように、制度上のいろいろな特色、違いがあるわけです。我々としても共通の課題でもありますので、その辺は今後… これからのことを考えましても、減免のありようにつきましては、非常に限定的に考えざるを得ない。このことをご説明をさせていただきたいと思います。","id":"exchange-021"},{"speaker":"林委員","kind":"質問","question":"平成１６年度の調定額が３１３億円ですね、平成１６年度の収入済額とは書いてないけれども、それが２８８億円。およそ２５億円弱になるんですけれども、滞納されている額というのはどういうふうな計算で出てくるのか、最初に説明を求めました。","respondent":"武内税務課長","answer":"この表の中で、今、委員が言われたところで、わかりづらいのは不納欠損というのがあります。","id":"exchange-022"},{"speaker":"林委員","kind":"意見","question":"２８８億円の収入額があって、その数字がどうなって、この表のどこに載っているかという説明をしてくれればいいんです。あちこちからいろいろなものを持ってこないで、持ってくるなら、すっきり最初から全部持ってきてくださいとの意見を述べました。","respondent":"武内税務課長","answer":"この収入率につきましては、調定額に対して2)の収入額で割り算していただきますと、９２.０３％という収入率が出てくるんです。","id":"exchange-023"},{"speaker":"林委員","kind":"意見","question":"これは平成１６年度に収入できなかったものが、平成１７年度に滞納額として出てくるわけですよね。収入された額が２８８億円強、３１３億円引く２８８億円から不納額を引くと、この２２億円になるんですということを聞いているんですとの意見を述べました。","respondent":"日下部企画財政課長","answer":"今、この内訳について確認しておりますので、確認次第、またご報告をさせていただきたいと思います。","id":"exchange-024"},{"speaker":"林委員","kind":"質問","question":"担当の全職員が一致してというふうに(3)で書かれているんですけれども、滞納を徴収するための仕事しかないのか、どうか。その辺を聞かせください。","respondent":"武内税務課長","answer":"その企業のほうの対応と、滞納者で区外に引っ越してしまう方がいますので、その方たちを担当する整理第三担当で７名います。差押をしまして、換価をしなきゃいけないというような状況が生まれたときの対応としまして、合計で２７名が日々滞納整理の業務に当たっております。","id":"exchange-025"},{"speaker":"林委員","kind":"質問","question":"僕は、特別徴収額は９９.９％ぐらいに聞いているんですけれども、滞納というのがあるんですか。それも説明を求めました。","respondent":"武内税務課長","answer":"普通徴収が１２２億円、特別徴収が２１３億円でございまして、９９.６７％の収入率です。普通徴収につきましては９５.７０％です。","id":"exchange-026"},{"speaker":"林委員","kind":"質問","question":"担当の方たちというのは、専門職じゃないわけですよね、払ってくださいとかいろいろ。そういう作業のこつというか、そういうものについては、ノウハウを持ってこの仕事に当たられていると理解しておいていいか尋ねました。","respondent":"武内税務課長","answer":"税務についての内部研修を進めまして、秋口に２週間ほど、内部の会議室で専門研修ということで進めております。そのほか、２３区、特別区の研修所で行う研修、あるいは、東京税務協会で行う研修等、積極的に行かせるようにしております。","id":"exchange-027"},{"speaker":"林委員","kind":"質問","question":"奨学金ですか、そういうようなことで、徴収が進んだというような話を聞いたことがあるんです。相手にといっても、固いというのがやっぱり一番印象的なわけですから、その辺はいかがですかね。","respondent":"武内税務課長","answer":"そのように、機会あるごとに、収納の関係をやっている部署は、区の中でもさまざまなところにありますので、連携するところには連携をとっていきたいなと考えています。","id":"exchange-028"},{"speaker":"林委員","kind":"質問・要望","question":"僕の聞き間違えだったら訂正していただきたいんですが、平成１８年度ですか、実施した額は５億１,３００万円というふうに聞いたんですけれども。今、手元でわかりますか。","respondent":"武内税務課長","answer":"７７３件で５億１,０００万円という金額は、そういった意味で、平成１８年度に差し押さえた件数は７７３件になっています。実際的には、７７３件うち換価しているのは５４件で、４,０００万円ぐらいの金額を換価しております。","id":"exchange-029"},{"speaker":"林委員","kind":"質問","question":"そうすると、最初の回のときは多少端数計算で多くなるけれども、単純に２万円だとすると、５,０００円ずつ４回納める。カードでも払えるとなるんだけれども、カードの利用というのは、今考えていらっしゃらないんか尋ねました。","respondent":"武内税務課長","answer":"カードというのは、クレジットカードという意味合いでしょうか。","id":"exchange-030"},{"speaker":"林委員","kind":"質問","question":"だって郵便局の振替は、手数料は役所持ちでしょ。そうなってくると、可能じゃないのかなと思うんですけれども、検討の余地はないか尋ねました。","respondent":"武内税務課長","answer":"今、委員が言われたように、ご自分で振込手数料を支払う、区の振込先を教えてくれという場合については、当然、現状でもできますけれども、区のほうで手数料を持つという部分については、今のところ、考えておりません。","id":"exchange-031"},{"speaker":"林委員","kind":"質問","question":"例えば僕が、さっき言った５,０００円をカードで振り込んだら、僕が区民税５,０００円振り込んだというのはわかるわけじゃないですか。しつこいようだけれども、もう１回だけ。","respondent":"武内税務課長","answer":"ほんとうに私の認識不足というか、研究不足で申しわけないんですけれども、さまざまな形で研究していきたいと思います。","id":"exchange-032"},{"speaker":"林委員","kind":"質問","question":"できれば平成１８年度だけでも、滞納というものが生まれる歳入、そうするとなぜ滞納が起きるのか。額でも、次まででいいですから、お願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"阿部委員","kind":"質問","question":"お話がございましたので、ちょっと伺っておきたいといいますか、一言申し上げたいと思います。そういったこととのバランスということも考えて、ぜひ今のバランスでいいのかということもお考えほしいと求めましたが、いかがか尋ねました。","respondent":"武内税務課長","answer":"基準が定められておりまして、そういった中で、地方公共団体が条例を制定して執行しているわけです。その部分は、やはり税の部分については、特に品川区単独で税率を決めていくという考えはありません。","id":"exchange-034"},{"speaker":"阿部委員","kind":"質問・要望","question":"一体、徴収事務と比べて、同じだけのタイトさを持って行われているかどうかという話をさせていただきました。そこの縦でのバランスということも、ぜひ考えていただきたいと、要望も兼ねた質問をさせていただきました。","respondent":"日下部企画財政課長","answer":"ただ、やはり、全体の区政運営をどうやって公平、公正に進めていくかと。税務課長がご説明させていただきましたけれども、そういった点の基本的な考え方というのも抜きにはできませんので、このように考えているところです。","id":"exchange-035"},{"speaker":"金野委員","kind":"質問・要望","question":"配慮も含めて、研修内容までは細かく伺いませんが、その点をぜひお願いしたいと思います。今までの答弁の中でいろいろと伺いましたので、丁寧にぜひ行っていただきたい、意見を述べさせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"鈴木（真）副委員長","kind":"確認","question":"先ほどの差押の件で、ちょっと確認だけさせてください。質問の中でも、７７３件の５億１,３００万円とありましたが、その辺がどういうバランスになっているのかなということ。","respondent":"武内税務課長","answer":"押さえてもほとんど公売することは難しいんですけれども、それが６９件ということで、７７３件という数字になっております。７７３件という数字は、そういう複数のものを差し押さえたりする場合もありますので、これは実人員ではありません。","id":"exchange-037"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"例えば７７３件のうち４００件か５００件か、極端に言えば、もっと少ない数字になるのかなということで聞いたんです。引き続きもう１点、絵画２件と言ったんですけれども、どうなっているのかということをお願いしますとの意見を述べました。","respondent":"武内税務課長","answer":"絵画の２点ですけれども、そこに掲載させていただきましたけれども、残念ながら応募はありませんでした。ということで、その物はご本人にお返しさせていただきました。","id":"exchange-038"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"逆に現金が入ったから返したということですか。それからもう１点は、やっぱり、どのぐらいの人数に対してやっているのかというのは把握しておいてほしいという感じがするんです。","respondent":"武内税務課長","answer":"先ほど来の人数の件につきましては、またその辺、検討をして、わかるようにしていきたいと考えています。絵画商に見せて５万円だとかといっても、現金で払っていただくようにということも含めて、ご本人にとりあえずお返ししたということです。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"そういった総合的なところを、企画部ではどう分析をしながら見ていくのか。だから、そう意識をどう持って分析をしていらっしゃるのか、ちょっと最後ですが、そこをお伺いしたいと思います。","respondent":"福田企画部長","answer":"それから、年２度のことではありますが、世論調査を総合的な角度から実施をしております。私は思っておりまして、やはり行政が総合である以上、区民の声も総合的にお聞きする必要があると考えております。","id":"exchange-040"},{"speaker":"石田（慎）委員","kind":"質問","question":"歳入に関することの中での１番の(3)に、世田谷区で実施されているというふうに伺ったんですが、品川区の９４.５１％よりも高いのか。インターネット等での徴収等のお考えがあるのかどうか、お聞きしたいんですが、。","respondent":"武内税務課長","answer":"平成１８年度末で、品川区は６位で、世田谷区は８位という数字でございました。東京都のほうでも積極的にインターネット公売というのを進めておりまして、あるいは、品川区もそういうものに参加していきたいと考えております。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/471723?Template=document&Id=5824#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":39143,"voices":120}},{"id":"h19-20070829-16","meetingId":"h19-cm08","date":"2007年8月29日","dateIso":"2007-08-29","committee":"街づくり特別委員会","time":"午後１時０４分～午後４時３７分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"今、新馬場の入り口から行くと言ったんだけど、どうせ標柱とかいろいろあるなら、八ツ山の入り口から歩いてはどうですか。そんなちょっと歩いてもらうというんじゃなくて、八ツ山の入り口から全部歩けばどうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]},{"id":"topic-02","title":"はじめに、地区計画に関することのうち、景観","agenda":"はじめに、地区計画に関することのうち、景観","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ほかにそのような条件が整いつつある地区があるのかということと、このモデル地区として指定されるということの条件といいますか、そういった考え方があれば教えてほしいと求めました。","respondent":"阿部都市計画課長","answer":"まちづくりに従来から取り組んだ、あるいは現在も熱心に取り組んでいるということが、まず一番必要な条件だろうと考えています。その中では、先ほど申し上げましたけれども、それを今後ほかの地区にどういうふうに波及させていけるのかということを考えていきたいと考えています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"区としての独自性というのは、区としては今どのようなものを独自的なものと考えているのかお聞きしたい。まちとしてどう統一してやっていくか、そこら辺で区としての具体的な何か援助みたいなものはされているのかということをお伺いしたいと思います。","respondent":"阿部都市計画課長","answer":"それとあと、具体的にどういう形で聞くかは別にこれからの検討ですけれども、全区的な意見の聞き方も必要になってくると考えております。費用の援助はあるのかですけれども、それはございません。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"費用を出すか出さないかというよりも、区として手だてとして何か援助をしていることがあれば、その援助の方法を教えていただきたい。平成１８年で５回、平成１９年で３回開かれているということなんですけど、大体いつも何人ぐらいの方が参加されているのかをお伺いしたいと思います。","respondent":"阿部都市計画課長","answer":"メンバーにつきましては、景観まちづくり会議全体では約２０人です。幹事会につきましては、それより少ない１０人程度です。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"この都から助成をしていただいて今回の事業をやることになると思うんですけれども、わかっている部分で、このような都から助成を得て、商店街ですとかの改装をやった例があれば、ひとつ教えてほしいと求めました。","respondent":"金子産業振興課長","answer":"これについては、東京都としては例示という形でさまざまこういう補助がありますと出してきています。空き店舗対策に関しましては、今回は地域連携ということで、これが大がかりに店舗改装の助成をした草分けではないかと考えています。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問・要望","question":"都から助成を得た場合に、規制というんでしょうか。例えば、何年間は同じところに助成は出せないとか、そういうような規制があるのであれば、教えていただきたいんですけれども。","respondent":"金子産業振興課長","answer":"改修した場合に５年以内については、年によって減っていくんですけれども、返還義務が発生いたします。そういったものは対象になりませんが、いわゆる固定資産系のものに関しましては、そのように５年が基本的には返還義務の発生する年限です。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問・要望","question":"そういうような検討を進めていただきたいということと、例えば、そのような箇所がないような整備をしていっていただけたらと思います。要望だけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"今回はなぜこういう形か。これはいろいろ種類があって、その中の１つとしてモデル商店街事業という形になっているのか、そういうものを教えてほしいと求めました。","respondent":"阿部都市計画課長、金子産業振興課長","answer":"当然、そこで一定の方向が出されたら、次の段階としては当然もう少し広い地域の方の合意形成を図っていく必要があると考えています。こういう計画にしていきたいとか、そういうものがまとまった段階では… 地域興しやまちづくりに取り組む事業を支援すること」と、こういったものが対象になっておりますので、一応かなり幅広いもので考えてあります。東海道の石畳も５００ｍ部分はできていたわけですが…","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"まちづくり協議会の件ですが、どこが一番決定権を持ってくるのでしょうか。どういう形式で、最終的な決定はどういう流れで決定されていくのかという、そういう長期的な計画があるのかどうかをお聞きしたいと思います。","respondent":"阿部都市計画課長","answer":"それは順次進めていきたいとは考えてありますけれど、今のところ、まだほかの地域からはそういう要望がございません。まずは、先ほどご視察いただいたところをモデル地区にして、具体的な検討を進めるです。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"そこのところにそれなりの景観を保全していくべきじゃないかと、どういうふうにとらえていったらいいのか改めて品川区の考え方を伺いたいと思います。それとも、行政独自で１つ１つのまちの状況に合った景観を推進していくということもあり得るんか尋ねました。","respondent":"阿部都市計画課長","answer":"ただ、景観計画をつくるのは１つのまとまりのある地域でやっていきますので、そこの地域に住む人々の合意形成が必要になってくるだろうと思います。そういう意味で、区だけではなくて地域の方々の参加というものが当然必要になってくるだろうと思っています。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"そういうものを立ち上げてやっていこうじゃないかという機運が出て初めて区のほうと議論が始まってスタートしていくという考え方ですか。もっともっと積極的に品川区としてリードして、住民の機運が立ち上がらなくてもそういう事業は進めていくということもあるということなんか尋ねました。","respondent":"阿部都市計画課長","answer":"私どもとしては、１３地域センターで町会長会議を開かれますので、その１３地域センター全部でこの景観ガイドプランの説明をいたしました。まずは今申し上げましたとおり、まちの方々が、今後もそういう形で進めさせていただきたいと思っています。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"旧東海道にふさわしいまち並みをつくろうということでやってはいただけているんですが、実際にやっぱりこれは相当年月がかかるのではないかと。そして、本当はできるだけ早急に対応策ということを考えなければいけないんだと思うんですが、その辺は何かビジョンとしてあるんか尋ねました。","respondent":"阿部都市計画課長","answer":"例えば新築とか大幅な増改築とか、そういう際にやっていくだろうと思いますので、そういう意味ではかなりかかるだろうと考えています。前回この委員会でもご報告いたしましたけれども、長い時間がかかるかもしれませんけれども、一歩一歩やっていくことが大事だと考えています。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"地域の方、それからもちろん法人もそうなんですが、そういう方への呼びかけはやってはいないんでしょうか。今後、区としてもこういうふうにできるだけ早急にやっていきたいというような対案みたいなものがありましたら、説明を求めました。","respondent":"阿部都市計画課長","answer":"地域全体のさまざまな方が入ってまちづくりに取り組んでいるですので、そういう意味ではさまざまな方の意見を聞くことができると考えています。当然のことながら地域の方々に広く景観まちづくりの今検討している考え方を理解していただいて協力していただくということが必要であ…","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"要望なんですが、品川区で本当に景観形成を早急にやっていただきたい。できるだけ事業が早く進むように、品川区もまちづくり協議会のほうにさらに一層の協力をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１つは、今一番大きく旧東海道に求められているのは、都市型観光をどうしていくかというところが非常に必要なところなんだろうと。景観まちづくりとほかのものも絡ませてもいいけれども、観光に向けては今、区としてはどう考えているのかというところだけを説明を求めました。","respondent":"金子産業振興課長","answer":"そういった景観の部分の整備であるとか、さまざま考えられると思いますけれども、そういう意味では緒についたばかりと考えております。これからもそういった意味では全区的に観光施策を推進していくために努力していきたいと考えています。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本来、皆さんスタート時点ではそういう意識を持って熱く語っていたわけですから、そういうチャンネルの中でこういうことをしてみたらどうですか。要望でいいです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"資料の３ページでも届出・勧告の対象になる地域ということで２つに分けて、この検討の中で、条例化というのは今後検討されていくものなんでしょうか。もし検討されていくものとすれば、どういった条例のイメージになるのかということをつけ加えてほしいと求めました。","respondent":"阿部都市計画課長","answer":"ですから、条例に反する建物を建てるということになれば、それは「変更してください」という変更命令までできるという形になります。その条例を定めると考えていますので、中身は何を決めるかは今後の検討ですけれども、そういう変更命令もできるという条例になっているです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"南品川３丁目地区では今、そういった具体的な制限を定める地区計画などが検討されている段階ですけれども、その地区計画との兼ね合いはどういったものなのか尋ねました。","respondent":"阿部都市計画課長","answer":"ですから、南品川３丁目の地区計画で定めておりますのは、それが南品川３丁目の地区についても適用になるという形です。地区計画で具体的に定めるものではなくて、今申し上げた景観条例の中で具体的に定めまして、それを南品川３丁目についても適用するというものです。","id":"exchange-018"}]},{"id":"topic-03","title":"八潮地区","agenda":"八潮地区","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"各クラス１０名定員ということなんですが、指導する先生はどういう人数で対応されるのか、そこも含めて教えてほしいと求めました。それから、子どもたちが通学する範囲というのは、品川区民だけではないんじゃないかと思うんですけど、改めてそこも伺いたいと思います。","respondent":"古里学務課長","answer":"これらも含めながら慎重に検討をしていくべき事項ということで、今いろいろな調整をしています。品川区に転居をして、この学校に通わせたいという要望を非常に強く持っているということは、関係者から聞いてあります。","id":"exchange-019"},{"speaker":"南委員","kind":"確認","question":"具体的になったら、その辺も文教委員会も含めて教えていただければとお願いをしておきたいと思います。それから集会所施設については、そういう考え方を持っていると理解したんですけれども、そういうことでいいのかという確認をしておきたいと思います。","respondent":"古里学務課長","answer":"八潮地区の住民の皆さんから出されていた八潮北小に対するそうした要望については実現する方向で、この八潮北小を活用する場合は対応してほしいということは強く申し上げているところです。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つか教えていただきたいんですが、私立の学校という運営理由と、予算とかそれはどういう形になっているのかというところ。その私立のろう学校と品川区との関係はどうなっているのかを教えてほしいと求めました。","respondent":"古里学務課長、日下部企画財政課長","answer":"この東京都から学校の設置に当たって、「品川区で学校を提供するという協力ができないか」ということが以前ございまして、この間の経緯があるです。そうした経緯から、品川区として引き受けをしたです。 柵の設置の経費等についての取り扱いでありますけれども、区有財産を貸し付けるということになります。東京都ともいろいろ調整を今進めているところでありますけれども…","id":"exchange-021"},{"speaker":"西本委員","kind":"質問・要望","question":"私立学校に対してということになると、ある程度私学助成という形で入れるにしても、そこを経営しなければならない。財政的なところの考え方といいますか、品川区としての立場をどういうふうに考えているか、もう一度教えてほしいと求めました。","respondent":"古里学務課長","answer":"４,５００万円の目標ということで、大きな企業にも呼びかけをし、幾つかの企業から了解する旨の回答を得ていると聞いてあります。継続的な企業からの支援、これらを充てて、現在の段階では学校経営に必要な経費は十分に毎年毎年用意することができるということは確認をしていま…","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"それからもう１つ、やはり地域に根差したというところで、八潮地区の方たちとうまくいかなきゃいけない。その場合に、八潮地区の方たちは優しいですから、その辺の地域とのかかわり方についてはどういうふうな考え方を持っているんか尋ねました。","respondent":"古里学務課長","answer":"もう１つ、先ほど開かれました八潮まつりの中で、たまたま私は八潮北小の芝生の管理をしていただいているおやじの会の方とお会いしました。今後も継続して、そういう声を背景にしながら、地域との関係づくりも私のほうできちんと指導してまいりたいと考えています。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり、子どもたちとその地域の皆さんと一緒に健全育成という形にしていただきたいと考えています。なるべく入りやすいような、そういう方向でアドバイス等々をしていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"}]},{"id":"topic-04","title":"（仮称）マイガーデン南大井利用者募集","agenda":"（仮称）マイガーデン南大井利用者募集","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"切ってしまうようなことはできるだけなくしていただきたいと思っているんですけど、ちょっとその関係を１つ。それ以降もマイガーデン南大井として利用を提供していくということかどうか、ちょっとその辺を確認したいのが１つ。","respondent":"藤田道路公園課長","answer":"適切な場所が見つかれば、今の段階で今回の１回限りの募集で終わりにするとか、そういったことは考えてございません。区民の皆さんに提供していきたいと考えています。","id":"exchange-025"},{"speaker":"南委員","kind":"確認","question":"そうであるなら、なぜ１３カ月なのかなというのが、ちょっと１つわからないんですけど。もう１つ伺いたかったのは、改めてちょっと確認したいのと、その辺はどうだったのかを伺っておきたいと思います。","respondent":"藤田道路公園課長","answer":"マイガーデン豊町等も含めますと、おおむね毎年３００件ぐらいの使いたいというようなお話をいただいておりますので、私どもとしては考えていない。ただ、違う別な場所についてもご相談に応じながら活動できる場所を私どもも探し…","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/823348?Template=document&Id=6350#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":28284,"voices":75}},{"id":"h19-20070921-4","meetingId":"h19-c-settlement","date":"2007年9月21日","dateIso":"2007-09-21","committee":"決算特別委員会","time":"午後４時３６分～午後４時４５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/570060?Template=document&Id=1274#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":2254,"voices":18}},{"id":"h19-20070925-6","meetingId":"h19-cm09","date":"2007年9月25日","dateIso":"2007-09-25","committee":"区民委員会","time":"午前１０時０３分～午後３時１５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を76件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この専用の資金に変更されるということで、特に何か不利益となるような影響というのは考えられるんでしょうか、考えられないんか尋ねました。","respondent":"金子産業振興課長","answer":"従来と違って１００％信用保証協会の保証が、金融機関が２割負担するようになるということから、不利益が発生することはないかと思います。従来５００万円が限度額でしたが、平均で言うと３００万円程度ですので、そういう意味では不利益は発生しないだろうと予測しています。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、利率の低いほうは使えなくなる方も一部出るのかなという気がしました。さっきの広報と紹介状の関係だけ、ちょっともう一回確認だけさせてください。","respondent":"金子産業振興課長","answer":"金融機関の方々を集めまして、一応説明会を開いて金融機関のほうの理解を十分深め、誤解のないような形で説明会を開いているところです。この２７日、２８日、そごのないようにしていきたいというふうに考えてあります。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１,２５０万円という枠が小口零細企業保証制度の中にあって、借りる、借りない、希望したときに、本人申請だけなんですか。そこら辺はどういう対応をなさるのかなと思ったんですけど。","respondent":"金子産業振興課長","answer":"ただし、自治体としてはわかりませんので、これを保証協会に問い合わせなければならない。保証協会は、問い合わせが来た場合には速やかにそれを回答すると、利用者の方の不便も最小限にとどめられるかなというふうに考えてあります。","id":"exchange-003"},{"speaker":"山路委員","kind":"質問","question":"先ほど総合的に判断するということですからね。そこの状況をちょっと聞かせていただけますか尋ねました。","respondent":"金子産業振興課長","answer":"３区については、もうしばらく様子を見るという対応になっております。やはり２０区とかなりの区が対応を早めたのは、先ほど申し上げましたとおり、貸し渋りの発生が懸念されて利用者に融資が制限されると。","id":"exchange-004"},{"speaker":"山路委員","kind":"質問・要望","question":"例えば中小企業が融資を受ける場合に小規模に当てはまらない３０人ぐらいの企業が融資を受ける場合に、そういうことがないように銀行と交渉されるかどうか、その辺の対策についてのお考えをちょっと聞かせてほしいと求めました。","respondent":"金子産業振興課長","answer":"これにつきましては、東京都につきましては、１００％のものについては０.２％アップするという動きになっています。ただ、２３区、ほかの区の状況も伺ってみますと、ほとんどの区で２３区の中では利率を変更するところは少ないように聞いております。","id":"exchange-005"},{"speaker":"山路委員","kind":"質問・要望","question":"１０月スタートの際に関して、利率はアップしないということで安心かなと思いますけど、来年度に利率がアップされないようなやっぱり担保といいますか、そこまでしっかり交渉していただきたいということと、焦げつきというのは、現状でどれくらいあるか、ちょっとわかったらお知らせください。","respondent":"金子産業振興課長","answer":"この利率というのは交渉してまいりますので、あまりここの利率にはね返らないような形で交渉していきたいというふうに思っているところです。これの金額が単年度ごとになってしまいますが、直近の平成１８年度では、国全体で６,８５１億円というふうな規模になってあります。","id":"exchange-006"},{"speaker":"山路委員","kind":"質問・要望","question":"中小企業にとって使いやすい性格、使いにくいというイメージを与えないように、使いやすい制度にしていただきたいということを要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"飯沼副委員長","kind":"質問","question":"その辺のところの不利益が生じるのかどうかというのが１点と、その辺で、今までの小規模企業特別事業が全部ここの枠に行くということなんですか。(2)のところのソフトウエア業と情報処理サービス業の業種区分の変更、ちょっとこの辺はどういうことなのか教えていただけたらと思います。","respondent":"金子産業振興課長","answer":"ただ、私どもとしましては、当然そういうことのないように保証協会と連携を通じて対応していきたいと思っています。中小企業信用保険法のほうの定義に基づいて対応をするというのが国の統一の方針でしたので、こちらのほうの定義に基づいて定義を変更したところです。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"品川区に１５６組合があるということを聞いたんですが、組合員の方は何人ぐらいおられて、あと、補助金が１５０万円ということですけれども、それは事務経費ということだったと思うんですけど、実際どのようなことに使われているのか尋ねました。","respondent":"武内税務課長","answer":"１５０万円はそれぞれ品川・荏原と約半分ずつ補助金という形で支出しているわけですけども、さらに会報、それぞれの会で会報の冊子を発行している。そういう部分で補助金は支出されております。","id":"exchange-009"},{"speaker":"安藤委員","kind":"意見","question":"１０月１日から郵政民営化が実施されますので、郵政民営化自体はやはりユニバーサルサービスを維持するという確約がなかなか果たされない状況の中で強行されてしまうので反対なんですが、今回文言整理ということですので賛成ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"改定目的のところの1)と2)の関係がわからないので教えていただきたいんですけれども、収集運搬部門というのが2)で言うところの一応現行で５０kg未満の中小事業者ということで、それ以上のところと考えてよろしいんか尋ねました。","respondent":"秋山資源循環推進課長","answer":"負担いただいている２８円５０銭／kgの内訳が、収集運搬部門が１６円／kgで、処理処分部門が１２.５円／kgです。日量５０kgというのは、ごみを１日５０kg以上出す方については、収集運搬業者のほうに出していただくです。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"例えば、ちょっとやっぱり何が大規模事業者なのかどうかというのがわからないんですけれども、どのような負担の変化があるんでしょうか。この辺を説明を求めました。","respondent":"秋山資源循環推進課長","answer":"１０枚セット、１０ｌから７０ｌありますけど、平均で２４４円の負担増ということになるかと思います。どれぐらい使うかですけれども、週に１セットであれば週に２４４円の負担増です。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"負担増になってしまうということなんですが、今回新たに５０kgを４０kgに変えることで大規模事業者に変更になる事業所というのがどれぐらいの規模で予測しているのか教えていただけますか尋ねました。","respondent":"秋山資源循環推進課長","answer":"家庭系と一緒に収集をしておりますので、これについては詳しい重量であるとか数を、こちらのほうで把握ができてございません。収集運搬部門３１.３円と１６円の差額１５.３円については、税金、なるべくこの乖離を少なくしていこうというのが今回のご提案です。","id":"exchange-013"},{"speaker":"安藤委員","kind":"意見","question":"やっぱりどういったところに影響が出るのかということを事前にきちんと見ていかないと、ちょっとだめなんじゃないかなとすごく思うんですが、意見ということで終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の５０kgから４０kgすることによっての影響というのは、一般事業者に及ぶ数、そんなに影響が出ますか。そこら辺からまずお聞きします。","respondent":"秋山資源循環推進課長","answer":"日量５０kg、可燃ごみで５０kgですので、ほぼ影響がないのではないか。自己処理責任ということ、日量４０kgに下げましたので、指導の強化を行っていきたいというふうに考えております。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ごみ処理券で３,６００万円というプラスが出たと同時に、逆に分担金もマイナスが出ると思うんですが、その辺は見通しが立てていらっしゃるのか。それと、この分担金の割合ですけど、区の分担金の割合というのは人口割でしたか、ごみの排出量割でしたか、その辺を説明を求めました。","respondent":"秋山資源循環推進課長","answer":"分担金の計算ですけども、今ごみ量割になってあります。試算では２２億円ということになっておりますので、最終的に計算いたしますと、この分が幾らかというのはちょっと現時点ではわからないです。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問","question":"大田区でちょっと聞いたんですけど、品川に関しては、まだそこまで考えていないという部分でしょうか。今後見通しが何かあれば。","respondent":"秋山資源循環推進課長","answer":"大田区の一部地域の話ですけれども、京浜島、平和島、昭和島の３島だったと記憶しております。ただ、事業系については一般の業者で収集をいただきたいということで、区のほうから働きかけをしているということを聞いております。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問","question":"事務作業というか、向こうまで行って、どういう処理をするのか分からないですけどもその辺。あれは委託、それとも売ったときにお金を払うんですか、先に買い取り、その辺の状況をお願いします。","respondent":"秋山資源循環推進課長","answer":"取扱店のお手元の在庫というのは、特に負担になるということではありません。コンビニエンスストア、スーパーに関しては、本部またはベンダー経由でその辺の手続をとりたいです。","id":"exchange-018"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"まずその辺をお伺いしたいなと思うのと、あと資料３のところで、ルート１のところがなかなか進まないと先ほどご説明がありましたね。この辺が進んでいかない理由というか、ちょっとその辺、もうちょっと教えていただきたいんですが。","respondent":"秋山資源循環推進課長","answer":"食品リサイクルに関してご説明を申し上げましたので、現在逆にこのルートが非常にうまく回っているということでもあります。それから、ルート１につきましては、対象とするものによってかなり違ってくるのかなというふうに考えております。","id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"質問","question":"ルート１のところ、対象によって違う。その辺が進んだり、自治体の援助とかがあったら、ごみが減るんじゃないかなと思うんですけど、その辺はどうか尋ねました。","respondent":"秋山資源循環推進課長","answer":"大規模な施設に関しましては、食品リサイクル法で義務づけもありますので、それに従ってやっていただくということで、中小のものにつきましては、またこういう金額ですので、なかなか進んでいかないというのが現状だというふうに思っています。","id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問","question":"出てきたごみをどう処理するのかというよりも、７月にいただいた資料のところを見ると、若干減っているんですね。出されているところの声をどのくらい聞いていらっしゃるのかと、私はその辺にすごく注目をしたいんですが、いかがか尋ねました。","respondent":"秋山資源循環推進課長","answer":"ただ、例えば清掃一部事務組合は現在ちょうど２１清掃工場がすべて稼働しているということで、その辺の費用も膨らんでいるということもあります。シールの値上げ、先ほども申し上げましたように…","id":"exchange-021"},{"speaker":"飯沼副委員長","kind":"提案","question":"ご意見を聞かせてほしいと言ったら、まず最初に１kg４円なんですけども、上がるんですか。そうじゃなくて、もっと広く意見を聞いて区民の生活実態を把握した上で提案をしていくという姿勢が大事であると思うんですが、いかがか尋ねました。","respondent":"秋山資源循環推進課長","answer":"資料１でもご説明を申し上げましたとおり、乖離が１５円３０銭ということで、よろしくお願いいたします。","id":"exchange-022"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"特に小規模な事業者への影響が大であるというところでは、私はこれは見直していただきたいなと思います。意見です。","respondent":"川西委員長","answer":"ほかに発言がありませんようでしたら、以上で質疑を終了いたします。本件につきまして、各委員の態度・意見の表明をお願いいたします。","id":"exchange-023"},{"speaker":"安藤委員","kind":"意見","question":"そういうところに政治がやっぱり応援すべきところがあるにもかかわらず、そこに負担増という形で冷や水を浴びせるというのはどうかと思います。それがありとあらゆる税金という意味合いでもそうですし、そういった点からも、これに賛成するわけにはいかないということで反対しますとの意見を述べまし…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問","question":"一番響く個人商店の方とかが結構シールを買われて張るものですから、やはりこの値上げに関しては上がるのかというような話があると思います。ぜひ、周知、告知、徹底していただいて、４月にうまくいけるようになればと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"安藤委員","kind":"意見","question":"アクションプランのところなんですけれども、都市型観光拠点整備というところで、今回観光拠点を整備するというふうに至ったこれまでの経緯ということ、あとなぜ今回この場所になったのかという経緯もあわせて説明いただけるとありがたいんですけどとの意見を述べました。","respondent":"金子産業振興課長","answer":"私どもとしましては、さらに一層観光資源に磨きをかけるといいますか、一層の充実を図れるのではないかと考えておりました。今回タイミングよくといいますか、これを観光アクションプランの推進、観光案内所等々を設置して生かしていこうというふうに考えたところです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"財源のほうなんですけれども、都の支出金６０５万円が水辺の観光案内としてということでご説明があったんですけども、一般財源として残りであとその他というふうになっていますが、その他のほうが大分多いんですが、あとはどういうお金なんか尋ねました。","respondent":"金子産業振興課長","answer":"歳入に関しましては、当委員会の所管ではないというふうに思っておりますが、ご説明を申し上げますと、その他６,５００万円につきましては、公共施設整備基金から一般会計に繰り入れて支出するものです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"意見","question":"もう少しどういったものなのかというのを知りたいなというのと、しかも多量に取り入れていってほしいと思うんですけども、声を導入していこうと考えておられるかということもあわせて説明を求めました。","respondent":"金子産業振興課長","answer":"その意味では、地元の方々等々のご意見を参考にしながら、区として決めていきたいと考えています。特に地元におきましては、こういった方々からも意見を聞きながら進めていきたいというふうに考えてあります。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今度は基金がもうなくなってしまうということでよろしいんですか。今検討されている中に入っているかどうか、もし入っていれば、どの辺まで詰めているか説明を求めました。","respondent":"金子産業振興課長","answer":"石畳部分、あるいは商店街の装飾灯、ゲートの部分は商店街の補助事業として私どもも緊密な連携をまちづくり事業部とあわせて実施しています。所管は都市計画課ですけれども、緊密な連携をとって事業を進めているところです。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"確認","question":"契約していた相手先が変わったということの影響もあるのか、それともそれは全然関係なしに時期として省エネ対策であるのか、確認させてください。先日、ケーブルテレビに台場小学校でやったということで出たんですけど、ぜひこれもこれから進めていっていただく上で、確認だけお願いします。","respondent":"金子産業振興課長、鷹倉区民課長、久保田防災課長","answer":"昨年の例を考えましても、すべて終わってからになりますので、年度末かあるいは事業が完了してのタイミングになります。… 中央監視装置の関係ですが、丸井から新たな業者に変わったことが影響しているのか、このようなご質問かと思います。これにつきましては… 当初今年の春からこの一般放送化というのを予定していたんですが、というのが、放送業界がやはり相当懸念の声明を出しておりました。…","id":"exchange-030"},{"speaker":"山路委員","kind":"質問","question":"ＮＨＫの話をされましたけど、例えばテレビがとまっているときには、これは稼働するんですか。将来は各家庭にも欲しい人とか、いると思いますが、値段というのはどれぐらいするんか尋ねました。","respondent":"久保田防災課長","answer":"今いろんな例えばＮＴＴなり、あるいはドコモとも携帯電話を利用したサービスとか、いろんな検討というか開発に入ったというふうには聞いております。ただ、その辺は今後やっぱり半年間かけてじっくり検証しながら、その辺はやっていきたいというふうに考えているところです。","id":"exchange-031"},{"speaker":"山路委員","kind":"質問・要望","question":"警報していくというシステムだったんですけど、研究中とも言われていますけど、このモデルではどういうことをされるかということをまず聞きたい。１台の値段が、値段は１５台で３６０万円とさっき言われましたけど、今回やられるモデルの状況をちょっと説明してほしいと求めました。","respondent":"久保田防災課長","answer":"例えば学校だったらこういう対応、それぞれ一般的に代表となる対応の仕方のマニュアルづくりを実はやっていきたいなというふうに考えております。それこそ職員だけじゃなくて…","id":"exchange-032"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"５１％はどこが持っているのか、中身を教えていただきたいのと、その他の産業振興に関しての効果というのがどのくらい上がっているのかな。その辺を教えていただきたいのと、どのようなアクションを起こしたらいいのか、ちょっとその辺を説明を求めました。","respondent":"久保田防災課長、鷹倉区民課長、金子産業振興課長","answer":"一応年度内でそういう形を出したとしても、さらにそれを来年度つなげて、より確実なものにしていきたいというふうには考えております。 品川区の負担、正確にいいますと、４８.８６％。２３名いらっしゃいますが、この方々が２０.４７％、このような形になっております。 計算、計測しているわけではありませんけれども、品川区全体のイメージアップにもつながっているかどうかというふうに考えているところです。…","id":"exchange-033"},{"speaker":"飯沼副委員長","kind":"質問","question":"総合区民会館きゅりあんのところなんですけれども、丸井が３０.６３％、その他２３名の方が２０.４７％ということで、丸井の３０.６３％というのは、次にあそこに入る方のところと話し合いは決まっているということか尋ねました。","respondent":"鷹倉区民課長","answer":"先ほど申しましたとおり、新たな事業者がこの組合、理事会での決定による、こういうことです。","id":"exchange-034"},{"speaker":"安藤委員","kind":"提案","question":"低額の所得でありまして、生活が困難と認められた区民の特別区税を減免する必要があるということで提案ということです。区が納税が困難と認めた人を対象にするものでして、自治体として今せめてできることということで、今回の条例を提案させていただきましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"渡辺委員","kind":"質問","question":"その生活状況の調査というところでお聞きしたいんですが、こちらも当然調査対象になると思いますが、その辺現実を踏まえてどのような見込みになるのかお聞きしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"飯沼副委員長","kind":"提案","question":"提案者でありますので、私から。現在ある減免の制度のところでそういう調査があるということなので、生活保護と大体同じような調査というふうに受けとめてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"渡辺委員","kind":"質問","question":"行政の方からも状況を伺いたいんですが、今のお答えに対して、生活保護の対応と同等という中で、申請があってから、実際は調査期間は無限ではないと思いますので、その辺の期間とあと現実的にそれだけの期間の中で調査が滞りなく行われるか、この辺、現実に則した見込みをお聞きしたいと思います。","respondent":"武内税務課長","answer":"その１週間前が納期ですので、その１週間でその方の担税力というのを調査しなければいけないということですね。生活福祉課のほうでその辺の資産等の調査をしているということで、生活保護受給者についてはある一定の調査をした後、減免の対象になるです。","id":"exchange-038"},{"speaker":"山路委員","kind":"質問","question":"川崎市でそれが１％、２％ということですが、実際に申請に来る人はもっといるんじゃないか。どういう数値になるか、ちょっと検討つかないんですけど、区のほうでわかったら教えていただけますか。","respondent":"武内税務課長","answer":"川崎市の実態で安藤委員がご説明をされているわけですけれども、いわゆる機械上で計算をして、さらに担税力を調査するという現状なわけですね。今後のことを考えますと、やはり税の公平性ということを考えますと、この程度の該当者では済まないのかなというふうに考えております。","id":"exchange-039"},{"speaker":"山路委員","kind":"質問","question":"生活保護世帯収入以下の方を対象としますので、かなりの数に膨れ上がるんじゃないかと、この数というのは掌握できるんでしょうか。わかっているんか尋ねました。","respondent":"武内税務課長","answer":"まだ細かく計算しているわけではありませんので、条例非課税の今現状の枠の中で対象になっている方が、品川区で６万人ほどいらっしゃいます。１.３倍ぐらいの方がまた上乗せになるのかなというふうに考えますと…","id":"exchange-040"},{"speaker":"山路委員","kind":"質問","question":"そうなりますと、影響見込み額が２,０００万円では当然済まないわけですよね。地方自治体、品川区としては不可能じゃないかというふうに私考えるんですけども、区側はどういうふうにとらえられているんか尋ねました。","respondent":"武内税務課長、早津区民生活事業部次長","answer":"あるいは普通徴収の場合ですと、年４回の支払いになりますので、それを毎月納入ということで、１２回払いにするだとかというシステムもあります。品川区としては２３区の中で、こういうシステムを取り扱っているところはないということ… 対象になる方はおそらく万単位で、１万人の後半ぐらいの方が新たに対象に最大限でなるのではないかというふうに考えています。この方々の税額から考えますと、億単位、１億円を超えて２億円というような数字の規模の影響があると。","id":"exchange-041"},{"speaker":"山路委員","kind":"提案","question":"先ほどの現状の第３６条とあわせると、説明がさっきちょっとありましたけど、提案者はその辺に対してはどのように考えていらっしゃるかとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"安藤委員","kind":"意見","question":"なかなか第３６条の趣旨というのが生きていない状況ですので、そういった点ではあえてここでこういう具体的な記述を入れるということは、私はこの制度の趣旨を生かすことになるんじゃないかなというふうに思っておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"現実的に今の減免制度のところにおいては、申請を受けて、そのままはいそうですかと受けるわけではございません。財産をいっぱい持っている人なんかは除かれるわけですから、私は川崎市の例がかなり参考になる。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"山路委員","kind":"意見","question":"そうなってくると、本当に困っている人たちの減免は考えなきゃいけないけど、もっと国レベルで検討すべきことじゃないかなと思うんですね。そのことを考えますと、先ほど二重の基準にはならないということでしたけど、条文において不備があるんじゃないかという気がするんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今川崎の場合ということで、自分から申請という話でしたけど、先ほど税務課長のお話だと、チェックをするのに１週間の間でチェックするという話が出て、川崎市というのは、その辺の実態はちゃんとチェックなさっているのかおわかりか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"飯沼副委員長","kind":"意見","question":"川崎市の場合は、世帯によっての金額が表に出ていて、それ以下のところで。でも、申請書があって調査をするということですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えば品川だったら１週間の間でそれだけのチェックが本当にしきれるんですか。ただ、そこで公平性がまた欠けてしまうんではないかという点で、その辺はどうお考えか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"課長からご答弁をいただきたいなと思いますけれども、１週間でできるのかどうかというあたりは、その辺はいかがか尋ねました。","respondent":"武内税務課長、田中区民生活事業部長","answer":"基本的には税の公平性を考えますと、安易に減免という形はとっていない、そういうふうなことですけれども。 そこのところでは非常にきちんとした調査が資産活用も含めた調査が行われた上で保護が開始されるということになっているわけですね。非課税の基準をもう一つつくる、ダブルでつくるような考え方については法的には大変疑義がある…","id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"提案","question":"二重の基準というような話と、最初にお話しいただいたやっぱり生活保護対象者であれば税金の減免も当然わかる。現状、この条例提案の中では難しい問題があるのかなというふうに私は理解しましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"渡辺委員","kind":"質問","question":"提出者の方にまず伺って、理事者のほうに伺いたいんですが、情報があればお聞かせ願いたいと思います。自分も今年度の６月に新宿区のほうでやはり審議されたというふうに聞いていますので、その辺の情報を踏まえてお聞きしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"安藤委員","kind":"提案","question":"条例提案などは出されているんですが、まだ２３区でこのような減免制度としてつくられたことはないというふうに私は理解しております。税法上の問題なんですけども、これは地方税法の第３２３条のほうで定められている減免にのっとってつくっておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"飯沼副委員長","kind":"提案","question":"よりわかりやすくしたというところでご理解をいただきたいなと思います。２３区の状況では、あとのところはまだ実っていないという状況ですが、私どもぜひ品川から実現をしていきたいなと思って提案をしていますとの意見を述べました。","respondent":"武内税務課長","answer":"私のほうで把握している２３区の状況ですけども、第２回定例会において、先ほど委員が言われたように新宿区のほか２区がこのような提案をされて、今回第３回の定例会で品川区を含めて８区で出るのではないかという情報を私は得ています。","id":"exchange-053"},{"speaker":"鈴木（真）委員","kind":"意見","question":"東京都としては、政策として手当するほうが公平と考えるという答弁もあったようです。その辺を考えますと、この条例に対して私は賛同しませんということですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"山路委員","kind":"意見","question":"先ほどもお話にありましたけれども、二重の基準ができるとか、条文に不備があるんじゃないかということと、各区でもやっぱり否決されているようですので、この条例に関しましては、賛成できませんとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"稲川委員","kind":"意見","question":"現行条例が今区にある状況の中で、号を加えるというのは必要がないのではないかと。現行条例をもっとしっかり進めていくべきだと私は思いますので、特にどう追加するとかそういうものは必要ないと思いますので、私は賛成しませんとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"渡部委員","kind":"質問・要望","question":"今回条例が上がってきて、いろいろ内容を見させてもらいました。考えて、やはり国として何とかしてもらわなければならないというのが基本的な考えでありますので、今回は私は見送らせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"}]},{"id":"topic-02","title":"ありがとうございます。さよう進めさせていただきます。 それでは、請願第２３号、割賦販売法の抜本的改正を求める意見書を政府等に提出することを求める請願","agenda":"ありがとうございます。さよう進めさせていただきます。 それでは、請願第２３号、割賦販売法の抜本的改正を求める意見書を政府等に提出することを求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"啓発活動とか啓蒙活動とかをやっているんですけど、区のクレジット被害の現状などはどうなっておりますか尋ねました。","respondent":"鷹倉区民課長","answer":"それから、自社割賦がこれは５件。区レベルではそういう形の相談件数があった、こういうことです。","id":"exchange-058"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"紹介者で、質問ということではなく、今本当に丁寧にご説明していただいて、私は理解したつもりです。例えば４番の部分でクリーングオフできない、これを採択していただきたいということで、意見として。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"}]},{"id":"topic-03","title":"移らせていただきます。 それでは、請願第２５号および請願第２６号、小規模住宅用地の都市計画税の軽減措置の継続につき意見書の提出を求める請願","agenda":"移らせていただきます。 それでは、請願第２５号および請願第２６号、小規模住宅用地の都市計画税の軽減措置の継続につき意見書の提出を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"もしわかれば教えていただきたいのと、東五反田あたりも上がっているというふうに伺ったんですが、見解を説明を求めました。","respondent":"武内税務課長","answer":"２００m2以下の用地面積ということで、何パーセントぐらいあるのかという数字については、まことに申しわけないんですけども、把握しておりません。やはりみんなが住みたいという東京ということで…","id":"exchange-060"}]},{"id":"topic-04","title":"請願第２７号および第２８号、小規模非住宅用地の固定資産税・都市計画税の減免措置の継続につき意見書の提出を求める請願","agenda":"請願第２７号および第２８号、小規模非住宅用地の固定資産税・都市計画税の減免措置の継続につき意見書の提出を求める請願","exchanges":[{"speaker":"渡辺委員","kind":"意見","question":"自民党として結論を出して、採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"}]},{"id":"topic-05","title":"請願第３１号および請願第３２号、償却資産に対する固定資産税における意見書の提出を求める請願","agenda":"請願第３１号および請願第３２号、償却資産に対する固定資産税における意見書の提出を求める請願","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"個人事業者の場合は、３月１５日の確定申告に合わせてやりますので、ぜひこの辺も理解してほしいと求めました。紹介議員として、ぜひ皆さんにご理解いただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"渡辺委員","kind":"意見","question":"自民党といたしまして、結論を出して採択をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"}]},{"id":"topic-06","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料の裏面のほうで、６番の職員の勤務体制というところで、日曜日があけばそれは便利になるという面があると思います。１月から３月の間の交替制勤務というのとは、またがらっと変わるということなんですか、もう少し具体的に説明していただければ。","respondent":"上川内戸籍住民課長","answer":"地域センターの職員のほうから部内の連携ということで、火曜日の体制より、火曜日は２時間延長窓口をやっております。それから、４月以降につきましては事業も増えますので、所要人員の中で、職員の定数を措置していくです。","id":"exchange-064"},{"speaker":"安藤委員","kind":"意見","question":"４月以降のことが、やはり必要な人員体制というのはどうしても必要になってくると思うんですけれども、そこら辺の人員体制というのをもう少し説明を求めました。","respondent":"早津区民生活事業部次長","answer":"したがいまして、４月以降におきましては、人数がどうということはまだ確定しておりませんが、必要な体制はとっていくということになります。１月の途中に人数を変更するというような形ではなくて、１月から業務を開始するについては、こういうことになります。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"やはりちょっと性急に１月からフルにやるには、ちょっと準備というか、人員体制の手当がやはり弱いんじゃないかと私はすごく感じております。その辺に関してはどうか尋ねました。","respondent":"早津区民生活事業部次長","answer":"人員については、先ほども申し上げましたとおり、まだ正式に何人という形でははっきりさせてはございませんが、早急に詰めまして必要な体制をつくっていくというふうに考えてあります。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"一月に１回とか２回とかというふうには、職員の方の声も出ているようですので、そういうふうには考えられはしないんか尋ねました。","respondent":"早津区民生活事業部次長","answer":"例えば１４日以内に出生の届出をするとかというようなことになりますと、翌週というわけにはいかなくて、毎週開庁をするということにしたものです。試行期間の中で需要等を見定める中で本格実施の際、あるいは本格実施後にどういう体制をしたらいいのかを検証しようと…","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問","question":"日曜出勤ということなんですが、一応休日手当みたいなものは出るんか尋ねました。","respondent":"上川内戸籍住民課長","answer":"それは振替対応をするということから考えていない。平日の振替です。","id":"exchange-068"},{"speaker":"安藤委員","kind":"意見","question":"休みということと、またちょっと休め方というのがちょっと変わってくると思うので、何らかのやはり負担感を絶対強いると思うんですよね。そこらに関しては、やはり何らかの手当というか、現金という意味じゃなくて…","respondent":"早津区民生活事業部次長","answer":"官公庁のみが日曜日に出勤したからといって手当を出すのはおかしかろうということで廃止した経過がありますので、今回の措置によりましても、振替休暇をとることでそれぞれの職員の休日に充てていただくということから特別な手当というようなことは考えていないです。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"いつ、従来あったものが廃止されてしまったんか尋ねました。","respondent":"早津区民生活事業部次長","answer":"ちょっと記憶がないんですが、一、二年の話じゃなく、１０年ぐらい前ではなかったかと思いますが、ちょっと断定的なことは申し上げられません。","id":"exchange-070"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それこそ区民の方の要望にこたえた話で、今ちょっと考えが逆かなというような質問があったんですけど、私は賛成です。最終だけはやらないということだけは結構強調しておいて、後でいい結果が悪いほうにならないように、その辺だけよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"これが即、日曜日開庁を求めているかどうかというところの検証はしっかりしていただかないといけないと思っています。そこの結論に達しているのかどうか、その辺も含めてなんですけれども、お伺いしたいと思います。","respondent":"早津区民生活事業部次長","answer":"そうした状況を踏まえながら、区としては休日の開庁について検討をしておりまして、検討をそのように進めてきたです。そういった効率を考えますと、どこにあります等の説明が非常に簡単ですから、こういう判断で決定したものです。","id":"exchange-072"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"そういった意味で、３階フロアですべて済むという体制をとるのでしょうか。私はぜひそこまでやっていただけたら、すごく区民サービスの向上になると思うんですが、いかがか尋ねました。","respondent":"上川内戸籍住民課長、早津区民生活事業部次長","answer":"３階フロアの戸籍住民課を中心にやると先ほど言いましたが、そこに国民健康保険も来るということで、すべての業務をやるということではございません。今回の業務としては戸籍住民課の窓口を中心にして… この日曜日の開庁に伴う戸籍住民課以外の対応というのは、そういった形で行う。それが３階フロアだです。","id":"exchange-073"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"１月から本格なんですよということなのか、ちょっとその辺を確認したいのと、いかがなものかと。職員のところからもいっぱい意見が出ていると思うので、ぜひ十分な論議をしてやってほしいと求めましたが、その辺はいかがか尋ねました。","respondent":"早津区民生活事業部次長","answer":"この辺につきましては、ちゃんと職員の理解を得ながら、よりよい形で実施してまいるつもりです。窓口のあり方につきましては、ご提案を含めまして、引き続きよりよい窓口のあり方を検討してまいります。","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問","question":"４月以降にそういった業務内容が業務内容ですから、そうでなくて、職員体制というのをしっかりすべきだと考えています。４月以降には、こうした派遣やアルバイトの方というのをどんどん活用していく考えというのはおありなのかということをお伺いしたいんですけど。","respondent":"早津区民生活事業部次長","answer":"これは執行機関である私どもが責任を持って必要な体制を整備していくですので、その辺、ご理解いただきたいと思います。さまざまなよりよい執行体制というのはどういう形であろうかという全体的な検討の中で決めてまいりたいというふうに考えてあります。","id":"exchange-075"},{"speaker":"安藤委員","kind":"意見","question":"その執行体制がどういう体制をとるかということで、やはり急激な実施というのはとりあえず一たん保留にしてもいいんじゃないかなというふうに私は思いますが、意見としてですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/598842?Template=document&Id=2496#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":67139,"voices":264}},{"id":"h19-20070925-7","meetingId":"h19-cm09","date":"2007年9月25日","dateIso":"2007-09-25","committee":"厚生委員会","time":"午前１０時０３分～午後５時０３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を116件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"同じく６で、該当するものがないと聞いているんですけれども、そのあたりはどういうことか。それから旅館業というのはどの程度あって、継いでいくというのがどのくらいの数に想定されるのかなというのを説明を求めました。","respondent":"山岡品川区保健所衛生課長","answer":"ほとんど承継、これは法人格を持っている場合は、代表者が変更の場合は変更届だけで済みますのでこれに該当しません。個人の場合が相続という関係で、関係してくるということで、ほとんどない状況です。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしますと、今までは承継の場合は３万５,０００円の手数料で、今度は７,４００円の承継の手続で済みますよという制度になるということですよね。温泉法の改正の中身というのは、その承継のほかに大まかにどんなものがあるのかということも教えてほしいと求めました。","respondent":"太田健康課長","answer":"１点目の改正になった背景ですけれども、２点目のほうと絡むんですけれども、温泉成分の定期的な分析および公表の義務づけ等が今回新たになされたと。１０年ごとに、温泉法の部分の承継というのが規定がなかったということを踏まえて、今回改正されたものと聞いております。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"渋谷で、温泉の爆発の事故もありましたけれども、今、すごく深く掘って、温泉を売りにしていくというのがいろいろ出てきているということを聞きますけど、品川区ではそういう動きというのはどうなんか尋ねました。","respondent":"山岡品川区保健所衛生課長","answer":"危険がゼロかというとわかりませんので、その辺は注意していきたいと思っていますけれども、現状の４施設についてはそういうことです。あるいは万が一ガスが出て、すべて区内４施設については屋外に設置されているということで、特にガスがたまるような状況にはないということで…","id":"exchange-003"},{"speaker":"堺委員","kind":"質問","question":"６月ですか、９月１１日でしょうか、そんな報道がされていますね。ちょっとその辺わかりましたら、教えていただけますか。","respondent":"太田健康課長","answer":"温泉法の改正がなされたということの、それに伴って、今回条例改正を提案するということをご説明申し上げたものです。爆発等を含めた安全管理について国のほうで検討をして、これから骨子案をつくって、場合によっては法律改正になってくるです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０カ月間の工事期間ということになっているんですが、これがまた９カ月ということで、１カ月短くなったということなんでしょうか。そのところをちょっと説明を求めました。","respondent":"蓼沼高齢福祉課長、冨岡高齢事業課長","answer":"これは１１月に工事は竣工して、ただ検査が１カ月かかるということで、それを含めまして１２月ということで明細のほうは表示をさせていただいたです。 区立で予定しておりましたけれども、法人との協議の中で、私ども団塊の世代の利用に何か考えていただきたいというのを投げかけておりました。内容については、先ほど申し上げましたように…","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"民設民営ということになぜしたのかということと、議会からのチェックというのがどういう形でできるのかということをお聞かせほしいと求めました。それと運営に当たっての負担金というか、そういうのはどういう形でされるのかについてもお聞かせほしいと求めました。","respondent":"冨岡高齢事業課長","answer":"運営の負担金につきましては、整備助成と同じで、助成金ということで対応したいと考えております。議会のチェック等ですが、利用者の方にお使いいただくことに変わりありませんし、それから議会のチェックは十分にできるかなと考えています。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今までもお聞きしてきたと思うんですけれども、指定管理者と同じような形で区のほうに出されて、チェックがされるという仕組みになるんでしょうか。そのところも聞かせてください。","respondent":"冨岡高齢事業課長","answer":"これにつきましては、当然基本協定を結びまして、それからさらに助成金要綱ということで、報告をしてチェックができるようにする予定です。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私が聞きたいのは協定だけじゃなくて、毎年毎年の日常的に、指定管理者であればモニタリングシステムという形でなりましたよね。それから計画書、区としてもチェックできる、そしてまた議会としてもチェックできるという形がとれるのかということでお聞きしたのです。","respondent":"木下福祉高齢事業部長","answer":"ケアホームなども区の高齢者施策との一体性ということもありますから、いろいろな形で我々としては運営事業者と連携をしていきたいと考えています。指定管理の場合と異なってまいりますけれども、予算審議などの場面を含めまして、その中でご意見を頂戴できればと思っています。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"一体どういうふうな運営状況になっているのかということをチェックをしたいと思ったときに、日常的にそういうふうなものというのはないんでしょうか。そこら辺のところもお願いします。","respondent":"木下福祉高齢事業部長","answer":"当然、ここは社会福祉法人こうほうえんが運営することになっておりますので、法人としての決算とか、事業報告というのは用意をされますし、私どもとしても、そのことについては把握していきたいと考えていますので、その中での取り扱いというのは可能だろうと考えています。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこら辺のところはしっかりと見ていっていただきたいし、議会でもチェックできるようにということでお願いしたいと思います。土地・建物を無償貸与ということで、財産そのものは区の財産でなくなるということではなくて、無償貸与ということでの考え方でいいんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"この土地・建物につきましては、端的には無償で貸与するということで考えております。ですから、区の財産でなくなるということではございません。","id":"exchange-010"},{"speaker":"須藤委員","kind":"質問・要望","question":"それから、質問は２番目に相対的に圧縮された数字が上がってきているんですけれども、いわゆる減になってきたよと。そういうあたりはこういう状況でという、いろいろな信頼度みたいなことは大丈夫なのかなという思いがあるんですが、そのあたりを説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"それから、都・国との信頼関係ですけれども、これにつきましては、地域住宅交付金の交付手続を通じて、十分都を通じて国とも協議をしてまいりました。合意しながら進めてきた結果として、区としての意を用いてまいりましたし、今後とも努めてまいりたいと考えています。","id":"exchange-011"},{"speaker":"須藤委員","kind":"質問","question":"予算立てをしていただくと、こういう大変な思いをしなくなると思うので、よろしくどうぞお願いします。そういうところと連携をとったらどうですかというのをケアホームの方にはちょっとお話をさせていただいたので、何をしている、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"堺委員","kind":"確認","question":"何点か確認をしたいんですけれども、最初に予算書の３７ページ、先ほどご説明いただきました児童デイサービスに関連してお尋ねをします。これについての扱いというんですか、個人情報保護との兼ね合いの中で、どう対応されていくのかなんですね。","respondent":"高橋障害者福祉課長","answer":"モニターを設置するのは、ほかのお子さんを対象にどうだとかということではありませんので、個人情報の絡みでは問題ないかと思います。","id":"exchange-013"},{"speaker":"堺委員","kind":"質問","question":"機材がいろいろ置いてあった部屋のその隣でということですかね。そういう理解でいいか尋ねました。","respondent":"高橋障害者福祉課長","answer":"委員が言われた、別室というのがその隣の部屋ということで間違いございません。モニターを設置することによってご自分のお子さんの動きを、その辺を観察しながら、お話しするという状況です。","id":"exchange-014"},{"speaker":"堺委員","kind":"確認","question":"これについてはお互いに何回も注意を呼びかけ合うというんですか、確認し合うという、その辺も確認していきたいと思います。貸付ということですから、どういう形になっているのか、ちょっとその辺を確認しておきたいんですが。","respondent":"蓼沼高齢福祉課長","answer":"具体的には、これは財産所管をしております、管財部門のほうと協定を別途結びますけれども、基本的な考え方としては、期間としては２０年間の貸付で、返済については無利子で返還をしていただくということで、返済方法等については、今後具体的に詰めていくです。","id":"exchange-015"},{"speaker":"堺委員","kind":"質問・要望","question":"２０年間無利子ということで、通常、こういうケースの場合は、それが標準的な対応の仕方になっているんですか。過去にも幾つかこういう例があったのかどうかも含めて、参考までに教えていただきたい。","respondent":"蓼沼高齢福祉課長","answer":"それから建物についても整備費を助成してきたというような形ですので、それを踏まえて、今回も同じような手法を採用したです。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問","question":"福栄会とか、品川総合福祉センターとか、これは公設民営というんですかね。なおかつ貸付金が２０年間で無利子でやってもらうということですから、適切な言葉でないかもしれないけれども、いいお仕事だなと。","respondent":"蓼沼高齢福祉課長","answer":"ただ、これまでの区内の法人と同じような財政支援を区としても、この原小学校のこうほうえんに対しても行っていこうです。それは言いかえれば、区民の方に対して適切な質の高いサービスを安定的に供給するという目的がまず大前提にあるです。","id":"exchange-017"},{"speaker":"堺委員","kind":"確認","question":"次に確認で申し上げようと思っていたんですが、こういう形をとることによって、利用される区民の皆さんに質の高いサービスが提供できるんだと。と思いますので、この辺についても、これからもお願いしたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"認可保育園のほうでお聞きしたいんですけど、補正後で６,４５０万円ですか、これはどういう考え方でこういうふうになっているのかということを説明を求めました。","respondent":"小林保育課長","answer":"きちっとした精査をしてまいりたいと考えていますが、ご説明させていただきましたように、その分を公費で計上した経過があります。協議をした結果、こちら、計上させていただきました６,４００万円余の負担を法人にお願いしたところです。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ちょっと具体的に６,４５０万円というものがどういう形で出てきたのかというのは、それでもう１つお聞きしたいのは、この保育園と。そういうものの保育の中身を区が把握していくというのは、どのようにされていくのかということについて、ちょっと説明を求めました。","respondent":"小林保育課長","answer":"全体の保育需要から考えますと、現在８園ありますが、品川区の子どもたちを預かっているという現状にあります。公立等含めて、十分な連携をもって状況は把握できておりますので、公私ともに一体となった運営の管理を今後も継続していく予定でおります。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区のほうが公募をして、民設民営という形になった、いわば区立保育園と同じような形のものであるんだと思うんですよね。そういう点から言えば、議会としてもチェックできるようなことというのが必要だと思うんですけれども、そこのところはいかがか尋ねました。","respondent":"小林保育課長","answer":"逆にそうでなければ、区民の方々から言えば、ご納得がいただけないものであると考えております。なおかつ今後、それを基礎としてよりよい形を考えていこうということですから、議会の関与もしていっていただくという形になるかと思います。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"体制がどうなっているかとか、ここの保育園も区のほうに情報を求めれば、体制からわかるということでいいんか尋ねました。","respondent":"小林保育課長","answer":"ご報告をいただき、それを保育課の中で精査する中で、次年度の運営の協議等を行っております。今回につきましても、同様の形で対応してまいります。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それであれば、指定管理者と基本的には変わりないような、中身のチェックができるということでとらえてよろしいか尋ねました。","respondent":"小林保育課長","answer":"財務ないしは実績の把握は社会福祉法人会計によっておりますので、それによって知ることができる内容については同様と考えております。状況に応じた対応が、独自の経営権の中でできるのが、あえて言えば私立保育園の特色かと認識しております。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"指定管理者ということでなくやるわけですから、情報も出してほしいと求めましたし、しっかりと把握もしてほしいと求めました。それからもう１つお聞きしたいのは、どういうふうになってくるのかということを１点お聞きしたいのと、そのところもちょっと説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"考え方としては区の助成と、基本的には区の施設整備の考え方としては国・都の補助金、そういう考え方で計画を進めてきている状況です。この貸付の返済ですけれども、これについては基本的には利用者の利用料の中から、その一部を返済に充てるということになると聞いております。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区がどれぐらい持って、どれぐらいを事業所に持ってもらうとかというのは、そのときそのときで考え方というのはないんでしょうか。その時々によって変わっていくのか、そういうことであれば、今回はなぜこういう額になってきたのかということを説明を求めました。","respondent":"木下福祉高齢事業部長","answer":"例えば２０年間の間で、こうすることが法人の支援につながると、しっかりしたものになるということになります。助成金というのは大体この大きさだったら、法人側もしっかり詰め、そこですり合わせをしながら個別に決めていくということが考え方であります。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"社会福祉法人の利益を上げていくというのではなくて、述べているわけですから、ぜひ区民負担軽減というところでやっていってほしいと求めました。そういう形で出ていますけれども、このケアホームというのは運営するに当たってはそういうのは一切出ていかないということなんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"民間の特別養護老人ホームにあるような経営支援費のことかと思いますけれども、この原小学校のケアホームについてはそういうものはございません。先ほど申し上げましたように、基本的には介護報酬でということが原則です。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう点では特別養護老人ホームでさまざまな問題が起こっていますし、区がかかわってやっていくわけですから、チェックの仕組みをどうするか。社会福祉法人のものが毎年出ると思うんですけれども、それだけでは私はとても足りないと思いますので、その点について説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"これは先ほどもシルバーセンターでお答えいたしましたように、あるいは実績報告、決算については必要な書類は提出をしていただくです。先ほどの事業計画あるいは予算・決算等につきましては…","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ議会のほうにもご報告ほしいと求めましたし、くれぐれも問題が起こらないような形での品川区の実態の把握と、それから情報の提供ということでよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"宮崎副委員長","kind":"確認","question":"ちょっと何点か確認をしておきたいんですけれども、１つは、そこのところを確認しておきたいと思うんですけど。基本的には貸し出す施設なので、区の側での費用負担ということになるんだろうと思うんですけど、そこのところを確認しておきたいと思います。","respondent":"蓼沼高齢福祉課長、冨岡高齢事業課長","answer":"事項別明細のほうでは、地域住宅交付金の本体部分については、高優賃助成ということで計上しております。そのほかの整備費助成については、ケアホームの助成ということで、別に項目を立てておりますが… もちろんグループ活動もしていただいて、そのほかに部屋等、時間等でさまざまな工夫は運営者がしていただければと考えているところです。","id":"exchange-029"},{"speaker":"宮崎副委員長","kind":"質問","question":"ですから、ですから、そこのところはどういうふうにするのか。そこら辺の考え方というのはどういうことなのか、あわせて伺いたいと思います。","respondent":"蓼沼高齢福祉課長、冨岡高齢事業課長","answer":"こうほうえんの当初のこの負担に対する考え方につきましては、運営事業者、参加事業者が提案するということで公募いたしました。基本的なその３つの要素で提案がありまして、双方で協議をして… 事業内容を決めていくというのがありますけれども、設置につきましては運営規定というようなものもつくっていただいて、区の考えがきちんと反映されるように運営していきたいと考えています。","id":"exchange-030"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"募集のときの募集要項というんですか、そういうところとの関係ではどうなってくるのかなというのが、そこのところをちょっと伺っているんです。これはどうも、後からくっつけたと思えてしようがないんですけれども、そこら辺のところをちょっと説明いただきたい。","respondent":"蓼沼高齢福祉課長","answer":"ただし、地域住宅交付金や都の補助金の歳入を建設費に充当するほか、区から一定の助成貸付を行う予定ですということが当初の想定です。ですから、それをこういうような明確な形で予算に計上することはできませんでしたので、区の一般財源で措置をしていたというものです。","id":"exchange-031"},{"speaker":"宮崎副委員長","kind":"質問","question":"ですから、これは後から、これも負担が出ます、あれも負担が出ますというやり方は、やっぱりしないほうがいいと思うんです。ちょっとそんな感想を持ちましたということを言っておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"介護給付費と地域支援事業の負担金、交付金を返還するということでの、その主な中身について、教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"それから都の負担金として返還するものが、２,２０９万５,０００円、これが介護給付費です。それから地域支援事業交付金ですけれども、支払基金交付金への返還が１,１２７万２,０００円、合計３億４,９４３万３,０００円です。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは予定していたものよりも、使わなかったということで返還するということではないんでしょうか。そこの中身があるのかなというふうに思ったんですけれども、そういうところでの中身について、お聞かせいただきたいということです。","respondent":"蓼沼高齢福祉課長","answer":"これはいわゆるもらい過ぎといいますか、超過交付であったもので、予算では給付費の見込みをするわけです。一定程度の見込みで、平成１８年度、もらい過ぎたものを返すというような性格です。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"当初予算を組んだときよりも、実際に給付してみたら、その給付が予算よりも少なかったということで、返還するということになるわけですよね。それなので、その当初見込みよりも少なかった主なものはどんなものですかということで、教えていただきたいということです。","respondent":"蓼沼高齢福祉課長","answer":"それはそれとして、要支援１、２の方への予防給付が当初予定していたよりも、それほど給付が伸びなかったというのが主な要因かと思います。要介護１が想定より多かったものですから、要介護１のほうでは、当初の見込みよりも下回ったです。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それだけ下がったというところに対してしっかりと見ていただいて、実際の在宅の利用者の要支援の予防介護の部分については、今後ぜひ充実をさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"宮崎副委員長","kind":"質問","question":"ちょっと今の質問に関連してなんですけど、今の３つのサービスのところでは、わかりますか。例えば介護ベッドだと、何かそういうことがわかったら、補正の減額のところを裏づける数字がわかったら教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"大体当初、介護予防の方ですと、２億円の見込みが１,１００万円くらいですね。それからヘルパーの時間数等については、ちょっと数字を持ち合わせておりません。","id":"exchange-037"},{"speaker":"宮崎副委員長","kind":"質問","question":"ぜひこれだけの補正が出るわけですから、これは要するに実際の介護サービスが減っているということですから、しようがないと思うんですけれども。ちょっと、これ以上聞いてもしようがないので、わからないので、終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"去年の４月ぐらいからはずっとそういうふうなことで対応がされてきて、９月から全面的にという形になったと思うんですが、それが使えなくなってしまってからの人数と予算というのはどれぐらいになっているかというのを教えていただけますか。","respondent":"蓼沼高齢福祉課長","answer":"介護ベッドと車いすの制度改正以前と後の数字というのは、今手元にはございません。やはり同じ１月審査分ですけれども、１,９３３件ということで、件数としては１,１１８件の減という状況です。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ヘルパーの問題にしても、同様にぜひお願いしたいと思うんですが、いかがでしょうか。今の部分で、件数はおおよそわかりましたけれども、予算の部分でもちょっと教えていただけたらと思います。","respondent":"蓼沼高齢福祉課長","answer":"先ほどの福祉用具につきましては、金額的には１,４４０万円余が減額しているというものです。平成１８年度が３,６２６件、３８５件のマイナスで、金額としては２,８３０万円余というものになります。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうのだけでは、はかれない部分があると思うんですよ。時間数がほとんどの方が減らされたという問題がありますので、時間数もわかったら説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"時間数では、ちょっと出していないと思います。ですから、時間に換算するとという見方はあるかと思いますけれども、介護報酬を算定する上で時間数というのは多分出てこないと思います。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"要支援１、２が定額制になったので、なかなか時間数ということで言えば難しい。現実問題は本当に２時間が１時間半に、また１時間に減らされたということで、しっかりとデータとしてつかんでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"須藤委員","kind":"質問","question":"それから、なぜずっとこういう償還金という、今までもいろいろな意味で返還していた形で整理をしていますよね。そのあたりの国とか地方自治体とか、こういうところの考え方はどういうふうになっているのか、説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"介護保険もそうですけれども、例えば老人医療費なども基本的には予算を立てて、それはやはり、どうしても見込みで立てざるを得ないと思います。基本的には見積もりを立てて、それで年度末でプラスマイナスが生じたものについては…","id":"exchange-043"},{"speaker":"須藤委員","kind":"意見","question":"中途でやり出したのは平成１６年のときからで、ずっと返しますよという形で清算したと思うんだけれども。そうすると、当然なってきちゃうと思うんだけれども、そのあたりはどうでしょうとの意見を述べました。","respondent":"蓼沼高齢福祉課長","answer":"９月補正で対応せざるを得なかったというのが、平成１７年度、それから今年度の補正の処理です。基本的には予定を立てて、実績が出て、翌年度もらい過ぎたものは返して、足りないものは交付申請をするというものです。","id":"exchange-044"},{"speaker":"堺委員","kind":"質問","question":"当初見込んだ額ではなくて、それは超過交付金を返還したんですからね。きちっと説明をしていただければと思って、今回、この件についてもう１回改めて説明をしてください。","respondent":"蓼沼高齢福祉課長","answer":"車いすについては、必要な方については、一定の適切な判断のもとに車いすの福祉用具の貸与というものは実施されてきたわけです。なるべく自立化を支援する観点からそのサービスの内容を見直しをしたものでございまして、それは変更なく実施されているというものです。","id":"exchange-045"},{"speaker":"堺委員","kind":"質問・要望","question":"繰越金になるであろう金額が幾らなんですか、もっと安くしたらいいんじゃないかとか、説明はきちっとということを申し上げているわけですね。この辺について、もう１回見解がありましたら、説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"要支援の介護予防給付にいたしましても、特に要支援１、その方の自立を支援していこうという観点で考え方を整理して。その方についても適切にケアプランをして、必要なサービスは引き続き提供しているというものです。","id":"exchange-046"},{"speaker":"宮崎副委員長","kind":"質問","question":"なかなか明確な話がないんで、ちょっと改めて伺いたいんですけれども、先ほどの介護ベッドなんかが給付対象から外れたんだということで説明があった。今まで給付されていた方で、見直しによって給付されなくなった人というのはいるんですか、いないんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"それは先ほど申し上げましたけれども、ベッドと車いすの内訳はございません。ただ両方合わせた数字は先ほど鈴木委員に答弁したとおりです。","id":"exchange-047"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"どういう状態だったかというと、布団から立ち上がれないんですよ。私は今日、残念ながら具体的な数字が、今までの受けていた人で給付されなくなった数をしっかり出していただきたいと、重ねて言いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この国庫支出金の返還金というのは、総給付費の２５％いかないものが国の負担割合ですよね。ということは、総給付費にすると、どれぐらい減額になるのかなというのを考えたんですけど、これの約４倍と考えていいか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"国が２０％、５％が調整交付金、都と区が１２.５％ずつと。支出が見込みよりも下回ったので、その割合に応じて返還するというものです。","id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"２３％ぐらいになるのかと思うんですけど、国庫支出金の返還金の約４倍の１４億円ぐらいということで考えていいんでしょうかということで、質問をしました。","respondent":"木下福祉高齢事業部長","answer":"要は平成１８年度中に国とか支払基金とか、東京都に見込み、大体過払いになるようにもらうわけですね。その部分について、１月末までに納めなさいというふうに方針が変わったものですから、年度の途中でこれをお願いしているということであります。","id":"exchange-050"}]},{"id":"topic-02","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"この被爆者に対する援護に関する法律で、いわゆる原爆症を認定してくださいということなんだけれども、原爆症認定と、被爆者健康手帳を持っている方々との差というのはどういうことがあるんか尋ねました。","respondent":"高橋障害者福祉課長","answer":"被爆者健康手帳というのは、地域が限定されたところで、そこにいるということが証明されれば、手帳が交付されるというような状況です。認定制度というのは、医療の給付や特別手当を受けるために、厚生労働大臣の認定を受ける必要があるので、認定を申請するというようなことです。","id":"exchange-051"},{"speaker":"須藤委員","kind":"質問","question":"被爆者健康手帳を持っていると、やはり医療の給付は受けられるんじゃないんですか。被爆者健康手帳を持っていると、それなりの給付があるんじゃないのかな、医療機関で。","respondent":"高橋障害者福祉課長","answer":"手帳を持っていますと、健康診断、健康指導を受けられるのであって、医療の給付になりますと、認定が必要になってくるというような状況です。それから一般疾病による医療の給付の２つの制度が、全国で、無料で医療の給付が受けられるという状況です。","id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"手帳を持っているということは、健康診断と指導、それしか受けられないという状況になっているんでしょうか。もう１つ、品川区内では手帳を受けられている方がどれくらいいらっしゃるのかと、認定されている方の数も合わせて教えてほしいと求めました。","respondent":"高橋障害者福祉課長","answer":"月額１３万５,４００円、特別手当については、月額５万円というような状況があります。それと医療の問題につきましても、手帳があっただけではなく、認定を受けて初めて医療のところで給付がされるというような状況です。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"手帳を持っている方の０.８６％の方しか、あまりにも乖離があるという理由というのは、どういうところにあるということで考えられるかもお聞かせほしいと求めました。","respondent":"高橋障害者福祉課長","answer":"申しわけございませんが、認定するのは厚生労働省のほうなので、その認定基準が乖離しているかどうか、私のほうではつかんでおりません。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多分、そういうところもぜひ担当課というところでは思いを寄せて、つかんでいただけたらと思います。それからもう１つ、地域限定で手帳の交付を受けられるということなんですが、そのことについてもお聞かせほしいと求めました。","respondent":"高橋障害者福祉課長","answer":"原子爆弾が投下された際、指定の区域ということで、大体２キロとかいうことです。それと、そのほかに原子爆弾が投下されてから２週間以内に救援、医療活動等に入った者、それと、その胎児の者ということになっております。","id":"exchange-055"},{"speaker":"堺委員","kind":"質問","question":"先ほど担当課長のご説明の中でも、３月９日ですか、都議会が、衆議院・参議院の議長、それから関係大臣等にも意見書を出された。８月６日付のある新聞に、現実に５日の午後ですか、見直すことを検討させたいというようなお話をされていたということが報道されておりました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"本間委員","kind":"質問・要望","question":"理解いたしたいと思います。趣旨が理解されれば、意見書としてまとめて、国に対して要望していきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これほどの大変な犠牲になりながら、戦後６０年間、共産党としても２年前からこの問題では対策委員会をつくって取り組んでいるところです。ぜひ採択をして、意見書提出というところでやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１回目、２回目も１,０００名以上の方が署名されていまして、区としてどう考えられているのか。その点について、まずお聞きしたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"先ほど申し上げましたように、利用料につきましては再三申し上げているとおり、区の考えは明確になっております。それについて特に事前に説明会を開くということは考えておりません。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その利用料について、地域で理解が得られていると考えているのかということをお聞きしたいのと、これほどの強い地域の要望で、請願が出てきているということに対して、どう考えているかということをお聞きしたので、お願いします。","respondent":"蓼沼高齢福祉課長","answer":"さきの請願審査のときもご説明して、区としてはそういう特別養護老人ホーム並みの利用料ですとか、国民年金の方が入れるような利用料設定は考えていないです。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところはちょっと１回、しっかりとお聞きしたいと思うんですけれども、やっぱり地域に納得いく形で進めるというのが大事だと思うんですよね。地域にこれほど強い要望があって、それで説明会も開いてほしいという、改めてお聞きかせください。","respondent":"蓼沼高齢福祉課長","answer":"区の考えは、今検討しているところですけれども、１６万円から２０万円ぐらいのところ。そこが１つの目標ではないかということを勘案して、この種の請願について、意思決定をしていただいているものと考えております。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つ、そこの仕組みを聞かせていただきたいと思うんですが、１つは介護報酬の特定介護施設の１割負担というのがありますよね。そこら辺のところの利用料の決定の仕方、計算の仕方、その根拠についてお聞かせほしいと求めました。","respondent":"木下福祉高齢事業部長","answer":"区が関与していますから、当然区のほうの考え方も調整してまいります。７割は特別養護老人ホームになっているということでありますから、続けていきたいと考えていますので、基本的にはここの部分では対応はしにくい。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区がつくるのに、一部のお金のある人のための施設をどうしてつくるんだ、お金のない人を排除しないでほしいというのが地域の方の願いなんですよ。それぐらいのものですから、排除しないでほしい、いかがか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"そういう多様な選択肢が用意されているわけですから、そのすべてを原小学校の中で求めるという、これは無理なことであります。全体の中で、その辺はご理解をいただければと思います。","id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だけど、そういう施設はお金のない人を排除しないでほしい。こういう形でできないですかね。","respondent":"木下福祉高齢事業部長","answer":"厚生年金でも基本的に入っていくことができるもの、その辺を少し視点に置いて、進めているものであります。全体としては、特別養護老人ホームを含めた中で、今のお話につきましては、私どもとしては対応をさせていただきたいと思っているところであります。","id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区がつくる施設として、厚生年金の方は入れるけれども、国民年金の方は入れない。国民年金の方を排除する施設、そういう施設を区の姿勢としてつくっていくということでいいんか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"それを原小学校の中で実現するのかということでは、現実には制度の枠組みから言うと難しいと考えています。今、お話があった部分については、特別養護老人ホームも含めて対応をするです。","id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう方針を出していますけれども、そういう方針を出しているのって、品川区だけじゃないですか。どこの自治体でも、２３区、どこをとっても、その新型特別養護老人ホームをつくっているわけじゃないか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"今、７は特別養護老人ホームになっているという点で、今後の高齢者のご希望に沿ったものというふうに考えているところであります。やはり問題認識は、保険料にも連動する問題でありますので、かなりそういう意味では総合的な検討が必要だろうと思っているところです。","id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私も改めて特別養護老人ホームのお話を聞いて驚きましたけど、２.２対１というふうに実際はなっていないんじゃないですか、多分。だから自治体のやることですから、やっぱり本当にだれも、全員が入れる減免制度をつくるような、そういう施設に自治体としてやるべきなんじゃないか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"宮崎副委員長","kind":"確認","question":"１つ確認しておきたいんですけれども、この施設の対象外だというふうに考えているかどうかということを、はっきりまず聞いておきたいと思うんですが。","respondent":"蓼沼高齢福祉課長","answer":"答えはおのずと出てくるかと思いますけれども、収入源は年金だけに限られるかというと、そう簡単には言えないと思います。ですから、この年金受給者だけを入居者として想定しているのかというと、そういうことについては、特に区としては考えていないです。","id":"exchange-068"},{"speaker":"宮崎副委員長","kind":"質問","question":"私の質問が、先ほど部長は厚生年金で入れるようで、そういう施設の視点で考えたんだという説明だったんですよ。今度の原小学校の跡につくるケアホームは、国民年金しか収入がない人は対象外ですという想定で考えてもいいんですねということを聞いているんですが。","respondent":"木下福祉高齢事業部長","answer":"国民年金６万円で生活できるかという、あるいは同居、いろいろな形で支援を得ているというのが多くの方の状況だと思います。家族全体の中でケアホーム、原小学校の施設を選択するということは十分あるわけでありますので、その辺は幅広くとらえていただけたらと思います。","id":"exchange-069"},{"speaker":"宮崎副委員長","kind":"質問","question":"このニーズをどう考えるのかということと、もう１つは今、区内の二葉町のあたりでも、民間の業者が有料老人ホームをつくっていますよね。そこのところはどういうふうに説明するんか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"先ほどもちょっとご説明させていただいたんですけれども、そういう中で、事業者が負担をするというのが原則なんです。区全体の施策の中で、そこは対応をするということでありますので、誤解されるようなものの言い方はされないようにしていただきたいと思います。","id":"exchange-070"},{"speaker":"宮崎副委員長","kind":"質問","question":"そういう説明でしたけど、それじゃあ、そういう人たちには特別養護老人ホームにいつまでに入れますという約束ができるんですか。そういうところはどうやって改善するのか、ちょっと最後に伺いたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"部長から再三ご説明しましたように、特別養護老人ホームについては大体７で、そのほかが３というようなことです。要介護の方々の生活を支援するために施設整備、在宅支援、あわせて進めていくというふうに考えているところです。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"７分の１か、８分の１か、９分の１か、これぐらいしか入れない。特別養護老人ホームを完備しているというのは、何を基準に、何を根拠にそう言われているのかということを改めてお聞きしたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"具体的にそういう転換以降の調査はまだ進めているところですけれども、必要な支援等があれば、対応していくということになろうかと思います。それを踏まえて、区としても対応といいますか、検討が必要になる部分も出てくるかと思います。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"認定率は、もう本当に全都の中でも下から３番目かそのくらいじゃないでしょうか。１回申し込んだら、ずっと積み上げていくわけですから。","respondent":"蓼沼高齢福祉課長","answer":"要介護認定を受けている方で、１号被保険者は１万人弱、９,６００人ぐらいだったと思いますけれども、それは要支援１、２を入れての数字です。あるいは今整備を進めておりますグループホームも含めて、今後もやはり一定の地域バランスを考えながら…","id":"exchange-073"},{"speaker":"須藤委員","kind":"質問・要望","question":"請願につきまして、理事者にいろいろ質疑されたので、内容的によくわかってきましたので、逆に品川区の高齢者福祉施策の考え方もよくつかめてきて、ここだけの限定ではないというお話も聞かせていただきましたので、そろそろ結論を出してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"堺委員","kind":"質問・要望","question":"本日結論を出すということで、お取り扱いほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"堺委員","kind":"意見","question":"原小学校跡地あるいは都南病院の跡地に仮に施設を作っても３、いわゆる７対３で、そういう考え方につきまして我々も理解できるところであります。利用料金を含めて、現時点ではやはりこの請願についてはどうしても不採択にせざるを得ないということで、意見を申し上げますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だれもが入れる施設をつくってほしい、このことがどれほど地域からの強い要望かということをあらわしているんだと思います。あれほどの意見が出たわけですから、そして地域の方々が納得できる形で進めていただきたい、この請願に対しては採択をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"須藤委員","kind":"質問","question":"請願内容の１番目ですけれど、これだけを単独でというのは難しいという説明ですよね。それをちょっと説明を求めました。","respondent":"高橋障害者福祉課長","answer":"看護業務ですが、基本的には医師、歯科医師の指示のもとに行うことが、保健師助産師看護師法第３１条に載っております。医療行為の禁止につきましても第３７条に、保健師等につきましては医師の指示のもとではないと業務を行ってはならないというふうになっております。","id":"exchange-078"},{"speaker":"須藤委員","kind":"確認","question":"では２番目をもう一度確認だけれど、今現在、障害児の自立支援法に訪問看護師派遣というのはないということですから。それから３番目、いわゆる訪問看護事業をやっていただいておりますけれど、これも補助金として行政からは支援していないという確認でよろしいか尋ねました。","respondent":"高橋障害者福祉課長","answer":"委員が言われたとおり、２番目の問題につきましては障害者自立支援法上、制度としてございません。それと３番目の補助金の部分につきましても、訪問看護ステーションにおきましても、介護医療報酬の中で運営を行っているのが現状です。","id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の訪問看護の制度が介護保険と健康保険、医療のほうの制度があるということなんですが、もうちょっと詳しくお聞かせいただきたいんですが、曜日、祝日、時間の制限を設けないでください、ということでありますが、ここら辺は実際はどうなんか尋ねました。","respondent":"高橋障害者福祉課長","answer":"この曜日、時間ということでは、主治医が指示したということになりますので、医療行為的な処置が必要かどうかというところで判断したかと思います。ですので、その辺の現状につきましては医師が判断したということになりますので、私のほうでは現状としてはつかんでおりません。","id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"祝日、時間で対応されないということはあまりないのではないかと思うんですが、そこら辺のところがわかったら教えていただきたいのが１点です。もう１つは、そういうふうに受け持ちをして欲しいと訪問看護ステーションに依頼しても、そこら辺の実態をつかんでいたら説明を求めました。","respondent":"高橋障害者福祉課長","answer":"委員がおっしゃるとおり医師の指示がないと、医師が必要と認めないといけないものですので、その辺については常に医師との連携が必要かと思います。在宅での生活を続けていらっしゃる方かと思いますので、単独でこれだけが必要かということには…","id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"急にぐあいが悪くなったときも、受け持ちであれば断ることはあり得ないと思いますので、それはそれで対応されるんだと思うんです。ただ、訪問看護を受けたいと希望しても受けられないような状況があるのかどうかをつかんでいたら、教えていただきたいという質問です。","respondent":"高橋障害者福祉課長","answer":"そういう状況は現在つかんでおりません。その辺については受け入れる、受け入れられないじゃなくて、そこの医師が必要と認めれば訪問看護ステーションのほうで派遣は可能かと思います。","id":"exchange-082"},{"speaker":"本間委員","kind":"意見","question":"趣旨的には非常にわかる部分もありますが、少し勉強不足のところもあります。できましたら、継続という形にしていただけたらありがたいというのが意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"須藤委員","kind":"意見","question":"理事者から説明いただきましたように、請願内容がなかなか現状では、品川区が法的責任を持ってやるには法的な問題やいろいろなことをクリアしなきゃいけないと思うので、この請願内容ではなかなか前に進めがたいという感じですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"},{"speaker":"本間委員","kind":"質問・要望","question":"先ほども言いましたので繰り返しになりますが、意見を言うならば、扱いについては継続にしていただきたい、再度改めてということもあります。そうでなければ、ここで結論を出すということであればそれなりの意見表明をします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"堺委員","kind":"質問・要望","question":"近い将来、我々政治に携わる立場としては努力していかなきゃいけないのかなという気もしますし、また行政側でもそういう努力はしていただきたい。重ねて、いかなる人であろうとも「生きるために必要な最低限の権利」、これは保障されてしかるべきであろうと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"訪問看護の体制がないために、お願いしても受け入れ先がないということで困っているというお話もお伺いしましたし、そういう問題もお聞きしました。まだまだ障害を持った方に対しての体制という点では不十分なんじゃないかと思いますので、趣旨採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"}]},{"id":"topic-03","title":"の３、報告事項","agenda":"の３、報告事項","exchanges":[{"speaker":"須藤委員","kind":"質問・要望","question":"今説明いただいたんだけれど、広域連合のほうで９月１２日に厚生労働省に要望を出されたことは、ちょっと触れておいたほうがいいんじゃないかと。","respondent":"冨岡高齢事業課長","answer":"委員ご指摘のように９月１２日に、一都三県の広域連合によりまして国への緊急要望書の提出がございました。その内容ですけれども、保健事業への財政支援、制度周知、国庫負担金等の速やかな交付、調整交付金の別枠交付といったような内容です。","id":"exchange-088"},{"speaker":"宮崎副委員長","kind":"確認","question":"確認しておきたいんですけれど、そういうことでいいのかどうなのかということと、また１人当たりの保険料にはどのぐらい影響が出てくるのかというのをまず聞いておきたいんですが。","respondent":"冨岡高齢事業課長","answer":"大体こういう形の計算をするわけでありますが、７０％という場合はこういう形の計算をいたします。実際にはもうちょっと細かい計算の出し方がありますので、簡単に何％という形では、ちょっと数値を入れてみないとわからない部分があります。","id":"exchange-089"},{"speaker":"宮崎副委員長","kind":"質問","question":"ほとんどこの調整交付金３０％に近い数字になりそうなのかなと受けとめたんですけれど、それでいいのかどうなのかちょっと伺いたい。例えばここは約４０％になっていますけれど、果たしてそういうことは可能なのかどうか、どうなんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"可能かどうかということは、理論的にはあり得ると思いますけれど、具体的にはこれから検討がいろいろされていく部分だと考えています。","id":"exchange-090"},{"speaker":"宮崎副委員長","kind":"質問","question":"大体３０％のほうにかなり近いのかなと受けとめたんですけれど、それでいいのかどうなのかということも、あわせて伺いたいと思います。さきほどの財源構成のところは理論上と言われたんですけれど、その辺は実際には議論されているんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"理論上と申し上げましたが、訂正といいますか、当然法律の枠内ということはあるかと思います。それから３０％がどうなのかですけれども、まだこれからどうなるかちょっとはっきりしていないと、数値的な確認はまだというふうに聞いております。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"資料２－１のところで、均等割と所得割の比率を５０対５０ということなんですけれど、不安になるところだと思うんです。所得割とそれぞれ書かれていますけれど、そういう表をぜひ資料として出していただきたいと思うんですけれど、その点説明を求めました。","respondent":"冨岡高齢事業課長","answer":"これは住民税を算出する場合の合計所得から基礎控除を引いた分に所得割の率を掛けていく、という形の計算法をするということで考えているところです。それから資料の件ですが、これは資料の出し方が、基準が多分違っていると思いますので…","id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"現在の国保料と今度の高齢者医療で３０％のときと１００％のときでどうなのかというところを、試算としてぜひ出していただきたいと思うんです。５割、この７割減額という方もいらっしゃるんじゃないかと思うんですけれど、その点もあわせて説明を求めました。","respondent":"冨岡高齢事業課長","answer":"５割、２割の部分とどういうふうにかかわるかですが、資料２－２の４ページに被用者保険の被扶養者への激変緩和という部分があります。そこの下のほうに、（１）と（２）の制度が重なる場合は（１）を適用すると出ておりますので、こういうふうに対応されるかと思います。","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１２分の１が調整交付金ということで、それが所得水準の低い、高いで１２分の１全額もらえるかどうかが問題になっていると思うんですけれど。葬祭にしても健診にしても、全部これを保険料で賄うという仕組みもどう考えてもおかしくて、そこのところの考え方を説明を求めました。","respondent":"冨岡高齢事業課長","answer":"それから葬祭事業を行うのか行わないのかというのも１つありますけれど、行うとすると保険料で対応すると。それからもう１つ、今の保健事業ですが、これにつきましてはやはり今のままですと保険料で対応するです。","id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その国保の中で７５歳以上の医療費というのは給付の多くの部分を占めると思うんですけれど、区の負担は逆に減ることになってくるんでしょうか。それと、国保の中で７５歳以上の給付費を占める割合とかも、もしわかったら教えてほしいと求めました。","respondent":"冨岡高齢事業課長","answer":"区の負担が増えるかどうかというのは、ちょっとまだ今の段階では計算ができない状況です。支援金の現役世代の方が人数も減ってまいりますので、これ以上負担がかからないようにという形で対応しているものだと理解をしております。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何がどうなっているのか、そこら辺のところをもっとわかる形で明らかにしていってほしいと求めました。こういうことでは、７５歳を過ぎた方の健診項目に関しての考え方という点ではいかがか尋ねました。","respondent":"中村品川区保健所長","answer":"その後７５歳以上でこの項目で新たに異常が見つかれば、この検査でカバーができるんじゃないかということで国等も検討しているです。ここら辺は、各自治体においてどれだけプラスアルファの健診をするか、また別途考慮されているというふうにも伺っているところです。","id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"各自治体でということであれば、品川区が今までやっていたものもプラスしてやっていくということも考えられるんか尋ねました。","respondent":"太田健康課長","answer":"さきの本会議でも同一の質問がございましたけれども、現在、国民健康保険を所管する国保年金課を中心にして、庁内での検討会を今進めているところです。","id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"整形だけしかかかっていないとか、そういう病院にかかっていない方もいらっしゃるわけですから、そういう中身だなという感じがするんですね。心電図も眼底も診ていないわけですから、７５歳を過ぎているからもういいですよというのではなくて、ぜひ要望をしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-098"},{"speaker":"堺委員","kind":"質問","question":"今のことと関連するのかもしれませんが、資料１－１の説明の中で７５歳以上の健康診査等についての実施主体で、広域連合の努力義務とあるんですが、説明いただいたのかもしれませんが、この努力義務というのは何なんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"実際問題といたしまして広域連合では、そうは言っても実施をいたしますという形で、今、協議会でまとめたところです。詳細についてはこれからさまざまな機関と調整しながら検討していくということになっております。","id":"exchange-099"},{"speaker":"堺委員","kind":"質問","question":"要するに７５歳以上の後期高齢者の人を対象にして、新たに保険制度というか医療の行為といいますか、４０歳から７４歳までの人と変えますよと。だから決して高齢者の健康診断を軽視するということではないんですよというふうに理解をしていいんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"この努力義務というのはあくまでも法律上に書かれている言葉でございまして、広域連合としては実施をするです。しかも、実施については区市町村に委託化する方向で検討しているということで、そういう形ではまとまっておりますので。","id":"exchange-100"},{"speaker":"堺委員","kind":"確認","question":"したがって７５歳に到達したから、もう健康診断を受けなくていいよ、健康診断の項目が減っちゃったんだよということではないんですねと。その辺をちょっと確認しておきたいということです。","respondent":"冨岡高齢事業課長","answer":"７５歳になられましても、しなければいけないというより若干軽うありますが、努力しなさいです。そういうふうに国は考え、広域連合のほうも実施をするということで受けとめているところです。","id":"exchange-101"},{"speaker":"堺委員","kind":"提案","question":"最近いろいろな報道等でも医療費の増大というんですか、それは時代の大きな流れだろうなという気はするんですね。提案ですが、後期高齢者の関係につきましては新聞報道等によりますと、新たにこの負担増については凍結という流れが報道されていましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-102"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"私も今の堺委員の提案に対して賛成です。いろいろな議会から、もう既に意見書が上がっているということもお聞きしていますし、ご決定ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-103"},{"speaker":"須藤委員","kind":"質問・要望","question":"私どもも意見に賛同いたします。我々の中でも会派の中でいろいろな考え方が出されましたので、整理をして今日中に委員長のほうへお持ちさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-104"},{"speaker":"堺委員","kind":"質問","question":"明日の委員会でその案文を皆さんにお諮りして、それをまず委員会の意志として固めていただければいいんじゃないでしょうか。それで、ステップとして今度は議会運営委員会に提出をされて品川区議会として出したほうが、と思いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-105"},{"speaker":"須藤委員","kind":"意見","question":"今、堺委員より品川区議会として出したほうが、というお話もありましたので、厚生委員会として出すことも地方自治法の改正でできるようになったけれど、議長と委員長とでご相談してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"現在と比較してどれぐらいの保険料になるかというのがすごく見えると思いますので、明日その案文とあわせてぜひ資料として委員会に提出していただきたいと思うんですけれど、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-107"},{"speaker":"須藤委員","kind":"意見","question":"大枠の考え方が出されて３０％しか補助しません、１つ１つそこまで理事者に資料をもらって、我々が文章を考えることじゃないので。じゃあ、それだけの仕事を理事者にどうのというのは、明日までに意見書をまとめるという時期にちょっと無理な話だろうと思うんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-108"},{"speaker":"堺委員","kind":"意見","question":"ご自分で勉強することならばいいのかもしれませんが、委員会としての資料要求ではなくて、ご自分で勉強することかなと。事前にあったほうがそれは参考になったかもしれませんが、個人的には委員会資料として要求する必要性はないと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-109"},{"speaker":"本間委員","kind":"質問","question":"私たちの品川区議会では、議会の代表として須藤委員を送っています。これまで２回ぐらいしか会合ができないとか、そういう中でのことですから、その辺はちょっと時期が早いのではないかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-110"},{"speaker":"高橋委員","kind":"意見","question":"明日の意見書に関して必要かどうかということだと思うので、それを使って検討するのには必要ないと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は介護保険の平成１８年度の品川区の制度運営状況について、ぜひ区のほうからご報告をいただきたいということでお願いしたいと思っているんです。だからぜひそういう点では、大きく制度が変わったその年のまとめですから、厚生委員会に報告をしていただきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-112"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成１２年からですからこれが６年目ですね。そういうところで報告をいただきたいと思うんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-113"},{"speaker":"須藤委員","kind":"提案","question":"鈴木委員の提案が急だったのでちょっとあれなんだけれど、私自身は委員が報告せよと議会の中、委員会の中で要求してくればできることだと思います。唐突に何でどうだと言われたので、反対ということではないとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-114"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"そもそも介護保険は厚生委員会の所管なので、やはり年度の運営状況についてはしっかり報告をいただくということを求めておりますので、ぜひそういう機会をつくっていただきたいということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-115"},{"speaker":"須藤委員","kind":"質問・要望","question":"もう一度鈴木委員の質問に対して答えていきたいということなので、資料どうのこうのという形をつくっていっても大変な仕事になってくる。出しませんという表現はまたおかしいので、そのあたりは我々もきちんともう少し調べてからご返答させていただきたいという話をしているわけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-116"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/928192?Template=document&Id=3182#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":85146,"voices":279}},{"id":"h19-20070925-8","meetingId":"h19-cm09","date":"2007年9月25日","dateIso":"2007-09-25","committee":"建設委員会","time":"午前１０時０３分～午後６時０５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を100件整理しています。","topics":[{"id":"topic-01","title":"第７１号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第７１号議案、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"それから、大崎駅西口第３のほうが、耐震補強工事終了後にバイクを移設すると書かれていますけれども、何台分ぐらい考えているのか、教えてください。それがまた、移設後のバイクの台数の考え方をあわせて説明を求めました。","respondent":"松嶋交通安全担当課長","answer":"耐震補強工事終了後にバイク駐車場としてやる予定ですけれども、一応、バイクはおおむね１７０台ぐらい設置できるように考えているところです。これがなくなることを考えれば、今回、そのところに合わせて全部つくりたいと思っているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"見た感じ、確かに自転車も、バイクもいろいろありますから、あれですけれども、利用状況調査を行っているのかどうか、そこを伺いたいと思います。大学生、いわゆる学生の利用者というのはどれぐらいになるのか、教えてほしい。","respondent":"松嶋交通安全担当課長","answer":"したがいまして、これも調べればわかる部分ですけれども、今は手元にございませんので、お答えすることはできません。始発のおおむね３０分から１時間前にあけて利用するという利用状況ですので、シャッターを設けるです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"１１月１日から始まる話ですから、今の時点で、何時から何時が閉まりますというその時間を正確に教えてほしいと求めました。その辺はどういう感じになるのか、ちょっと教えていただけますか。","respondent":"松嶋交通安全担当課長、青木都市開発課長","answer":"時間の話ですけれども、終電、始発の時間をもくろんで、終電のおおむね３０分後に閉めて、始発の３０分前にあけるというように考えているところです。委託先がどのようになるかは、私のほうではちょっと認識はしておりませんので… ８月３日の、各権利者、あるいは事業予定者などがともに考え方をまとめました都市再生ビジョンというものの中でうたっている考え方でございまして。地元の方々の雇用なども確保できるものと考えておりますので、まちづくり…","id":"exchange-003"},{"speaker":"阿部委員","kind":"質問・要望","question":"それとも、また別の街区で新しいものができたら、また別に駐輪場なり、バイク置き場なりをつくっていくという考え方なのか、それを教えてください。それは普通の会社みたいに、収益はそこのものなのか、どちらなのかということを教えていただきたい。","respondent":"青木都市開発課長","answer":"開発が予定されておりまして、それに伴って見込まれる駐輪需要については、各地区の開発で設置するよう指導しております。具体的には、私どものほうから、今のところ特定したものはございません。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"中間法人のご答弁のところで、管理委託先としてこの中間法人に委託するわけですけれども、委託料というのは、年間契約になるかと思うんですが、どれぐらいを、今、見込んでいるんか尋ねました。","respondent":"松嶋交通安全担当課長","answer":"おおむねなんですけれども、今年度、１１月から始まりますが、３月までは、この地下駐輪場だけではなくて、大崎エリアということで約２,０００万円弱を考えております。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうしても、必ずＪＲ東日本もそこで利用するわけですから、私はあるべきだろうと思っているんです。ＪＲの利用も増えるわけですから、そこら辺のところの努力はどういうふうにされて、いかがか尋ねました。","respondent":"青木都市開発課長","answer":"都市計画的に、あるいは、現状の利用状況から、この９００台の駐輪場を設置しております。委員のご指摘を踏まえて、何らかの必要があるとすれば、ご指摘のとおり、ＪＲとの協議もやっていきたいと思います。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"大崎駅を使う部分が多い地域がこれからどんどん出てくるわけですから、大崎駅を使っている人の多いわけですから、そこら辺の点も踏まえて。まちづくり事業部長に大変期待をしておりますので、そこら辺でチェックできるようにやっていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-02","title":"第７２号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第７２号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"三つの再開発事業のことになりますので、まず一つ目の大崎駅西口Ｄ地区のことについて伺いたいと思います。はじめに確認させていただきたいのは、現状はどうなっているのか、まず確認させてください。","respondent":"岩田まちづくり事業部長","answer":"担当課長が、ただいま総務委員会のほうに出ておりますので、戻り次第、それらについてはお答え申し上げるとしまして、本条例の内容については、担当課長がいなくても建築課長でお答えできると思いますので、できれば、そういう議論にお願いしたいと思います。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"住宅とのバランスのとれた都市環境というふうに記されておりますけれども、Ｄ地区を見ますと、形としては１棟になるんですか。それぞれどういう形になるのか、その建物はどういう形になるのか、教えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"特に駅前の商業スペースというのは、商店街への影響というのはどういうふうに考えているのか、そのお考えを教えてほしいと求めました。完成次第５,０００万円とか、７,０００万円という金額になりかねないと思うんですけれども、お考えを説明を求めました。","respondent":"岩田まちづくり事業部長","answer":"本建設委員会でもご説明を申し上げて、都市計画審議会の場で採択をしていただいて、既に都市計画決定が終わったものです。都市計画を検討する、業務を入れるのかということをいろいろ検討する中で、地元の準備組合が持っている。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"それについて、区の考えがないのかということを、先ほど、お聞きしたわけです。どうしても伺いたいところでありますので、その１点について、お答えほしいと求めました。","respondent":"岩田まちづくり事業部長","answer":"大ざっぱなところは、箱ものとして上限と最低限度を定めたというご理解をお願いしたいと思います。今後変更は十分にあり得る話ですし、いろいろ事業計画を立てていくというのが、どこの再開発事業でも行っているものです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"続いて、北品川五丁目の再開発事業について伺いたいんですけれども、進め方はどうだったのか、一番気になることなんです。その後、地域の方々の説明会というのは、どの程度開催されているのか、合意形成のところを、説明を求めました。","respondent":"岩田まちづくり事業部長","answer":"近隣説明は、それから中に入る用途といったものが定まってまいりますので、細かい説明はされる。ある日突然、こういったプランをぽんと地域の方に説明されたわけではなくて、その中でいろいろな議論をずっと２０年間押し進めてこられたわけです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"Ｄ地区の事業予定と、補助金と、準備組合の加入率と、ディベロッパーと、建設会社。２月の建設委員会でも報告がありましたけれども、その後、変更がないのか、現状を確認したいと思いまして、ご説明ほしいと求めました。","respondent":"青木都市開発課長","answer":"予定しています事業費が、そのうち１６億円ぐらいは補助金を欲しいというか、補助金に該当すればということでお話をいただいております。所有権者、借地権者合わせて４２名で、今、具体的な数字はにございませんが、７３.８％の加入率で…","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"３５９名が集まって、るる３９階という高さは高すぎるとか、そういう話がなぜ挙がったと思いますか。改めて伺いたいのは、どうか、説明を求めました。","respondent":"岩田まちづくり事業部長","answer":"北品川五丁目の準備組合の行った説明会に多くの周辺住民の方がお見えになって、非常に地域の方は不安をお持ちになるのは当然の結果だと思います。準備組合のほうがきちっと説明をすることによって、こういうことを、私どもは行政指導をさせていただいているわけです。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"事業費としても、総事業費が、この前に伺ったら９５０億円、税金投入１３０億円弱という説明がありました。この計画に対して合意は得られていると思うのか、再度、お伺いしたいと思います。","respondent":"岩田まちづくり事業部長","answer":"その一つひとつについて誠意を持ってご説明をする中で、周辺の住民の方々の理解も、この地区も得られるだろうと考えております。ちょっと説明もできなかったんですが、東京都、神奈川県を含めた京浜工業地帯の有数な一角として日本の経済発展を支えてきた地区なんです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"若干伺いたいと思うんですけれども、それぞれこれは何m2になるのか、教えていただきたい。それから、こんな再開発はほかに見たことがないんですけれども、何でＤ街区だけこんなに細分化されているのか、ご説明いただけますか。","respondent":"青木都市開発課長","answer":"地権者の同意が図れれば、Ｄ街区全体を一体的に開発することが望ましいということで地区計画の方針を定めておるんですけれども、いかんせん。それを適切に誘導していくために、現状では、Ｄ街区についてはこういった形で細分化された地区計画を定めているものです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"別の計画があったけれども、適切に誘導と言いますけれども、こんなに細分化された都市計画というのはほかにあるんでしょうか。いかがか尋ねました。","respondent":"岩田まちづくり事業部長、齋藤住宅課長","answer":"ただ、この地図で見ますと、１街区は非常に小さく見えますけれども、一個一個はかなり大きな土地を持っている地権者です。それから、ちなみに、ここは再開発事業ではございませんので、補助金等は一切出ません。 私のほうからご説明させていただいているように、これを条例で定めないと、建築基準法の例外とはなりません。別表１は、そういった例外的な地域を定めたものでありますけれども、どういった例外を定めたかというのが別表２です。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"３号館の脇の角のところは、最初から外れていましたで構わないんですけれども、それを教えていただきたい。法的に、私はどういう認識を持っていればいいのか、それを説明を求めました。","respondent":"片田建築課長、青木都市開発課長、岩田まちづくり事業部長","answer":"例えば原動機を使って１５０m2以上の作業所を営む工場等については、商業地域の中にはできないといったような内容を決めてあります。… ２点、お答えいたします。要するに運河沿いの歩道として、現段階では、一般の方にあまり積極的にご利用いただけないような状況になっております。 何かうまい工夫がないかということは、今、検討しています。したがって、品川区もああいうふうにするべきだろうとは思っておりますけれども…","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"意見","question":"Ｃ２というところが一番ポイントかなと、今の段階では思っておりますので、ぜひそこら辺をお願いしておきたいと思います。そこら辺も含めて、ぜひやっていただこうかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"三上委員","kind":"質問・要望","question":"現実に都営住宅というのは、耐久年度的に、耐震的な部分はどういう評価になっているんでしょうか。それについて、また品川区としてはどう考えていかれるのか、そこだけ、ちょっとお考えを聞かせていただきたい。","respondent":"齋藤住宅課長","answer":"東五反田二丁目アパートは、昭和４８年に供用を開始しておりまして、２０８戸。今年の夏ぐらいには明らかにするということだったんですけれども、まだ東京都としては大きな方針を示しておりません。","id":"exchange-020"},{"speaker":"三上委員","kind":"質問","question":"ですから、こういうことについての早い検討をまずすべきじゃないかということを、私は思うんです。そこらあたりの見極めをまずやってからじゃないと話は進まないわけですから、それは早急にやるように、いかがなものか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"ここの部分の建て替えと有効活用について共同事業としておやりにならないかということで、何度か交渉したことはあります。住宅局は開発には乗れないという回答があったもので、ここの街区との共同はやめて、現在の街区構成で再開発計画を進めたというふうに聞いております。","id":"exchange-021"},{"speaker":"三上委員","kind":"質問・要望","question":"いかがでしょうかという働きかけをされてもいいんじゃないかと思いますので、機会があれば、そういうふうにしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど、きょうの条例の審議の中にはＧ地区は入っていないんですが、ここがなぜ抜けちゃっているのかということ。一番最初の質問の経過の中で、それはどうなのか、そこを説明を求めました。","respondent":"青木都市開発課長","answer":"Ｆ地区が、当初、検討区域から外れていたものが、いつ入ったのかというご質問ですけれども、もともとＦ地区については開発の予定はありません。都市計画検討をしている中で、進めております小関橋のかけ替え工事に伴って、山手通りと直結できる。","id":"exchange-023"},{"speaker":"井上委員","kind":"意見","question":"そうすると、２番目のＧ地区の件については、整備計画がまだできていないけれども、基本的には、敷地面積の最低限度とか、そういうのはどこかと一緒になるんじゃないかなと思うんですけれどもとの意見を述べました。","respondent":"青木都市開発課長","answer":"Ｇ地区についてのみ地区整備計画を定めるという都市計画変更を行うことによって、何らかの新たな規制なり、緩和なりのルールが定まることになります。現段階では、それを用意していないということです。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"今は用途の規制と、この条例が通って地区計画で条例に明記するということになると、必然的に事業者が出された高さの問題とかはどうなるのか。これはもう、ここには書かれていないですけれども、これがもう通っているということになるんか尋ねました。","respondent":"青木都市開発課長","answer":"ここにつきましては、地区計画の決定と同時に都市再生特別地区の提案も受理されて、特区指定を受けております。ご指摘のとおり、そちらの規制がかかるということで、今回の地区計画に関する条例には記載がないものです。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"御殿山小学校の南に当たるところでは１４３ｍ、ここは高台になっているわけですから、やっぱりすごく不安に思う部分です。住民の方はマックス１４３ｍと考えているものは建てられますよという条件なんですけれども、高さを下げるとか、そういうことは可能なんか尋ねました。","respondent":"青木都市開発課長","answer":"ご審議いただく条例が可決されれば、その範囲内において事業計画が成されるものについて、それ以上の規制誘導するものはございません。調停やあっ旋という制度はありますので、ご意見等の調整は、そういった場を活用するものと考えております。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"特に北品川五丁目の問題では、住民の方々、御殿山小学校に４時間の日影を与える問題でも、行うべきものではないと思います。７,０００万円では、とても庶民には手の届かないものになるわけですから、第７２号議案には反対です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"井上委員","kind":"意見","question":"それから、ここのＦ地域とまちづくりの計画があるなら、はっきりと見えてこないということ。それから、こういった高層を中心にしたまちづくりについて、考え直していく姿勢が必要であるというふうに思いますので、この条例には反対ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"須貝委員","kind":"意見","question":"基礎的なことで聞きたいんですが、認定（その１）と、認定（その２）ですが、一部は削っちゃっているところもあるんですが、同じ区間の場合に、やはり１回取り消して、そしてまた再度認定するような形にしないといけないと思うんですが、そこだけちょっとの意見を述べました。","respondent":"松代管理工事課長","answer":"当初、区間でいきますと、左側のところを廃止しますと、こちらが終点なんですが、１路線としての認定がされておりました。区域決定および供用開始の取り扱いについてというので、今、手続を審議していただいているものです。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"もうちょっとご説明いただきたいのは、目黒川に接している部分の道路を廃止して、さらに親水護岸整備の工事を行って、その後にある親水公園、それからちょっと離れますけれども、親水広場というんですか、この三つの関係がもうひとつよくわからなかったので、もう一度ご説明ほしいと求めました。","respondent":"松代管理工事課長","answer":"一たん廃止手続をしまして、公園としての位置づけをし、公園として管理をする。歩行者の通路としての機能は残りますが、公園になった場合、本来の道路としての機能はないということから廃止をするものです。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜ、そこがよくわからないので、もう一度ご説明ほしいと求めました。そこもちょっとご説明ください。","respondent":"青木都市開発課長","answer":"品川区が進めておりますまちづくりの基本的な方針として、そういった中で、この部分は目黒川の両岸が公園として整備されるところになります。再開発事業の容積率がどう変わるのかというご質問ですけれども、道路の廃止によって…","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜそれを外して公園の一部にするということなんですか。地元から公園をつくってほしいということがあると、なぜわざわざある公道を外してまでつくるのか、教えてほしいと求めました。","respondent":"松代管理工事課長","answer":"これは東五反田地区方針計画ということで、平成４年に建設大臣の承認を得てつくられているものです。道路網、また公園の配置等々、十分計画がされたものとして進められるものと考えております。","id":"exchange-032"},{"speaker":"中塚委員","kind":"意見","question":"右側にある三井不動産の所有で第２地区再開発、１００ｍ級のビル建設、手前に公園をやっているようにしか思えないんです。なぜ、開発事業者のクオリティを上げるための工事になるのかとの意見を述べました。","respondent":"岩田まちづくり事業部長","answer":"本来的には、河川の管理用通路としての機能は、法律上どかすことはできないものです。品川区としては、この地に、過去考えました防災船着場機能を持った船着場といったものを設置するという計画をつくったわけです。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"結局は、裏手にある開発事業のクオリティを上げるために行うものだと、私には思えます。態度も非常にひどいものだという話も伺っている中で、そういうのはほんとうにおかしな話だ、私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"阿部委員","kind":"質問","question":"それとも、工事が進む中で、いつごろからとかという見通しがあれば、教えてください。実際に廃止される、要は新たに認定されずに廃止になるこの区間は、いつからいつまで通れない状態なのか。","respondent":"青木都市開発課長、松代管理工事課長","answer":"着手以降、原則として、工事エリアに入りますと、車両の通行は禁止する予定です。ご指摘のとおり、再開発組合の施工がすべて完了した段階でということになりますので、全体のオープンは平成２２年に入ってからを予定しております。 その供用をとめて工事に入るんですが、歩行者の通行等は、これまでどおり通しながら工事をしたいと考えております。こちらのほうもきちんと指導をして、歩行者の通行等に支障がないような形で、今後詰めていきたいと考えております。","id":"exchange-035"},{"speaker":"阿部委員","kind":"質問","question":"それから、護岸整備が平成２１年ですか、そのころなんでしょうかね、実際に通れるのは。ごめんなさい、ちょっとわからなかったものですから、説明を求めました。","respondent":"岩田まちづくり事業部長","answer":"道路法で定めている３カ月間の管理期間、市街地土木において、人までとめて工事をやるというような横暴な工事は許されません。１週間とか、３日とか、私どもも厳しく指導してやらせたいと思います。","id":"exchange-036"},{"speaker":"阿部委員","kind":"質問","question":"では、基本的には、歩行者、自転車については、工事の進捗にかかわらず通行可能であると。車両の部分は、いかがか尋ねました。","respondent":"松代管理工事課長","answer":"基本的にすぐに工事の準備等に入りますので、車両は通れなくなると考えています。歩行者、自転車等は必ず通れるような歩行者帯というのは設けながら、工事を進めると考えております。","id":"exchange-037"},{"speaker":"阿部委員","kind":"質問","question":"要するに、当面は迂回というか、そのまま通れなくなる。そうすると、再開発が終わるまでの迂回路というのはどういうことになるんか尋ねました。","respondent":"松代管理工事課長","answer":"車両の迂回路は、ここが通行どめになりますと、五反田南公園からの一方通行で入ってまいります。そういったように、若干内陸側へ上っていただいて、直進、もしくは迂回してもらうという形になろうかと思っています。","id":"exchange-038"},{"speaker":"阿部委員","kind":"質問","question":"そうすると、このあたりの内陸部分の車の流れというのは、やっぱり変わってくるのかなと思います。あるいは、場所によっては交通整理員を置くとか、そういったことはお考えか尋ねました。","respondent":"松代管理工事課長、青木都市開発課長","answer":"今、委員からお話がありましたように、１日の交通量というのはほんとうに少ない道路だと思っています。誘導をして、通行等に大きく支障が出ないよう配慮しながら、工事を進めていくように指導してまいりたいと思っています。 現道廃止について検討した際の交通量調査のデータがございまして、その車両が約３５０台、昼間の１２時間で記録されてあります。双方通行にいたしておりますので、こういった点でも、通過交通というのは当面問題ないものと考えておりま…","id":"exchange-039"},{"speaker":"阿部委員","kind":"質問・要望","question":"１日の台数は決して多くないかもしれませんが、朝、それからお昼から夕方にかけては子どもの歩く道でもあります。様子を見ながら、危ないところがないように、ぜひきめ細かな対応をとってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"高さ云々かんぬんへどういった影響があるのか、ないのか、あわせて教えてください。Ｌ字の内側というんですか、右上というんですか、ちょっと教えてほしいと求めました。","respondent":"青木都市開発課長","answer":"ご賛成いただいているかどうかという、まず１点目。それから、この囲まれた地区がなぜ開発されないのかということですけれども、開発の合意に至ってないです。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"私道が公道になるわけですから、どういう形の合意といいますか、ちょっと合意の仕組みをもう少し詳しく教えてほしいと求めました。それから、ぐるっと公道に囲まれると変わるんじゃないのかなと思っておりまして、もう少し詳しく教えてほしいと求めました。","respondent":"岩田まちづくり事業部長、青木都市開発課長","answer":"当然、１人でも反対したら、それはできません。公道にすることに、ああいう方々の同意書が要るかとか、そういう基本的な考え方はありません。 これは既に、区の地区計画を定めるに当たって委員会でご報告をさせていただいて、ご説明しています。ご説明申し上げますと、あるいは、壁面の後退ということを定めております。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"その方の１人に伺ったら、野村不動産の開発事業者のほうから、無償で２ｍくれという話があったそうなんです。どういうお話になっているかわかりませんけれども、そういった経過は区はご存じなのかどうか、ちょっと経過を教えてほしいと求めました。","respondent":"青木都市開発課長","answer":"都市計画法の第１６条の説明会、あるいは第１７条の縦覧手続などを経て、区民の皆様にもご理解いただいているものです。もちろん、地元の方にもご理解いただいているものです。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"この街区は合意が難しいからといって、勝手に自分たちは外されちゃったんだと、いわば排除された形で残ってしまったという話を伺ったんです。片方は１００ｍ、片方は１４３ｍですか、住まわれている方もほんとうに困るという話を伺ってきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"４ｍというのがちょっとごちゃごちゃしたんですけれども、入口だけが６ｍなんですけれども、最終的にずっと６ｍなのかということ。それから、４ｍだと一方通行か、双方通行なのか、最終的にどういう交通の流れになるんか尋ねました。","respondent":"松代管理工事課長","answer":"下のほうに行きまして、右側の方が６ｍの現道です。そうすると、今後の通行形態ですけれども、こちらは双方通行になる予定です。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"左の２ｍというのが、道路となるんですか。その後、今、この計画で、区道としてここだけを認定をし、さらにその後にもう一度、６ｍにしたときに、認定をし直すということになるんか尋ねました。","respondent":"松代管理工事課長","answer":"ただ、今、認定をしようと想定しているところが、４ｍ、６ｍの幅員があるということで、今、民地があるところに２ｍぐらいの現道があります。認定された路線の中の幅員が４ｍから６ｍになると、そのことによって、区道として管理をするといった形になるものです。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"八潮団地再生事業の検討業務委託についてお伺いしたいんですけれども、どのようなことを考えているのか、ご説明ほしいと求めました。それから、八潮地域の問題ですけれども、住民参加の問題をどのように受けているのか、あわせてご説明ください。","respondent":"青木都市開発課長","answer":"予定では、あるいはアンケートなども視野に入れて、住民の意見を把握してまいります。連合自治会のほうで、その方々が、住民側として独自にいろいろな検討を始めていらっしゃるというふうに伺っております。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"引き続き良好な住宅環境の確保が必要なんだという説明がありましたけれども、そのことと、学校と施設の部分の規制を変更するというんですか。その辺について、もう少し詳しく教えていただけますか。","respondent":"青木都市開発課長","answer":"例えば、今回のように小学校を統合することで小学校の数が減った場合には、都市計画の変更が必要になります。あるいは、良好な居住環境はよく保たれている団地ですから、そこの環境を保つために地区計画制度に置き換えていこうということを検討しておりまして。","id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"学校のところをとりわけ見ているわけですから、その辺がよくわからないので、教えていただきたいということです。理屈上は違うものになることだってあり得るわけですから、その辺をどんなふうに考えているのか、教えていただきたいんです。","respondent":"青木都市開発課長","answer":"委員、あるいは団地に住んでいる方々の生活がどうなるのかということも踏まえた上で、当面の都市計画がどうあるべきかというものを検討するものです。Ｂ案が何であるかということを検討している最中でございまして、補正を組ませていただいて、業務を始めするものです。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問","question":"今なぜ、どういう八潮の活性化を図るのかという話し合いが進んでいる中で、いろいろ意見を出し合っているところですよね。今なぜ変更の手続を始めなければいけないのかというところが、どうしてもよくわからないところがありますので、説明を求めました。","respondent":"岩田まちづくり事業部長","answer":"どう使えるかはこれから検討していくんですけれども、再来年４月という、こういうことです。地域の方で検討委員会がつくられておりますので、我々はサポートしていく立場にもありますので、そういう面での活用もしていきたいと考えております。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問・要望","question":"全く別の点で１つ伺いたかったのが、航空法の関係なんですかね、高さの規制が別の要因として定められているという話を聞いたんです。ちょっとその辺の法律のことが僕わからないので、教えていただけますか。","respondent":"阿部都市計画課長","answer":"多分変わってないとは思います。ただ、その辺、詳細は承知しておりませんので、また委員のほうにお伝えしていきたいと思います。","id":"exchange-051"},{"speaker":"中塚委員","kind":"質問・要望","question":"それで、法律上定められている高さが、変な意味、ぐんと変わったりしたらまたそれで問題もありますし、大体今のまま、今の羽田空港の飛行機のラインでも今のままだというのであれば、その中の計画になるし、そこは大事な点だと思いますので、ぜひ報告していただきたいと思っています。","respondent":"阿部都市計画課長","answer":"見方によってはかなり近いところを通る場合も現在ありますので、多分、今申し上げましたけれども、高さの制限は変わっていないとは思います。","id":"exchange-052"},{"speaker":"阿部委員","kind":"質問・要望","question":"これは、建設委員会から離れるのかもしれないんですけれども、こういうのは入札とかで決まっていくものなのでしょうか。それから、させちゃうというようなお話なのか、どういったことをどのように委託するのかちょっと教えてほしいと求めました。","respondent":"青木都市開発課長","answer":"１,５００万円で何をやるかということですけれども、時期はまた検討しますけれども、予定しています。そういった行政協議、あるいは権利者協議ができるための一定の様式に沿った資料を作成してもらうこと、それまでを今年度の業務として予定しています。","id":"exchange-053"},{"speaker":"阿部委員","kind":"質問","question":"逆に言えば、来年度、平成２０年度以降は特にその種の検討業務の委託というのも終わっている状態になっているということになのでしょうか。それとも、また引き続き別の検討業務をさらに委託するというご予定なのか尋ねました。","respondent":"青木都市開発課長","answer":"東京都の審議会に付議していただくように作業を進めたいと考えていますので、そのあたりでのお手伝いもお願いするかもしれません。それは現段階での地元の検討、あるいは庁内での課題抽出の状況によって、平成２０年度以降高まってくると考えています。","id":"exchange-054"},{"speaker":"阿部委員","kind":"質問","question":"ということは、これはもう業務委託契約は終わっているということか尋ねました。","respondent":"青木都市開発課長","answer":"申しわけございません、順番が前後しておりますけれども、契約は成立しております。で、既に業務を着手しております。","id":"exchange-055"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その説明がさっきなかったので、それをもう一回、補正予算だからぜひしていただきたい。それをわかっていれば、その２つ、説明を求めました。","respondent":"伊勢住環境整備担当課長、松代管理工事課長","answer":"来年度じゃなくて今年度それがつくということで、内示変更等により交付が見込まれるため、今回の補正予算を組んだものです。そして、今年度公社から買い戻しを行うです。 今後の予定、スケジュールです。は実施と、こういう形で来年３月末にすべて完成するように進めたいと、このように考えてあります。","id":"exchange-056"},{"speaker":"井上委員","kind":"提案","question":"ちょっと中身に入ってしまうんですけれども、踏み切りについてちょっと、こういう踏み切りの拡幅についても区民の方から要望があり、まちづくり事業部にも提案しているところなんですけれども、踏み切りの拡幅の工事というのはどういう内容なのか、説明していただけますかとの意見を述べました。","respondent":"松代管理工事課長","answer":"対応を協議してきたわけですけれども、先ほど補正の説明にもありましたように、国の補助金等がつくようになりました。当初は５カ所を予定しておったんですが、さらに５カ所を増やそうと、こういった形で進めていきたいと考えているものです。","id":"exchange-057"},{"speaker":"井上委員","kind":"質問・要望","question":"歩く人のスペース確保というところが本当に皆さん要望されていたので、一般財源でも努力をしてほしいなというのは要望はしていましたけれども、ぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"}]},{"id":"topic-03","title":"平成１９年請願第２２号 首都高速中央環状品川線事業の五反田換気所及び出入口に関する請願","agenda":"平成１９年請願第２２号 首都高速中央環状品川線事業の五反田換気所及び出入口に関する請願","exchanges":[{"speaker":"石田（秀）委員","kind":"提案","question":"東京都側が今度提案をされたのは、私も伺いましたが、最初の提案よりは大分細くなったりもしているという。それに対してこたえてほしいという形で、お伺いしたいのは、この方々に対してとの意見を述べました。","respondent":"阿部都市計画課長","answer":"ＴＯＣのほうに移って、検討しているというのを聞いてありますし、あとはインフォメーションセンターをつくって丁寧な説明をしていくと。日曜日は１回ですけれども、第二建設事務所に対しては十分な説明を丁寧にやっていただくということは引き続き求めてまいりたいと考えていま…","id":"exchange-059"},{"speaker":"石田（秀）委員","kind":"質問","question":"全体に、もちろん非常に、連絡会の方々も、いろいろ話をした中で、非常に我々の趣旨も理解してほしいんだという話もされました。それもお話を伺いましたけれども、私どもは非常に趣旨は理解はできると思って、この部分で署名をしております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"阿部委員","kind":"質問","question":"何かしてほしいとか、考えてほしいとか、不信というのがやはり膨らんでしまうと思うんです。例えばこの、２番のデータ公開などについて、区のできることというのはもうちょっとないんか尋ねました。","respondent":"阿部都市計画課長","answer":"先ほど説明して、今回のこの請願が出されましたので、そのデータの件についても申し入れをしています。首都高速道路株式会社のほうからも積極的に、合同連絡会からこういう請願が上がっていますので、公開してくださいという話はしています。","id":"exchange-061"},{"speaker":"阿部委員","kind":"質問・要望","question":"でも、できればあとどのぐらいまではできるかどうかお答えできますよぐらいまで説明があると、またちょっと受けとめ方も違ってくるのではないか。相手が納得する説明というのは必要でもあるし、この請願で最も求められていることじゃないかと、最後は意見で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"中塚委員","kind":"質問・要望","question":"１つ伺いたいのは、１－７のところで書いてあります大気汚染についてです。改めて、大気汚染がどうして改善するとおっしゃるのか、ご説明ほしいと求めました。","respondent":"阿部都市計画課長","answer":"渋滞が解消されることによりまして、環境改善が図られるというふうに東京都等も言っておりますし、私どももそのように認識している。先ほど申し上げましたけれども、大気に対する環境負荷は小さい、非常に小さいというふうに環境影響評価の中で出ているものです。","id":"exchange-063"},{"speaker":"中塚委員","kind":"提案","question":"地域の方々が提案されている４つのアイデア、月刊『おとなりさん』の中にいろいろな公募された提案が、代案というんですか。どういうお考えがあるのか、ちょっとお聞かせいただけますかとの意見を述べました。","respondent":"阿部都市計画課長","answer":"公募案について詳細な検討を加えていただいて、私どもがその公募案に対して、この案はどうだこうだという所見を述べる立場にはないです。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問","question":"将来仕事に就けなかったり、そういった方もいらっしゃるわけですから、生活そのものが破壊されるわけです。こういうぜんそくの苦しみをしっかり受けとめていただいて、環境改善に向けたことが必要ではないかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"井上委員","kind":"提案","question":"区民の方たちの要望ということでは積極的に対応していただきたいと思うんですが、提案するということも東京や事業者がやることだということより区ができることというのがあるのではないかと思うんですけれども、何か検討する余地はありますか尋ねました。","respondent":"阿部都市計画課長","answer":"東京都はそれに対して、供用開始前の大気調査を行いまして、現に換気所についてはそういう最新技術も入るような大きさのものになると聞いてあります。今委員のご提案にございました例えば健康調査とか、そういうものを東京都…","id":"exchange-066"},{"speaker":"井上委員","kind":"質問・要望","question":"そこのところはもう少し、区民に対して目を向けるという意味で、ぜひ全庁的に検討してほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"石田（秀）委員","kind":"意見","question":"結論は出したほうがいいと思います。それで、私どもの感覚では、先ほども言いましたけれども、皆さんの趣旨は非常にわかるので、私は趣旨採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"三上委員","kind":"質問・要望","question":"今の２６号線通りに住んだときのその違いというのは、ディーゼル規制をする以前には、そのことについて発症的な部分というのはなくなった。本日のところ、この請願、私は趣旨採択でお願いしたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"中塚委員","kind":"意見","question":"五反田周辺も含めて今でも大気汚染の中でぜんそくで苦しんでいる方々がいらっしゃる中で、もうこれ以上はごめんだという請願者の趣旨は痛いほど理解できますので、態度といたしましては趣旨採択ということですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"阿部委員","kind":"意見","question":"結論を出すという形でお願いしたいと思います。この請願のことにつきましては理解できることですので、趣旨採択という形でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"須貝委員","kind":"意見","question":"長い期間ですが、話し合いに応じるように今後も引き続き要請してほしいということで、意見を述べします。今回に関しては結論を出すということで、趣旨採択ということでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"}]},{"id":"topic-04","title":"平成１９年請願第２４号 目黒線立体交差事業に伴う洗足架道橋閉鎖のため設置された代替道路の使用方法および改修についての請願","agenda":"平成１９年請願第２４号 目黒線立体交差事業に伴う洗足架道橋閉鎖のため設置された代替道路の使用方法および改修についての請願","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"近所の方々が道路の安全性に疑問を感じたり、危険性を感じると、そういう気持ちはよくわりました。ちょっとお伺いしたいのは、約１.５倍に増えているというお話ですけれども、増えた理由はどのように分析をされているのかお伺いしたいと思います。","respondent":"浜脇街路事業担当課長","answer":"今まで架道橋の下を通っていた分が５００台以上あったわけですから、そういうようなものがあそこが使えなければ違うルートを回ってくるです。こういった少し利用が増えてきたということは想像できますし、今までの利用とは若干変わっているかなというふうに想像しておるところで…","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問","question":"確かにああいう形の道路というのはあまりほかに見たことありませんし、しかも下り坂の左カーブですから、安全性がやはり疑問だなとは思います。それともう一つ伺いたいんですけれども、要は双方向化への変更とありますけれども、この変更はなぜ行ったのか教えていただけますか。","respondent":"浜脇街路事業担当課長","answer":"先ほどのパネルの中で説明いたしましたけれども、結局、今、これまで５００台ぐらいが品川区から目黒区側に抜けるということがございました。ですから、効果があったと思われます。","id":"exchange-074"},{"speaker":"中塚委員","kind":"意見","question":"遠くのものが便利になって、あるいは抜け道として利用されていることへの不安というのは、この趣旨は理解できるものだと僕は思っております。最後は意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"井上委員","kind":"質問・要望","question":"２０分ぐらいだったでしょうか、本当にあの道路が必要なのかどうなのかということを、危険だということは十分わかると思うんです。それがどういう車なのかというのはこのデータだけではわかりませんけれども、そういう意味では、ぜひ考えてほしいと求めました。","respondent":"浜脇街路事業担当課長","answer":"ご説明もし、私どもが当初予定していた１０８台にはいきませんけれども、それなりの機能を持ってこの代替道路は使われていただいているという認識です。","id":"exchange-076"},{"speaker":"阿部委員","kind":"質問","question":"１点、あの一連の装備と言ったらいいんでしょうか、計算されてみたことはありますか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"騒音、そういうものと思ってやっている部分がありますので、そういった意味では普通の道路づくりのときなんかよりかは若干かかっているのは事実です。工費については東京都はじめ４者で拠出しているものですから、なるべく…","id":"exchange-077"},{"speaker":"阿部委員","kind":"質問・要望","question":"そういう意味で、この地域はそもそもバランスを失いつつあるのではないかというような、これ、ごめんなさい、意見として。このエリアの方々から要望として出されたといういきさつがあったのでないかという、ちょっとその辺、確認させてください。","respondent":"浜脇街路事業担当課長","answer":"ある意味で説明会等でご意見、その代替道路についても私どもとして、事業者側としてつくるということが決定しているということになります。はつくりませんでしたので、ちょっと場所を変えてつくるということで、なったです。","id":"exchange-078"},{"speaker":"阿部委員","kind":"意見","question":"やはり地域以外の方もそれぞれに使うためにあるからこそ道路であるということもやはり踏まえなければいけないだろうなと、すみません、意見ばかりでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"一つひとつクリアをしていこうということで、いろいろな要望を伺いながら、何度も何度も書き直して変わってきた。そのときお話を伺って、今何人ぐらいかというのも伺ったけれども、しているならしていると言って。","respondent":"浜脇街路事業担当課長、岩田まちづくり事業部長","answer":"今でも説明していますし、私どもの説明について、理解したといってくれない状況ではあります。この方に対しても、それ以外の方に対しても対応はしておりますけれども、なかなか聞いてくれない。 基本的にはここは１日当たり５００台くらい抜けていたのが、結果的には現在は通過交通はこの中にどうも入ってきていないようです。ですから、地域もこういう規制的な利便性のことから考えれば…","id":"exchange-080"},{"speaker":"井上委員","kind":"質問","question":"洗足架道橋をぜひ閉鎖をしないでほしいという状況は、皆さんの思われていたような、希望していたものではないということも当時はいえると思うんです。ですから、ここがなくなって本当に困るんですかということもちゃんと調査をする必要があって、お話をいただければなと思います。","respondent":"浜脇街路事業担当課長、岩田まちづくり事業部長","answer":"というので、かなりの、地区外の方から見れば通過交通だったことは事実。この台数は６３台、５４４台はもう来ていないわけですから、まずは地区交通として必要だということについては間違いないところだと思ってあります。 私の説明が先ほど悪かったかもしれませんけれども、通過交通が便利ですから、この地域に用もない車が通り抜け車両としてどんどん通っていた。別の便利な道を通過交通は探しますから、そちらへ散るだろうと普通には考えていましたけれど…","id":"exchange-081"},{"speaker":"三上委員","kind":"確認","question":"１つ、まず、確認したいのは、この請願文というのは、項目については前回と同じですか、それとも違うようになっていますか。","respondent":"浜脇街路事業担当課長","answer":"私の見た限りでは、ほとんど違っております。この代替道路、今回は代替道路とこの道路について絞っている部分が、前回２月に請願したときとは若干絞れてお話が出ているです。","id":"exchange-082"},{"speaker":"三上委員","kind":"質問","question":"絞れてきたということは、請願に通すなという話と、通っている現実を考えて、ああだよ、こうだよ、改善してくれというのと両方入っていたということでの、問題点としては不都合が生じたというふうに理解していいのか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"私どもが区民の声にも回答しているんですが、その回答について答えてある部分については理解をしていただいて、こちらのほうにまとまって話が出ているというふうに思われます。","id":"exchange-083"},{"speaker":"三上委員","kind":"質問","question":"請願項目の１つ目として、こういうことになると、遮断しないために誤って通る車というのは必ずありますよね。そこらあたりというのは、交通管理者的な考え方からいったら、判断というのはどうなるんか尋ねました。","respondent":"浜脇街路事業担当課長、松嶋交通安全担当課長","answer":"先ほど２０kmという話がありました、最小限のそういった規制といいますか、何かそういったものをつけ加えて安全性を確保しているというふうに思ってあります。 つまりさくを出すというのは、それは歩行者専用道路ということで交通規制をかければ、それは可能です。どうするかということであれば、部分的な対応も時には必要かと、そういうふうに考えます。","id":"exchange-084"},{"speaker":"三上委員","kind":"意見","question":"もう一つ聞かせてもらいたいんですが、特に、「生活道路」という言葉がさっきから出てくるんだけれども、生活道路というのはそこに住んでいる方たちが利用する形だけを生活道路と表現するのかどうかとの意見を述べました。","respondent":"岩田まちづくり事業部長","answer":"したがって、ここの道路を例えば八潮とか大井の人が通ることも自由ですし、道路というのはそういう性格のものだと。区内には４ｍ道路はいっぱいございまして、ここは一方通行まで変更しておりますので、これは不可能だと思います。","id":"exchange-085"},{"speaker":"三上委員","kind":"質問","question":"２番目のほうで、先ほどの担当課長の説明でいうと、要するに工事の期間中は段差的な部分を解消するためにちょっと盛土した部分がある。だけれども、そういうことの説明で間違いないとするならば、これは元の高さ以下には戻っているということで理解していいわけなんか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"資料２のときにご説明しましたように、６cmほど高くなって、東急が工事をするときにはこのように１３.５％まで下げていただいたと。ですから、私どもは決してこの盛土をしたのではなくて、一時期そういったことがあったというのはありました。","id":"exchange-086"},{"speaker":"三上委員","kind":"質問・要望","question":"そうすると、この請願を求めるというのは、これはもう願意としては成立していると判断していいのか。","respondent":"浜脇街路事業担当課長","answer":"雪の日に若干人が、歩行者が脇から歩けるような道をつくっておかないと危険かなと思って、それをどこにするかというのが非常に悩みの種です。それについては警視庁と今後とも相談をしながら、やっていこうかなと考えています。","id":"exchange-087"},{"speaker":"三上委員","kind":"意見","question":"やはり雨でも、雪でも、どういったときでも転ばないで少なくても歩ける方法論だけはきちんと整えておくほうがいいのかな。それは私も十分理解できる話だと、こういうふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-088"},{"speaker":"石田（秀）委員","kind":"質問","question":"先ほどもいろいろ、るる過去からの話も伺ったし、行政側の非常に、そういう意味ではしっかりと対応していただいて、本当に、私は、よくその部分は対応しているなと思うぐらい、住民の方に対し、２番のこともありますし、過去からの経緯もあるということも考えて、私は結論的には不採択。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"},{"speaker":"三上委員","kind":"意見","question":"先ほども一部申し上げましたけれども、本日結論を出すということについては賛成します。態度といたしましては、１項目、２項目ともに、ある意味では願意に沿い難いということであるならば、これは不採択というふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"},{"speaker":"須貝委員","kind":"意見","question":"できれば、一部の住民の方が交通事故等を心配されているということならば、ここの区間だけできるだけ安全対策を講じて欲しいなと思います。今回、結論を、長年やっているということで、結論を出すということで、私も同様に不採択ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-091"},{"speaker":"井上委員","kind":"意見","question":"雨の日、雪の日というところも、これが解消されているというふうにはとても思えない。趣旨には賛同できますので、態度は趣旨採択ということですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-092"}]},{"id":"topic-05","title":"平成１９年請願第３３号 大井町駅東口改札口営業時間延長に関する請願","agenda":"平成１９年請願第３３号 大井町駅東口改札口営業時間延長に関する請願","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"質問はあまりないんですが、今おっしゃったように、３月２日に来られて、４月１日から実施して、４月中旬行政側から話を伺いました。話し合いの場にも乗らないような状態だから、それはもう採択して、やるというぐらいの感じだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-093"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ質問ですけれども、もしわかればですけれども、ＪＲ東日本はなぜここを早く閉めちゃうのか。その理由はどのように把握されているのか、ちょっと説明していただきたい。","respondent":"阿部都市計画課長","answer":"それはＪＲ東日本も公益鉄道事業者ですけれども、民営会社の部分もありますので、そういう意味では経営努力を会社として求められていると。その一環として、こういう形というふうに理解しております。","id":"exchange-094"},{"speaker":"中塚委員","kind":"意見","question":"鉄道事業者として、本当に公共性の高い事業を行っている者として、結局利用者の利便性も考えない、また地域の方々の影響も考えない、こういうＪＲの姿勢というのは本当に許せないなと私も感じておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-095"},{"speaker":"三上委員","kind":"質問・要望","question":"元に戻していただきたいという、元に戻していただきたいことを大前提とした上で、どうしたらいいか。そういう意味であっては継続する、それから採択する、そのどちらかしかないと思うので、態度については、本日出すということであれば採択で結構です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-096"},{"speaker":"中塚委員","kind":"意見","question":"きょう結論を出すということと、態度は採択です。理由は、大井町東口改札口を短縮をするのは本当に全面撤回すべきだと思うからですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-097"},{"speaker":"阿部委員","kind":"意見","question":"採択。やはり品川区としての意思というのをきちんと明確にあらわして、その上で交渉すべきと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-098"},{"speaker":"須貝委員","kind":"意見","question":"議会で強く採択してやるということも必要だと思うんですけれども、やはりまず交渉をできるだけ努力を、さらなる努力をお願いしたいと思います。今回結論を出すということなので、区民の利便性を考えたらいたしかたないというふうに思いますが、ちょっと考えますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-099"},{"speaker":"井上委員","kind":"質問・要望","question":"やはり今区のほうから要望書を提出している中で、判断する、しないというところでは同じなんです。まあ、どうしても採択ということであれば、できれば継続にしていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-100"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/325823?Template=document&Id=3888#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":84662,"voices":252}}]);
